insert into public.kanjis (id, character, han_viet, meanings, onyomi, kunyomi, stroke_count, jlpt_level, examples) values ('途', '途', 'ĐỒ', '["giữa đường","con đường"]'::jsonb, '["ト"]'::jsonb, '[]'::jsonb, 10, 'N3', '[{"vocabularyId":95070,"word":"途中","hiragana":"とちゅう","meaning":"giữa đường"},{"vocabularyId":95071,"word":"用途","hiragana":"ようと","meaning":"công dụng"}]'::jsonb) on conflict (id) do update set character = excluded.character, han_viet = excluded.han_viet, meanings = excluded.meanings, onyomi = excluded.onyomi, kunyomi = excluded.kunyomi, stroke_count = excluded.stroke_count, jlpt_level = excluded.jlpt_level, examples = excluded.examples;
