insert into public.kanjis (id, character, han_viet, meanings, onyomi, kunyomi, stroke_count, jlpt_level, examples) values ('連', '連', 'LIÊN', '["liên tiếp","dẫn theo"]'::jsonb, '["レン"]'::jsonb, '["つれる","つらなる"]'::jsonb, 10, 'N3', '[{"vocabularyId":95110,"word":"連絡","hiragana":"れんらく","meaning":"liên lạc"},{"vocabularyId":95111,"word":"連休","hiragana":"れんきゅう","meaning":"kỳ nghỉ dài"}]'::jsonb) on conflict (id) do update set character = excluded.character, han_viet = excluded.han_viet, meanings = excluded.meanings, onyomi = excluded.onyomi, kunyomi = excluded.kunyomi, stroke_count = excluded.stroke_count, jlpt_level = excluded.jlpt_level, examples = excluded.examples;
insert into public.kanjis (id, character, han_viet, meanings, onyomi, kunyomi, stroke_count, jlpt_level, examples) values ('絡', '絡', 'LẠC', '["liên lạc","vướng vào"]'::jsonb, '["ラク"]'::jsonb, '["からむ"]'::jsonb, 12, 'N3', '[{"vocabularyId":95120,"word":"連絡","hiragana":"れんらく","meaning":"liên lạc"}]'::jsonb) on conflict (id) do update set character = excluded.character, han_viet = excluded.han_viet, meanings = excluded.meanings, onyomi = excluded.onyomi, kunyomi = excluded.kunyomi, stroke_count = excluded.stroke_count, jlpt_level = excluded.jlpt_level, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L01-WA-DESU', 'MINNA_N5', 'L01', 'N5', 'N1 は N2 です', 'N1 + は + N2 + です', 'N1 là N2', 'Mẫu câu khẳng định cơ bản nhất. Trợ từ 「は」 (đọc là "wa") đánh dấu chủ đề của câu, 「です」 đặt ở cuối câu thể hiện sự lịch sự và khẳng định.', 'Chữ 「は」 khi làm trợ từ chủ đề luôn đọc là 「わ」 (wa).', '[{"japanese":"私はベトナム人です。","hiragana":"わたしはベトナムじんです。","vietnamese":"Tôi là người Việt Nam."},{"japanese":"田中さんは銀行員です。","hiragana":"たなかさんはぎんこういんです。","vietnamese":"Anh Tanaka là nhân viên ngân hàng."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L01-JA-ARIMASEN', 'MINNA_N5', 'L01', 'N5', 'N1 は N2 じゃありません', 'N1 + は + N2 + じゃありません', 'N1 không phải là N2', 'Dạng phủ định lịch sự của 「です」 dùng để phủ nhận danh từ ở hiện tại hoặc tương lai.', 'Trong văn viết trang trọng dùng 「ではありません」 thay cho 「じゃありません」.', '[{"japanese":"私は先生じゃありません。","hiragana":"わたしはせんせいじゃありません。","vietnamese":"Tôi không phải là giáo viên."},{"japanese":"ミラーさんは学生じゃありません。","hiragana":"ミラーさんはがくせいじゃありません。","vietnamese":"Anh Miller không phải là học sinh."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L01-KA', 'MINNA_N5', 'L01', 'N5', '～ですか (Câu nghi vấn)', 'N1 + は + N2 + ですか', '… có phải không?', 'Thêm trợ từ 「か」 vào cuối câu khẳng định (và lên giọng nhẹ) để tạo câu hỏi lịch sự.', 'Văn bản tiếng Nhật chuẩn dùng dấu chấm tròn 「。」 cuối câu hỏi.', '[{"japanese":"あなたは会社員ですか。","hiragana":"あなたはかいしゃいんですか。","vietnamese":"Anh là nhân viên công ty phải không?"},{"japanese":"お名前は何ですか。","hiragana":"おなまえはなんですか。","vietnamese":"Tên của bạn là gì?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L01-MO', 'MINNA_N5', 'L01', 'N5', 'N1 も N2 です', 'N1 + も + N2 + です', 'N1 cũng là N2', 'Trợ từ 「も」 (cũng) thay thế hoàn toàn cho 「は」 khi chủ thể mới có cùng đặc điểm giống chủ thể vừa nhắc trước đó.', 'Không bao giờ dùng 「はも」 — luôn bỏ 「は」 thay bằng 「も」.', '[{"japanese":"グプタさんも社員です。","hiragana":"グプタさんもしゃいんです。","vietnamese":"Anh Gupta cũng là nhân viên công ty."},{"japanese":"私もさくら大学の学生です。","hiragana":"わたしもさくらだいがくのがくせいです。","vietnamese":"Tôi cũng là sinh viên đại học Sakura."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L01-NO', 'MINNA_N5', 'L01', 'N5', 'N1 の N2', 'N1 + の + N2', 'N2 của N1 / N2 thuộc về N1', 'Trợ từ 「の」 nối hai danh từ với nhau, trong đó N1 bổ nghĩa cho N2 (sở hữu, nơi trực thuộc hoặc chủ đề).', 'Thứ tự ngược với tiếng Việt: danh từ chính nằm phía sau 「の」.', '[{"japanese":"カリナさんは富士大学の学生です。","hiragana":"カリナさんはふじだいがくのがくせいです。","vietnamese":"Chị Karina là sinh viên đại học Fuji."},{"japanese":"これは日本語の本です。","hiragana":"これはにほんごのほんです。","vietnamese":"Đây là sách tiếng Nhật."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L02-KORE-SORE-ARE', 'MINNA_N5', 'L02', 'N5', 'これ／それ／あれ は N です', 'これ／それ／あれ + は + N + です', 'Cái này / Cái đó / Cái kia là N', 'Đại từ chỉ vật dùng độc lập làm chủ ngữ: 「これ」 (gần người nói), 「それ」 (gần người nghe), 「あれ」 (xa cả hai).', 'Khi trả lời câu hỏi dùng 「これ」, người nghe đổi sang 「それ」 và ngược lại.', '[{"japanese":"これは私の辞書です。","hiragana":"これはわたしのじしょです。","vietnamese":"Cái này là từ điển của tôi."},{"japanese":"それは日本のカメラです。","hiragana":"それはにほんのカメラです。","vietnamese":"Cái đó là máy ảnh của Nhật."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L02-KONO-SONO-ANO', 'MINNA_N5', 'L02', 'N5', 'この／その／あの + N', 'この／その／あの + N', 'N này / N đó / N kia', 'Từ chỉ thị bổ nghĩa trực tiếp cho danh từ đứng ngay phía sau nó.', 'Khác với 「これ」 đứng một mình, 「この」 bắt buộc phải có danh từ đi kèm phía sau.', '[{"japanese":"この傘は私のです。","hiragana":"このかさはわたしのです。","vietnamese":"Cái ô này là của tôi."},{"japanese":"あのかばんは誰のですか。","hiragana":"あのかばんはだれのですか。","vietnamese":"Cái cặp kia là của ai vậy?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L02-KA-KA', 'MINNA_N5', 'L02', 'N5', '～ですか、～ですか (Câu hỏi lựa chọn)', 'N1ですか、N2ですか', 'Là A hay là B?', 'Đặt hai mệnh đề nghi vấn nối tiếp nhau để hỏi lựa chọn giữa hai phương án.', 'Không trả lời bằng 「はい／いいえ」 mà nêu thẳng phương án đúng.', '[{"japanese":"これは「い」ですか、「り」ですか。","hiragana":"これは「い」ですか、「り」ですか。","vietnamese":"Chữ này là chữ \"i\" hay là chữ \"ri\"?"},{"japanese":"それはボールペンですか、鉛筆ですか。","hiragana":"それはボールペンですか、えんぴつですか。","vietnamese":"Cái đó là bút bi hay bút chì?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L03-KOKO-SOKO-ASOKO', 'MINNA_N5', 'L03', 'N5', 'ここ／そこ／あそこ は [Địa điểm] です', 'ここ／そこ／あそこ + は + N + です', 'Chỗ này / Chỗ đó / Chỗ kia là…', 'Đại từ chỉ địa điểm theo khoảng cách: ここ (nơi người nói đứng), そこ (nơi người nghe đứng), あそこ (nơi xa cả hai).', 'Cách nói lịch sự hơn tương ứng là 「こちら・そちら・あちら」.', '[{"japanese":"ここは日本語の教室です。","hiragana":"ここはにほんごのきょうしつです。","vietnamese":"Đây là phòng học tiếng Nhật."},{"japanese":"あそこは郵便局です。","hiragana":"あそこはゆうびんきょくです。","vietnamese":"Đằng kia là bưu điện."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L03-DOKO-DOCHIRA', 'MINNA_N5', 'L03', 'N5', 'N は どこ／どちら ですか', 'N + は + どこ／どちら + ですか', 'N ở đâu? / Đất nước·công ty nào?', 'Dùng để hỏi vị trí của vật/người/nơi chốn. 「どちら」 lịch sự hơn và thường dùng hỏi quê quán, trường học, công ty.', 'Khi hỏi giá tiền dùng 「いくらですか」: このネクタイはいくらですか。(Cà vạt này bao nhiêu tiền?)', '[{"japanese":"お手洗いはどこですか。","hiragana":"おてあらいはどこですか。","vietnamese":"Nhà vệ sinh ở đâu ạ?"},{"japanese":"会社はどちらですか。","hiragana":"かいしゃはどちらですか。","vietnamese":"Quý công ty ở đâu/tên gì ạ?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L03-ORIGIN-NO', 'MINNA_N5', 'L03', 'N5', 'N1 (Quốc gia/Hãng) の N2', 'N1(xuất xứ) + の + N2', 'N2 của nước/hãng N1', 'Dùng trợ từ 「の」 chỉ xuất xứ sản phẩm hoặc thương hiệu sản xuất.', 'Câu hỏi tương ứng: 「どこの N ですか」(N của nước/hãng nào?).', '[{"japanese":"これはイタリアの靴です。","hiragana":"これはイタリアのくつです。","vietnamese":"Đây là đôi giày của Ý."},{"japanese":"この腕時計はスイスの時計です。","hiragana":"このうでどけいはスイスのとけいです。","vietnamese":"Chiếc đồng hồ đeo tay này là của Thụy Sĩ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L04-IMA-JI-FUN', 'MINNA_N5', 'L04', 'N5', '今 ～時 ～分 です', '今 + ～時 + ～分 + です', 'Bây giờ là … giờ … phút', 'Cách nói giờ phút trong tiếng Nhật. Lưu ý các giờ đặc biệt: 4時 (よじ), 7時 (しちじ), 9時 (くじ) và biến âm phút (ぷん／ふん).', 'Dùng 「午前」(sáng) và 「午後」(chiều) đặt trước giờ; 「半」(はん) nghĩa là rưỡi (30 phút).', '[{"japanese":"今、午前八時十五分です。","hiragana":"いま、ごぜんはちじじゅうごふんです。","vietnamese":"Bây giờ là 8 giờ 15 phút sáng."},{"japanese":"ニューヨークは今、午後九時半です。","hiragana":"ニューヨークはいま、ごごくはんじです。","vietnamese":"New York bây giờ là 9 giờ rưỡi tối."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L04-V-MASU-TENSE', 'MINNA_N5', 'L04', 'N5', 'Vます / Vません / Vました / Vませんでした', 'Vます / Vません / Vました / Vませんでした', 'Chia 4 thì lịch sự của động từ', 'Động từ thể lịch sự chia theo hiện tại/tương lai (ます / ません) và quá khứ (ました / ませんでした).', 'Dùng cùng dạng 「ます」 cho cả thói quen hiện tại lẫn hành động tương lai.', '[{"japanese":"毎朝六時に起きます。","hiragana":"まいあさろくじにおきます。","vietnamese":"Mỗi sáng tôi thức dậy lúc 6 giờ."},{"japanese":"昨日、勉強しませんでした。","hiragana":"きのう、べんきょうしませんでした。","vietnamese":"Hôm qua tôi đã không học bài."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L04-TIME-NI-V', 'MINNA_N5', 'L04', 'N5', 'N (Thời điểm cụ thể) に V', 'N(thời gian) + に + V', 'Làm V vào lúc…', 'Trợ từ 「に」 gắn sau mốc thời gian có con số cụ thể (giờ, ngày, tháng, năm) để chỉ thời điểm hành động xảy ra.', 'Không dùng 「に」 sau các từ chỉ thời gian tương đối như 今日、あした、きのう、毎日、今朝.', '[{"japanese":"毎晩十一時に寝ます。","hiragana":"まいばんじゅういちじにねます。","vietnamese":"Mỗi tối tôi đi ngủ lúc 11 giờ."},{"japanese":"日曜日に友達と会います。","hiragana":"にちようびにともだちとあいます。","vietnamese":"Chủ nhật tôi gặp bạn bè."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L04-KARA-MADE', 'MINNA_N5', 'L04', 'N5', 'N1 から N2 まで', 'N1 + から + N2 + まで', 'Từ N1 đến N2', 'Biểu thị điểm bắt đầu (から) và điểm kết thúc (まで) về thời gian hoặc không gian.', 'Có thể dùng riêng lẻ 「から」 hoặc 「まで」 tùy ngữ cảnh.', '[{"japanese":"銀行は九時から三時までです。","hiragana":"ぎんこうはくじからさんじまでです。","vietnamese":"Ngân hàng mở cửa từ 9 giờ đến 3 giờ."},{"japanese":"昼休みは十二時から一時までです。","hiragana":"ひるやすみはじゅうにじからいちじまでです。","vietnamese":"Giờ nghỉ trưa từ 12 giờ đến 1 giờ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L05-E-IKIMASU', 'MINNA_N5', 'L05', 'N5', 'N (Địa điểm) へ 行きます／来ます／帰ります', 'N(địa điểm) + へ + 行きます', 'Đi đến / Đến / Trở về địa điểm N', 'Trợ từ 「へ」 (đọc là "e") chỉ phương hướng di chuyển dùng cùng các động từ 行きます (đi), 来ます (đến), 帰ります (về).', 'Trợ từ 「へ」 luôn đọc là 「え」(e), không đọc là "he". Khi phủ định toàn bộ dùng 「どこへも行きません」.', '[{"japanese":"明日、京都へ行きます。","hiragana":"あした、きょうとへいきます。","vietnamese":"Ngày mai tôi đi Kyoto."},{"japanese":"来年、国へ帰ります。","hiragana":"らいねん、くにへかえります。","vietnamese":"Năm sau tôi sẽ về nước."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L05-DE-VEHICLE', 'MINNA_N5', 'L05', 'N5', 'N (Phương tiện) で 行きます', 'N(phương tiện) + で + V', 'Đi bằng phương tiện N', 'Trợ từ 「で」 gắn sau danh từ phương tiện giao thông để chỉ cách thức di chuyển.', 'Riêng "đi bộ" dùng 「歩いて」(あるいて), không dùng 「で」.', '[{"japanese":"毎日電車で会社へ行きます。","hiragana":"まいにちでんしゃでかいしゃへいきます。","vietnamese":"Mỗi ngày tôi đi công ty bằng tàu điện."},{"japanese":"飛行機で日本へ来ました。","hiragana":"ひこうきでにほんへきました。","vietnamese":"Tôi đến Nhật bằng máy bay."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L05-TO-PERSON', 'MINNA_N5', 'L05', 'N5', 'N (Người/Động vật) と V', 'N(người) + と + V', 'Làm V cùng với N', 'Trợ từ 「と」 biểu thị người cùng thực hiện hành động. Nếu làm một mình thì dùng 「ひとりで」 (không có と).', 'Câu hỏi tương ứng: 「だれと行きますか」(Đi cùng với ai?).', '[{"japanese":"家族と東京へ来ました。","hiragana":"かぞくととうきょうへきました。","vietnamese":"Tôi đã đến Tokyo cùng gia đình."},{"japanese":"友達と映画を見ます。","hiragana":"ともだちとえいがをみます。","vietnamese":"Tôi xem phim cùng với bạn."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L06-WO-V', 'MINNA_N5', 'L06', 'N5', 'N を V (Tân ngữ trực tiếp)', 'N + を + V', 'Thực hiện hành động V lên N', 'Trợ từ 「を」 (đọc là "o") đứng sau danh từ chịu tác động trực tiếp của tha động từ (ăn, uống, đọc, xem, mua…).', 'Chữ 「を」 chỉ dùng làm trợ từ trong tiếng Nhật hiện đại. Hỏi "làm gì": 「何をしますか」.', '[{"japanese":"毎朝コーヒーを飲みます。","hiragana":"まいあさコーヒーをのみます。","vietnamese":"Mỗi sáng tôi uống cà phê."},{"japanese":"図書館で新聞を読みます。","hiragana":"としょかんでしんぶんをよみます。","vietnamese":"Tôi đọc báo ở thư viện."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L06-DE-PLACE', 'MINNA_N5', 'L06', 'N5', 'N (Địa điểm) で V', 'N(địa điểm) + で + V', 'Làm V tại địa điểm N', 'Trợ từ 「で」 chỉ nơi diễn ra một hành động cụ thể (ăn ở nhà hàng, mua ở siêu thị, học ở thư viện…).', 'Phân biệt với 「へ」 (hướng di chuyển) và 「に」 (nơi tồn tại ở Bài 10).', '[{"japanese":"食堂で昼ご飯を食べます。","hiragana":"しょくどうでひるごはんをたべます。","vietnamese":"Tôi ăn trưa ở nhà ăn."},{"japanese":"駅の前のスーパーで果物を買います。","hiragana":"えきのまえのスーパーでくだものをかいます。","vietnamese":"Tôi mua trái cây ở siêu thị trước ga."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L06-V-MASENKA', 'MINNA_N5', 'L06', 'N5', 'Vませんか (Lời mời lịch sự)', 'Vませんか', 'Cùng làm V nhé? / Anh chị có muốn… không?', 'Dạng câu hỏi phủ định dùng để mời rủ một cách lịch sự, tôn trọng ý kiến người nghe.', 'Đồng ý thường đáp: 「ええ、いいですね」(Vâng, hay quá!) hoặc 「はい、行きましょう」.', '[{"japanese":"一緒に京都へ行きませんか。","hiragana":"いっしょにきょうとへいきませんか。","vietnamese":"Cùng đi Kyoto với tôi không?"},{"japanese":"喫茶店でお茶を飲みませんか。","hiragana":"きっさてんでおちゃをのみませんか。","vietnamese":"Vào quán uống chút trà nhé?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L06-V-MASHOU', 'MINNA_N5', 'L06', 'N5', 'Vましょう (Đề nghị / Hưởng ứng)', 'Vましょう', 'Chúng ta cùng làm V nào!', 'Dùng để chủ động đề xuất cùng làm gì đó hoặc hưởng ứng tích cực lại lời mời.', 'Sắc thái thân mật và dứt khoát hơn 「Vませんか」.', '[{"japanese":"少し休みましょう。","hiragana":"すこしやすみましょう。","vietnamese":"Hãy nghỉ ngơi một chút nào."},{"japanese":"十二時ですから昼ご飯を食べましょう。","hiragana":"じゅうにじですからひるごはんをたべましょう。","vietnamese":"12 giờ rồi, chúng ta cùng ăn trưa thôi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L07-DE-TOOL', 'MINNA_N5', 'L07', 'N5', 'N (Công cụ / Ngôn ngữ) で V', 'N(công cụ) + で + V', 'Làm V bằng công cụ / ngôn ngữ N', 'Trợ từ 「で」 chỉ công cụ, vật dụng hoặc ngôn ngữ được dùng để thực hiện hành động.', 'Hỏi cách nói một từ bằng ngôn ngữ khác: 「"Thank you" は日本語で何ですか」.', '[{"japanese":"お箸でご飯を食べます。","hiragana":"おはしでごはんをたべます。","vietnamese":"Tôi ăn cơm bằng đũa."},{"japanese":"日本語でレポートを書きます。","hiragana":"にほんごでレポートをかきます。","vietnamese":"Tôi viết báo cáo bằng tiếng Nhật."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L07-AGEMASU', 'MINNA_N5', 'L07', 'N5', 'N1 (Người) に N2 (Vật) を あげます', 'N1(người) + に + N2 + を + あげます', 'Tặng / Cho N1 vật N2', 'Dùng khi chủ ngữ (tôi hoặc người khác) trao vật, tiền, hay dạy/gửi thông tin cho người nhận (đánh dấu bằng 「に」).', 'Không dùng 「あげます」 khi người nhận là bản thân mình (「私に」).', '[{"japanese":"誕生日に妹に時計をあげました。","hiragana":"たんじょうびにいもうとにとけいをあげました。","vietnamese":"Sinh nhật tôi đã tặng em gái đồng hồ."},{"japanese":"山田さんは木村さんに花をあげました。","hiragana":"やまださんはきむらさんにはなをあげました。","vietnamese":"Anh Yamada đã tặng hoa cho chị Kimura."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L07-MORAIMASU', 'MINNA_N5', 'L07', 'N5', 'N1 (Người/Tổ chức) に／から N2 を もらいます', 'N1 + に／から + N2 + を + もらいます', 'Nhận N2 từ N1', 'Dùng khi chủ ngữ nhận vật (もらいます), mượn (借ります) hoặc học (習います) từ ai đó.', 'Nếu nguồn cho là tổ chức (ngân hàng, công ty, trường học) thì chỉ dùng 「から」, không dùng 「に」.', '[{"japanese":"先生に辞書をもらいました。","hiragana":"せんせいにじしょをもらいました。","vietnamese":"Tôi đã nhận được từ điển từ thầy giáo."},{"japanese":"友達からきれいな写真をもらいました。","hiragana":"ともだちからきれいなしゃしんをもらいました。","vietnamese":"Tôi nhận được bức ảnh đẹp từ bạn."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L07-MOU-MASHITA', 'MINNA_N5', 'L07', 'N5', 'もう Vました / まだです', 'もう + Vました', 'Đã làm rồi / Vẫn chưa', '「もう」 đi với quá khứ 「Vました」 hỏi/khẳng định việc đã hoàn thành chưa. Phủ định trả lời 「いいえ、まだです」(Chưa ạ).', 'Tuyệt đối không trả lời 「いいえ、食べませんでした」 cho câu hỏi 「もう～ましたか」.', '[{"japanese":"もう昼ご飯を食べましたか。はい、食べました。","hiragana":"もうひるごはんをたべましたか。はい、たべました。","vietnamese":"Bạn đã ăn trưa chưa? Rồi, tôi ăn rồi."},{"japanese":"もう荷物を送りましたか。いいえ、まだです。","hiragana":"もうにもつをおくりましたか。いいえ、まだです。","vietnamese":"Bạn gửi hành lý chưa? Chưa, vẫn chưa."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L08-ADJ-NA', 'MINNA_N5', 'L08', 'N5', 'Tính từ đuôi な (Khẳng định / Phủ định)', 'N + は + Adj-な + です／じゃありません', 'N thì [Adj-な] / không [Adj-な]', 'Tính từ đuôi な khi kết câu bỏ 「な」 cộng 「です」; phủ định cộng 「じゃありません」 (giống danh từ).', 'Lưu ý: きれい (đẹp/sạch) và ゆうめい (nổi tiếng) kết thúc bằng "i" nhưng là tính từ đuôi な!', '[{"japanese":"京都は静かな町です。とても綺麗です。","hiragana":"きょうとはしずかなまちです。とてもきれいです。","vietnamese":"Kyoto là thành phố yên tĩnh. Rất đẹp."},{"japanese":"図書館の夜は賑やかじゃありません。","hiragana":"としょかんのよるはにぎやかじゃありません。","vietnamese":"Thư viện buổi tối không náo nhiệt."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L08-ADJ-I', 'MINNA_N5', 'L08', 'N5', 'Tính từ đuôi い (Khẳng định / Phủ định)', 'Adj(-い) + くないです', 'N thì [Adj-い] / không [Adj-い]', 'Tính từ đuôi い giữ nguyên 「い」 + 「です」. Phủ định: bỏ 「い」 cuối, thêm 「くないです」.', 'Ngoại lệ duy nhất: 「いいです」(tốt) đổi thành 「よくないです」(không tốt).', '[{"japanese":"日本の夏はとても暑いです。","hiragana":"にほんのなつはとてもあついです。","vietnamese":"Mùa hè ở Nhật rất nóng."},{"japanese":"この辞書はそんなに高くないです。","hiragana":"このじしょはそんなにたかくないです。","vietnamese":"Cuốn từ điển này không đắt lắm."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L08-ADJ-MODIFY-N', 'MINNA_N5', 'L08', 'N5', 'Adj-な + な + N / Adj-い + N', 'Adj-な + な + N / Adj-い + N', 'Danh từ có tính chất…', 'Khi bổ nghĩa đứng trước danh từ, tính từ đuôi な phải thêm 「な」, còn tính từ đuôi い giữ nguyên 「い」.', 'Hỏi tính chất/đặc điểm của N dùng 「どんな N ですか」(Là N như thế nào?).', '[{"japanese":"ワット先生は親切な先生です。","hiragana":"ワットせんせいはしんせつなせんせいです。","vietnamese":"Thầy Watt là một thầy giáo tốt bụng."},{"japanese":"富士山は高い山です。","hiragana":"ふじさんはたかいやまです。","vietnamese":"Núi Phú Sĩ là ngọn núi cao."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L08-GA-CONTRAST', 'MINNA_N5', 'L08', 'N5', 'S1 が、S2 (Nhưng mà)', 'S1 + が、S2', 'S1 nhưng S2', 'Trợ từ nối 「が」 liên kết hai mệnh đề có nghĩa tương phản nhau trong cùng một câu.', 'Phó từ mức độ: 「とても」(rất + khẳng định) và 「あまり」(không… lắm + phủ định).', '[{"japanese":"日本の食べ物は美味しいですが、高いです。","hiragana":"にほんのたべものはおいしいですが、たかいです。","vietnamese":"Đồ ăn Nhật ngon nhưng mà đắt."},{"japanese":"部屋は狭いですが、とても綺麗です。","hiragana":"へやはせまいですが、とてもきれいです。","vietnamese":"Phòng tuy hẹp nhưng rất sạch đẹp."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L09-GA-SUKI-JOUZU', 'MINNA_N5', 'L09', 'N5', 'N が 好きです／嫌いです／上手です／下手です', 'N + が + 好き／上手です', 'Thích / Ghét / Giỏi / Kém về N', 'Các tính từ chỉ sở thích và năng lực dùng trợ từ 「が」 đứng trước đối tượng (không dùng 「を」).', 'Khiêm tốn về bản thân thường không tự nhận là 「上手です」.', '[{"japanese":"私は日本の音楽が好きです。","hiragana":"わたしはにほんのおんがくがすきです。","vietnamese":"Tôi thích âm nhạc Nhật Bản."},{"japanese":"カリナさんは絵がとても上手です。","hiragana":"カリナさんはえがとてもじょうずです。","vietnamese":"Chị Karina vẽ tranh rất giỏi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L09-GA-WAKARIMASU', 'MINNA_N5', 'L09', 'N5', 'N が わかります／あります', 'N + が + わかります／あります', 'Hiểu N / Có N', 'Động từ 「わかります」(hiểu) và 「あります」(có sở hữu) dùng trợ từ 「が」 trước đối tượng.', 'Mức độ khẳng định: よく ＞ だいたい ＞ すこし. Mức độ phủ định: あまり～ない ＞ ぜんぜん～ない.', '[{"japanese":"私は漢字が少し分かります。","hiragana":"わたしはかんじがすこしわかります。","vietnamese":"Tôi hiểu được một chút chữ Hán."},{"japanese":"今日は用事がありますから、早く帰ります。","hiragana":"きょうはようじがありますから、はやくかえります。","vietnamese":"Hôm nay tôi có việc bận nên về sớm."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L09-KARA-REASON', 'MINNA_N5', 'L09', 'N5', 'S1 から、S2 (Vì… nên…)', 'S1 + から、S2', 'Vì S1 nên S2', 'Đặt 「から」 ngay sau mệnh đề nguyên nhân S1 để giải thích lý do cho kết quả S2.', 'Câu hỏi lý do dùng 「どうして…か」, khi trả lời ngắn đặt 「～からです」 ở cuối câu.', '[{"japanese":"時間がありませんから、新聞を読みません。","hiragana":"じかんがありませんから、しんぶんをよみません。","vietnamese":"Vì không có thời gian nên tôi không đọc báo."},{"japanese":"寒いから、窓を閉めましょう。","hiragana":"さむいから、まどをしめましょう。","vietnamese":"Vì trời lạnh nên hãy đóng cửa sổ nhé."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L10-ARIMASU-IMASU', 'MINNA_N5', 'L10', 'N5', 'N が あります／います', 'N + が + あります／います', 'Có N (đồ vật / người & động vật)', '「あります」 dùng cho đồ vật, cây cối, sự kiện không tự di chuyển; 「います」 dùng cho người và động vật.', 'Trợ từ đánh dấu đối tượng tồn tại là 「が」.', '[{"japanese":"そこに新しいコンビニがあります。","hiragana":"そこにあたらしいコンビニがあります。","vietnamese":"Ở đằng đó có cửa hàng tiện lợi mới."},{"japanese":"教室の中に学生がいます。","hiragana":"きょうしつのなかにがくせいがいます。","vietnamese":"Trong lớp học có học sinh."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L10-NI-GA-ARIMASU', 'MINNA_N5', 'L10', 'N5', 'N1 (Địa điểm) に N2 が あります／います', 'N1(địa điểm) + に + N2 + が + あります', 'Ở N1 có N2', 'Mô tả những gì tồn tại tại một địa điểm. Nhấn mạnh sự hiện diện của N2 ở nơi N1.', 'Khi liệt kê tiêu biểu (vài thứ trong nhiều thứ) dùng 「N1 や N2 など」 thay vì 「と」.', '[{"japanese":"大阪に有名な城があります。","hiragana":"おおさかにゆうめいなしろがあります。","vietnamese":"Ở Osaka có tòa thành nổi tiếng."},{"japanese":"庭に小さい猫がいます。","hiragana":"にわにちいさいねこがいます。","vietnamese":"Trong vườn có chú mèo nhỏ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L10-POSITION-NO-NI', 'MINNA_N5', 'L10', 'N5', 'N1 の [Vị trí] に N2 が あります／います', 'N1 + の + Vị trí + に + N2 + が + あります', 'Ở trên/dưới/trong/cạnh N1 có N2', 'Kết hợp danh từ vị trí (上・下・前・後ろ・右・左・中・外・隣・近く・間) với 「の」 để chỉ tọa độ chính xác.', 'Để đảo chủ đề (nói N2 đang ở đâu): 「N2 は N1 の [Vị trí] に あります／います」.', '[{"japanese":"机の上に写真と本があります。","hiragana":"つくえのうえにしゃしんとほんがあります。","vietnamese":"Ở trên bàn có ảnh và sách."},{"japanese":"銀行の隣に大きい病院があります。","hiragana":"ぎんこうのとなりにおおきいびょういんがあります。","vietnamese":"Bên cạnh ngân hàng có bệnh viện lớn."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L11-COUNTERS', 'MINNA_N5', 'L11', 'N5', 'Cách dùng Lượng từ (いくつ・人・枚・台)', 'N + を／が + Lượng từ + V', 'Đếm vật, người, vật mỏng, máy móc', 'Lượng từ trong tiếng Nhật thường đặt ngay trước động từ (sau trợ từ を／が) và không thêm trợ từ sau lượng từ.', 'Lượng từ phổ biến: ～つ (vật chung 1–10), ～人 (người: ひとり・ふたり・さんにん), ～台 (xe/máy), ～枚 (vật mỏng).', '[{"japanese":"りんごを四つ買いました。","hiragana":"りんごをよっつかいました。","vietnamese":"Tôi đã mua 4 quả táo."},{"japanese":"切手を五枚ください。","hiragana":"きってをごまいください。","vietnamese":"Cho tôi 5 con tem."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L11-DURATION-KAKARIMASU', 'MINNA_N5', 'L11', 'N5', '[Thời khoảng] + V / かかります', 'Thời khoảng + かかります', 'Làm V trong khoảng… / Mất bao lâu', 'Từ chỉ khoảng thời gian (～時間, ～週間, ～か月, ～年) đứng trước động từ không cần 「に」. 「かかります」 dùng cho thời gian và tiền bạc.', 'Hỏi khoảng thời gian/chi phí dùng 「どのくらい」.', '[{"japanese":"駅まで自転車で十分かかります。","hiragana":"えきまでじてんしゃでじゅっぷんかかります。","vietnamese":"Tới ga bằng xe đạp mất 10 phút."},{"japanese":"日本で一年間日本語を勉強しました。","hiragana":"にほんでいちねんかんにほんごをべんきょうしました。","vietnamese":"Tôi đã học tiếng Nhật ở Nhật 1 năm."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L11-FREQUENCY-NI-KAI', 'MINNA_N5', 'L11', 'N5', '[Thời khoảng] に [Số lần] V', 'Thời khoảng + に + ～回 + V', 'Làm V [số lần] trong [khoảng thời gian]', 'Biểu thị tần suất lặp lại của hành động trong một đơn vị thời gian.', 'Thêm 「だけ」(chỉ) sau lượng từ hoặc danh từ để giới hạn: 「休みは日曜日だけです」.', '[{"japanese":"一週間に二回テニスをします。","hiragana":"いっしゅうかんににかいテニスをします。","vietnamese":"Một tuần tôi chơi tennis 2 lần."},{"japanese":"一日に三回薬を飲みます。","hiragana":"いちにちにさんかいくすりをのみます。","vietnamese":"Một ngày tôi uống thuốc 3 lần."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L12-ADJ-PAST', 'MINNA_N5', 'L12', 'N5', 'Quá khứ của Danh từ & Tính từ い / な', 'Adj(-い) + かったです / なかったです', 'Đã từng [Adj / N] / Đã không [Adj / N]', 'N & Adj-な quá khứ: でした / じゃありませんでした. Adj-い quá khứ: bỏ い → かったです / くなかったです.', 'Ngoại lệ: 「いい」 quá khứ là 「よかったです」 / phủ định quá khứ 「よくなかったです」.', '[{"japanese":"昨日のテストは難しかったです。","hiragana":"きのうのテストはむずかしかったです。","vietnamese":"Bài kiểm tra hôm qua đã rất khó."},{"japanese":"先週の日曜日は暇でした。","hiragana":"せんしゅうのにちようびはひまでした。","vietnamese":"Chủ nhật tuần trước tôi rảnh rỗi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L12-YORI-COMPARE', 'MINNA_N5', 'L12', 'N5', 'N1 は N2 より Adj です', 'N1 + は + N2 + より + Adj です', 'N1 [Adj] hơn N2', 'So sánh hơn giữa hai đối tượng: 「より」 đặt sau đối tượng làm mốc so sánh.', 'Thêm 「ずっと」 trước tính từ để nhấn mạnh "hơn rất nhiều".', '[{"japanese":"新幹線はバスより速いです。","hiragana":"しんかんせんはバスよりはやいです。","vietnamese":"Tàu Shinkansen nhanh hơn xe buýt."},{"japanese":"北海道は東京より寒いです。","hiragana":"ほっかいどうはとうきょうよりさむいです。","vietnamese":"Hokkaido lạnh hơn Tokyo."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L12-DOCHIRA-GA', 'MINNA_N5', 'L12', 'N5', 'N1 と N2 と どちらが Adj ですか', 'N1とN2とどちらがAdjですか', 'Giữa N1 và N2 thì cái nào [Adj] hơn?', 'Câu hỏi so sánh hai đối tượng. Khi trả lời dùng 「N の ほうが Adj です」(N hơn).', 'Nếu cả hai như nhau thì đáp: 「どちらも Adj です」.', '[{"japanese":"夏と冬とどちらが好きですか。","hiragana":"なつとふゆとどちらがすきですか。","vietnamese":"Giữa mùa hè và mùa đông bạn thích mùa nào hơn?"},{"japanese":"コーヒーと紅茶とどちらがいいですか。","hiragana":"コーヒーとこうちゃとどちらがいいですか。","vietnamese":"Cà phê và hồng trà bạn chọn cái nào hơn?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L12-ICHIBAN', 'MINNA_N5', 'L12', 'N5', 'N1 の中で [Từ để hỏi] が 一番 Adj ですか', 'Nの中で + 何が + 一番 + Adj です', 'Trong N1 thì cái nào [Adj] nhất?', 'So sánh bậc nhất trong một nhóm từ 3 đối tượng trở lên. Từ để hỏi tùy loại: 何 (vật), だれ (người), どこ (nơi), いつ (thời gian).', 'Có thể dùng 「一番」 trực tiếp mà không cần mệnh đề 「～の中で」 nếu ngữ cảnh đã rõ.', '[{"japanese":"スポーツの中でサッカーが一番面白いです。","hiragana":"スポーツのなかでサッカーがいちばんおもしろいです。","vietnamese":"Trong các môn thể thao bóng đá thú vị nhất."},{"japanese":"一年で春が一番好きです。","hiragana":"いちねんではるがいちばんすきです。","vietnamese":"Trong một năm tôi thích mùa xuân nhất."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L13-GA-HOSHII', 'MINNA_N5', 'L13', 'N5', 'N が ほしいです', 'N + が + ほしいです', 'Tôi muốn có N (vật / đối tượng)', 'Diễn đạt mong muốn sở hữu một đồ vật hoặc đối tượng cụ thể. Đối tượng mong muốn đi với trợ từ 「が」.', '「ほしい」 là tính từ đuôi い, phủ định là 「ほしくないです」, quá khứ 「ほしかったです」.', '[{"japanese":"今、新しいパソコンがほしいです。","hiragana":"いま、あたらしいパソコンがほしいです。","vietnamese":"Bây giờ tôi muốn có máy tính mới."},{"japanese":"休みがほしいです。","hiragana":"やすみがほしいです。","vietnamese":"Tôi muốn có kỳ nghỉ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L13-V-TAI', 'MINNA_N5', 'L13', 'N5', 'V-ます (bỏ ます) + たいです', 'V(bỏ ます) + たいです', 'Tôi muốn làm V', 'Diễn đạt mong muốn thực hiện hành động của người nói (hoặc hỏi người nghe). Chia giống tính từ đuôi い (たくないです / たかったです).', 'Trợ từ 「を」 có thể chuyển sang 「が」 trước 「V-たい」 để nhấn mạnh đối tượng. Không dùng 「ほしい／たい」 cho ngôi thứ 3 ở N5.', '[{"japanese":"日本へ留学に行きたいです。","hiragana":"にほんへりゅうがくにいきたいです。","vietnamese":"Tôi muốn đi du học ở Nhật Bản."},{"japanese":"お腹が空いたからラーメンが食べたいです。","hiragana":"おなかがすいたからラーメンがたべたいです。","vietnamese":"Vì đói nên tôi muốn ăn mì Ramen."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L13-NI-IKIMASU', 'MINNA_N5', 'L13', 'N5', 'Địa điểm へ [V-bỏ ます / Danh động từ] に 行きます', 'Địa điểm + へ + V(bỏ ます) + に + 行きます', 'Đi đến đâu để làm gì', 'Trợ từ 「に」 đứng sau mục đích hành động (động từ bỏ ます hoặc danh từ hành động như 買い物・勉強) kết hợp với động từ di chuyển.', 'Với danh từ hành động nhóm 3 (買い物します) chỉ cần lấy phần danh từ: 「デパートへ買い物に行きます」.', '[{"japanese":"デパートへ靴を買いに行きます。","hiragana":"デパートへくつをかいにいきます。","vietnamese":"Tôi đi trung tâm thương mại để mua giày."},{"japanese":"公園へ写真を撮りに行きましょう。","hiragana":"こうえんへしゃしんをとりにいきましょう。","vietnamese":"Hãy ra công viên chụp ảnh nào."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L14-TE-KUDASAI', 'MINNA_N5', 'L14', 'N5', 'Vて ください', 'Vて + ください', 'Hãy làm V / Xin vui lòng làm V', 'Dùng để nhờ vả, hướng dẫn hoặc mời người nghe làm một hành động một cách lịch sự.', 'Cách chia thể て: Nhóm 1 (い・ち・り→って, み・び・に→んで, き→いて, ぎ→いで, し→して; ngoại lệ 行きます→行って); Nhóm 2 (bỏ ます+て); Nhóm 3 (来ます→来て, します→して).', '[{"japanese":"ここに名前を書いてください。","hiragana":"ここになまえをかいてください。","vietnamese":"Xin hãy viết tên vào đây."},{"japanese":"暑いので窓を開けてください。","hiragana":"あついのでまどをあけてください。","vietnamese":"Vì nóng xin hãy mở cửa sổ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L14-TE-IMASU-PROG', 'MINNA_N5', 'L14', 'N5', 'Vて います (Hành động đang diễn ra)', 'Vて + います', 'Đang làm V', 'Diễn tả hành động đang diễn ra ngay tại thời điểm nói (hiện tại tiếp diễn).', 'Câu hỏi thường gặp: 「今、何をしていますか」(Bây giờ bạn đang làm gì thế?).', '[{"japanese":"今、雨が降っています。","hiragana":"いま、あめがふっています。","vietnamese":"Bây giờ trời đang mưa."},{"japanese":"ミラーさんは今、電話をかけています。","hiragana":"ミラーさんはいま、でんわをかけています。","vietnamese":"Anh Miller hiện đang gọi điện thoại."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L14-V-MASHOUKA', 'MINNA_N5', 'L14', 'N5', 'Vましょうか (Đề nghị giúp đỡ)', 'Vましょうか', 'Để tôi làm V giúp bạn nhé?', 'Người nói chủ động đề nghị làm một việc gì đó giúp người nghe.', 'Nếu từ chối lịch sự có thể đáp: 「いいえ、けっこうです」(Không sao đâu, tôi tự làm được ạ).', '[{"japanese":"荷物を持ちましょうか。","hiragana":"にもつをもちましょうか。","vietnamese":"Để tôi xách giúp hành lý nhé?"},{"japanese":"駅まで車で送りましょうか。","hiragana":"えきまでくるまでおくりましょうか。","vietnamese":"Để tôi chở bạn ra ga bằng ô tô nhé?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L15-TEMO-II', 'MINNA_N5', 'L15', 'N5', 'Vて も いいですか', 'Vて + もいいですか', 'Tôi làm V có được không?', 'Dùng để xin phép làm một việc gì đó hoặc cho phép người khác làm.', 'Khi từ chối khéo thường nói: 「すみません、ちょっと…」(Xin lỗi, hơi bất tiện…).', '[{"japanese":"ここで写真を撮ってもいいですか。","hiragana":"ここでしゃしんをとってもいいですか。","vietnamese":"Tôi chụp ảnh ở đây có được không?"},{"japanese":"この辞書を借りてもいいですか。","hiragana":"このじしょをかりてもいいですか。","vietnamese":"Tôi mượn cuốn từ điển này được không?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L15-TEWA-IKEMASEN', 'MINNA_N5', 'L15', 'N5', 'Vて は いけません', 'Vて + はいけません', 'Không được phép làm V (Cấm)', 'Biểu thị sự cấm đoán, quy định không được làm một hành động nào đó.', 'Tránh dùng thẳng 「～てはいけません」 với cấp trên vì mang sắc thái ra lệnh mạnh.', '[{"japanese":"図書館で話してはいけません。","hiragana":"としょかんではなしてはいけません。","vietnamese":"Không được nói chuyện trong thư viện."},{"japanese":"ここでたばこを吸ってはいけません。","hiragana":"ここでたばこをすってはいけません。","vietnamese":"Không được hút thuốc ở đây."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L15-TE-IMASU-STATE', 'MINNA_N5', 'L15', 'N5', 'Vて います (Trạng thái / Nghề nghiệp / Thói quen)', 'Vて + います (trạng thái)', 'Đang ở trạng thái… / Làm nghề…', 'Ngoài ý nghĩa đang tiếp diễn, 「Vています」 còn diễn tả trạng thái kết quả (kết hôn, biết, đang sống ở đâu) hoặc nghề nghiệp, thói quen lâu dài.', 'Đặc biệt chú ý: phủ định của 「知っています」(biết) là 「知りません」(không biết), KHÔNG nói 「知っていません」!', '[{"japanese":"私は大阪に住んでいます。","hiragana":"わたしはおおさかにすんでいます。","vietnamese":"Tôi đang sống ở Osaka."},{"japanese":"姉はデパートで働いています。","hiragana":"あねはデパートではたらいています。","vietnamese":"Chị gái tôi đang làm việc ở trung tâm thương mại."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L16-V1TE-V2TE', 'MINNA_N5', 'L16', 'N5', 'V1て、V2て、～ (Liệt kê hành động theo thứ tự)', 'V1て、V2て、V3', 'Làm V1, rồi V2, rồi V3', 'Nối hai hay nhiều hành động xảy ra nối tiếp theo trình tự thời gian. Thì của cả câu quyết định ở động từ cuối cùng.', 'Không dùng để nối hai việc hoàn toàn độc lập không theo trình tự.', '[{"japanese":"朝起きて、顔を洗って、朝ご飯を食べます。","hiragana":"あさおきて、かおをあらって、あさごはんをたべます。","vietnamese":"Sáng dậy, rửa mặt rồi ăn bữa sáng."},{"japanese":"銀行でお金を下ろして、買物をします。","hiragana":"ぎんこうでおかねをおろして、かいものをします。","vietnamese":"Rút tiền ở ngân hàng rồi đi mua sắm."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L16-V1TEKARA-V2', 'MINNA_N5', 'L16', 'N5', 'V1てから、V2', 'V1て + から、V2', 'Sau khi làm xong V1 thì làm V2', 'Nhấn mạnh hành động V1 phải hoàn tất trước rồi mới tiến hành hành động V2.', 'Trong một câu chỉ dùng một lần 「～てから」, không lặp nhiều lần liên tiếp.', '[{"japanese":"仕事が終わってから、飲みに行きます。","hiragana":"しごとがおわってから、のみにいきます。","vietnamese":"Sau khi xong việc tôi sẽ đi uống."},{"japanese":"手を洗ってから、食事をします。","hiragana":"てをあらってから、しょくじをします。","vietnamese":"Sau khi rửa tay rồi mới ăn cơm."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L16-ADJ-JOIN', 'MINNA_N5', 'L16', 'N5', 'Nối tính từ & Danh từ (～くて / ～で)', 'Adj-い→くて / Adj-な·N→で', 'Vừa… vừa…', 'Tính từ い bỏ 「い」 + 「くて」 (いい → よくて); Tính từ な và Danh từ + 「で」 để nối các đặc điểm cùng chiều.', 'Nếu hai đặc điểm mang nghĩa trái ngược (đẹp nhưng đắt) phải dùng 「が」, không dùng 「くて／で」.', '[{"japanese":"この部屋は広くて、明るいです。","hiragana":"このへやはひろくて、あかるいです。","vietnamese":"Căn phòng này rộng rãi và sáng sủa."},{"japanese":"京都は静かで、綺麗な町です。","hiragana":"きょうとはしずかで、きれいなまちです。","vietnamese":"Kyoto là thành phố yên tĩnh và đẹp."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L16-N1-WA-N2-GA-ADJ', 'MINNA_N5', 'L16', 'N5', 'N1 は N2 が Adj です', 'N1 + は + N2 + が + Adj です', 'N1 có bộ phận/đặc điểm N2 thì Adj', 'Miêu tả một khía cạnh cụ thể (N2) thuộc về chủ thể lớn (N1).', 'N1 là chủ đề toàn câu (は), N2 là bộ phận trực tiếp mang tính chất (が).', '[{"japanese":"田中さんは背が高いです。","hiragana":"たなかさんはせがたかいです。","vietnamese":"Anh Tanaka dáng người cao."},{"japanese":"奈良はお寺が有名です。","hiragana":"ならはおてらがゆうめいです。","vietnamese":"Nara nổi tiếng về chùa chiền."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L17-NAIDE-KUDASAI', 'MINNA_N5', 'L17', 'N5', 'Vない で ください', 'Vない + でください', 'Xin đừng làm V', 'Đề nghị hoặc yêu cầu người khác không thực hiện một hành động nào đó.', 'Chia thể ない: Nhóm 1 (cột い → cột あ + ない; riêng い → わ + ない: 買います→買わない); Nhóm 2 (bỏ ます+ない); Nhóm 3 (来ます→来ない [こない], します→しない).', '[{"japanese":"ここに車を止めないでください。","hiragana":"ここにくるとめないでください。","vietnamese":"Xin đừng đỗ xe ở đây."},{"japanese":"パスポートを忘れないでください。","hiragana":"パスポートをわすれないでください。","vietnamese":"Xin đừng quên hộ chiếu."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L17-NAKEREBA-NARIMASEN', 'MINNA_N5', 'L17', 'N5', 'Vな(い) + ければなりません', 'V(bỏ い của ない) + ければなりません', 'Phải làm V (Nghĩa vụ / Bắt buộc)', 'Biểu thị việc bắt buộc phải làm theo quy định hoặc nhu cầu khách quan.', 'Dạng quá khứ: 「～なければなりませんでした」 (đã phải làm…).', '[{"japanese":"明日までにレポートを出さなければなりません。","hiragana":"あしたまでにレポートをださなければなりません。","vietnamese":"Phải nộp báo cáo trước ngày mai."},{"japanese":"毎日薬を飲まなければなりません。","hiragana":"まいにちくすりをのまなければなりません。","vietnamese":"Mỗi ngày phải uống thuốc."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L17-NAKUTEMO-II', 'MINNA_N5', 'L17', 'N5', 'Vな(い) + くてもいいです', 'V(bỏ い của ない) + くてもいいです', 'Không cần làm V cũng được', 'Diễn tả một hành động không bắt buộc phải làm.', 'Đây là câu trả lời phủ định chuẩn khi ai đó hỏi 「～なければなりませんか」(Có phải làm không?).', '[{"japanese":"日曜日は会社へ行かなくてもいいです。","hiragana":"にちようびはかいしゃへいかなくてもいいです。","vietnamese":"Chủ nhật không cần đến công ty cũng được."},{"japanese":"明日は早く起きなくてもいいです。","hiragana":"あしたははやくおきなくてもいいです。","vietnamese":"Ngày mai không cần dậy sớm cũng được."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L18-KOTO-GA-DEKIMASU', 'MINNA_N5', 'L18', 'N5', 'N / Vる ことが できます', 'Vる + ことができます', 'Có thể làm V / Có khả năng về N', 'Biểu thị năng lực cá nhân hoặc khả năng cho phép theo hoàn cảnh.', 'Chia thể từ điển (Vる): Nhóm 1 (cột い → cột う: 書きます→書く); Nhóm 2 (bỏ ます+る); Nhóm 3 (来ます→来る [くる], します→する).', '[{"japanese":"私は漢字を読むことができます。","hiragana":"わたしはかんじをよむことができます。","vietnamese":"Tôi có thể đọc được chữ Hán."},{"japanese":"カードで払うことができますか。","hiragana":"カードではらうことができますか。","vietnamese":"Có thể thanh toán bằng thẻ được không?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L18-SHUMI-WA-KOTO', 'MINNA_N5', 'L18', 'N5', '私の趣味は [N / Vる こと] です', '趣味は + Vる + ことです', 'Sở thích của tôi là…', 'Danh từ hóa động từ bằng cách thêm 「こと」 sau thể từ điển 「Vる」 để nói về sở thích.', 'Cụm 「Vる こと」 đóng vai trò giống một danh từ hoàn chỉnh trong câu.', '[{"japanese":"私の趣味は映画を見ることです。","hiragana":"わたしのしゅみはえいがをみることです。","vietnamese":"Sở thích của tôi là xem phim."},{"japanese":"兄の趣味は音楽を聴くことです。","hiragana":"あにのしゅみはおんがくをきくことです。","vietnamese":"Sở thích của anh trai tôi là nghe nhạc."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L18-MAE-NI', 'MINNA_N5', 'L18', 'N5', 'V1る / Nの / [Thời khoảng] 前に、V2', 'V1る / Nの + 前に、V2', 'Trước khi V1 / Trước N / Cách đây…', 'Chỉ hành động V2 diễn ra trước thời điểm V1 hoặc danh từ N. Động từ trước 「前に」 LUÔN ở thể từ điển 「Vる」 kể cả khi V2 là quá khứ.', 'Với khoảng thời gian KHÔNG dùng 「の」: 「３年前に日本へ来ました」(Đã đến Nhật 3 năm trước).', '[{"japanese":"寝る前に、歯を磨きます。","hiragana":"ねるまえに、はをみがきます。","vietnamese":"Trước khi đi ngủ tôi đánh răng."},{"japanese":"食事の前に、手を洗います。","hiragana":"しょくじのまえに、てをあらいます。","vietnamese":"Trước bữa ăn tôi rửa tay."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L19-TA-KOTO-GA-ARU', 'MINNA_N5', 'L19', 'N5', 'Vた ことが あります', 'Vた + ことがあります', 'Đã từng làm V (Kinh nghiệm)', 'Nói về một trải nghiệm từng có trong quá khứ (không dùng cho việc vừa làm hôm qua hay thói quen hằng ngày).', 'Cách chia thể た giống hệt quy tắc thể て, chỉ đổi 「て→た」 và 「で→だ」.', '[{"japanese":"私は富士山に登ったことがあります。","hiragana":"わたしはふじさんにのぼったことがあります。","vietnamese":"Tôi đã từng leo núi Phú Sĩ."},{"japanese":"お寿司を作ったことがありますか。","hiragana":"おすしをつくったことがありますか。","vietnamese":"Bạn đã từng làm món Sushi bao giờ chưa?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L19-TARI-TARI', 'MINNA_N5', 'L19', 'N5', 'V1たり、V2たり します', 'V1たり、V2たり + します', 'Làm lúc thì V1, lúc thì V2…', 'Liệt kê tiêu biểu 2–3 hành động trong nhiều hành động mà không nhấn mạnh thứ tự thời gian.', 'Thì và thể của cả câu chia ở động từ 「します」 cuối cùng.', '[{"japanese":"日曜日は本を読んだり、音楽を聴いたりします。","hiragana":"にちようびはほんをよんだり、おんがくをきいたりします。","vietnamese":"Chủ nhật tôi đọc sách rồi nghe nhạc các thứ."},{"japanese":"京都でお寺を見たり、写真を撮ったりしました。","hiragana":"きょうとでおてらをみたり、しゃしんをとったりしました。","vietnamese":"Ở Kyoto tôi đi xem chùa và chụp ảnh các kiểu."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L19-NARIMASU', 'MINNA_N5', 'L19', 'N5', 'Adj-い→く / Adj-な→に / N→に なります', 'Adj-い→く / Adj-な·N→に + なります', 'Trở nên… / Biến thành…', 'Diễn tả sự biến đổi trạng thái tự nhiên theo thời gian (trời ấm lên, giỏi hơn, thành bác sĩ, sang tuổi mới…).', 'Ngoại lệ: 「いい」 → 「よくなります」.', '[{"japanese":"五時から暗くなります。","hiragana":"ごじからくらくなります。","vietnamese":"Từ 5 giờ trời sẽ tối đi."},{"japanese":"日本語が少しずつ上手になりました。","hiragana":"にほんごがすこしずつじょうずになりました。","vietnamese":"Tiếng Nhật đã giỏi lên từng chút một."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L20-PLAIN-FORM-RULES', 'MINNA_N5', 'L20', 'N5', 'Quy tắc chuyển Thể lịch sự → Thể thông thường (普通形)', 'Vる / Vない / Vた / Adj-い / Nだ', 'Dạng ngắn / thân mật của Động từ, Tính từ, Danh từ', 'Động từ: ます→Vる, ません→Vない, ました→Vた, ませんでした→Vなかった. Tính từ い: bỏ です. Tính từ な & Danh từ: です→だ, じゃありません→じゃない, でした→だった, じゃありませんでした→じゃなかった.', 'Thể thông thường không chỉ dùng khi nói với bạn thân/gia đình mà còn là nền tảng bắt buộc cho các mẫu câu từ Bài 21–25!', '[{"japanese":"明日、東京へ行く。","hiragana":"あした、とうきょうへいく。","vietnamese":"Ngày mai tôi đi Tokyo. (thể thường)"},{"japanese":"昨日のテストは簡単だった。","hiragana":"きのうのテストはかんたんだった。","vietnamese":"Bài kiểm tra hôm qua dễ thật. (thể thường)"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L20-CASUAL-CONVERSATION', 'MINNA_N5', 'L20', 'N5', 'Câu hỏi & Lược bỏ trợ từ trong Thể thông thường', '[Thể thường]？（Lên giọng）', 'Giao tiếp thân mật với bạn bè, gia đình', 'Trong câu hỏi thân mật bỏ 「か」 và lên giọng cuối câu; với Danh từ/Tính từ な bỏ luôn 「だ」 (VD: あした暇？). Đáp lại dùng 「うん」(Ừ) / 「ううん」(Không).', 'Trợ từ 「は・を・へ」 và chữ 「い」 trong 「～ている→～てる」 thường được lược gọn khi nói thân mật.', '[{"japanese":"明日、パーティーに行く？うん、行くよ。","hiragana":"あした、パーティーにいく？うん、いくよ。","vietnamese":"Mai cậu có đi tiệc không? Ừ, đi chứ."},{"japanese":"今晩、映画見ない？いいね、見よう。","hiragana":"こんばん、えいがみない？いいね、みよう。","vietnamese":"Tối nay xem phim không? Hay đấy, xem đi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L21-TO-OMOIMASU', 'MINNA_N5', 'L21', 'N5', '[Thể thông thường] と 思います', '[Thể thường] + と思います', 'Tôi nghĩ rằng… (Phỏng đoán / Ý kiến)', 'Dùng để nêu suy đoán hoặc bày tỏ quan điểm cá nhân. Mệnh đề trước 「と思います」 bắt buộc chia ở thể thông thường (lưu ý N/Adj-な phải có 「だ」).', 'Phủ định ý kiến đặt ở mệnh đề bên trong: 「役に立たないと思います」(Tôi nghĩ là không có ích).', '[{"japanese":"明日は雨が降ると思います。","hiragana":"あしたはあめがふるとおもいます。","vietnamese":"Tôi nghĩ ngày mai trời sẽ mưa."},{"japanese":"日本の物価は高いと思います。","hiragana":"にほんのぶっかはたかいとおもいます。","vietnamese":"Tôi nghĩ vật giá ở Nhật đắt."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L21-TO-IIMASU', 'MINNA_N5', 'L21', 'N5', '[Trích dẫn / Thể thường] と 言います', '[Thể thường] + と言います', 'Nói rằng… (Trích dẫn trực tiếp / gián tiếp)', 'Trích dẫn nguyên văn đặt trong ngoặc 「…」 + と言います, hoặc trích dẫn gián tiếp dùng [Thể thường] + と言いました.', 'Lưu ý dùng 「と言っていました」 khi thuật lại điều ai đó đã nói hoặc thường nói.', '[{"japanese":"寝る前に「おやすみなさい」と言います。","hiragana":"ねるまえに「おやすみなさい」といいます。","vietnamese":"Trước khi ngủ nói \"Chúc ngủ ngon\"."},{"japanese":"ミラーさんは来週帰国すると言いました。","hiragana":"ミラーさんはらいしゅうきこくするといいました。","vietnamese":"Anh Miller đã nói tuần sau sẽ về nước."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L21-DESHOU', 'MINNA_N5', 'L21', 'N5', '[Thể thông thường (bỏ だ)] でしょう？', '[Thể thường bỏ だ] + でしょう？', '… đúng không nào? (Xác nhận sự đồng tình)', 'Đặt cuối câu với giọng lên nhẹ để xác nhận thông tin mà người nói tin rằng người nghe cũng đồng tình hoặc biết.', 'Khác với 「と思います」, trước 「でしょう？」 KHÔNG thêm 「だ」 sau Danh từ và Tính từ な.', '[{"japanese":"明日は寒いでしょう？はい、寒いです。","hiragana":"あしたはさむいでしょう？はい、さむいです。","vietnamese":"Ngày mai chắc lạnh nhỉ? Ừ, lạnh đấy."},{"japanese":"北海道は雪が降るでしょう。","hiragana":"ほっかいどうはゆきがふるでしょう。","vietnamese":"Ở Hokkaido chắc sẽ có tuyết rơi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L22-NOUN-MODIFIER', 'MINNA_N5', 'L22', 'N5', '[Mệnh đề Thể thông thường] + Danh từ', '[Chủ ngữ + が + V thể thường] + N', 'Danh từ mà [ai đó làm / có đặc điểm…]', 'Trong tiếng Nhật, toàn bộ mệnh đề giải thích đặt TRƯỚC danh từ được bổ nghĩa, động từ chia ở thể thông thường (chủ ngữ trong mệnh đề phụ đổi 「は」 thành 「が」).', 'Tuyệt đối không dùng 「は」 cho chủ ngữ bên trong mệnh đề định ngữ — luôn đổi thành 「が」!', '[{"japanese":"これは先週私が買った本です。","hiragana":"これはせんしゅうわたしがかったほんです。","vietnamese":"Đây là quyển sách tuần trước tôi đã mua."},{"japanese":"あそこで新聞を読んでいる人は先生です。","hiragana":"あそこでしんぶんをよんでいるひとはせんせいです。","vietnamese":"Người đang đọc báo ở đằng kia là thầy giáo."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L22-V-RU-JIKAN', 'MINNA_N5', 'L22', 'N5', 'Vる 時間／約束／用事 が あります', 'Vる + 時間／約束 + があります', 'Có thời gian / hẹn / việc phải làm V', 'Ứng dụng phổ biến của định ngữ: dùng động từ thể từ điển 「Vる」 bổ nghĩa trực tiếp cho 時間 (thời gian), 約束 (lời hẹn), 用事 (việc bận).', 'Động từ đứng trước 「時間／約束／用事」 luôn ở thể từ điển 「Vる」.', '[{"japanese":"朝ご飯を食べる時間がありません。","hiragana":"あさごはんをたべるじかんがありません。","vietnamese":"Tôi không có thời gian ăn sáng."},{"japanese":"明日友達と会う約束があります。","hiragana":"あしたともだちとあうやくそくがあります。","vietnamese":"Ngày mai tôi có hẹn gặp bạn."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L23-TOKI', 'MINNA_N5', 'L23', 'N5', '[Vる / Vた / Vない / Adj / Nの] とき、S2', 'Vる / Vた / Nの + とき、S2', 'Khi… thì S2', 'Chỉ thời điểm hành động S2 xảy ra. Dùng 「Vる とき」 khi hành động V1 chưa hoàn tất (trước/trong khi làm), dùng 「Vた とき」 khi V1 đã hoàn tất xong.', 'Kết hợp: Adj-い + とき, Adj-な + なとき, N + のとき.', '[{"japanese":"図書館で本を借りるとき、カードがいります。","hiragana":"としょかんでほんをかりるとき、カードがいります。","vietnamese":"Khi mượn sách ở thư viện cần có thẻ."},{"japanese":"眠いとき、濃いコーヒーを飲みます。","hiragana":"ねむいとき、こいコーヒーをのみます。","vietnamese":"Lúc buồn ngủ tôi uống cà phê đậm."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L23-V-RU-TO', 'MINNA_N5', 'L23', 'N5', 'Vる / Vない と、S2 (Điều kiện tự nhiên / chỉ đường)', 'Vる + と、S2', 'Hễ làm V1 thì tất yếu xảy ra S2', 'Diễn tả kết quả tự nhiên, quy luật máy móc, hoặc chỉ đường đi (hễ rẽ phải thì thấy…).', 'Mệnh đề S2 KHÔNG ĐƯỢC chứa ý chí, lời mời hay mệnh lệnh (～たい, ～ましょう, ～てください).', '[{"japanese":"このボタンを押すと、お釣りが出ます。","hiragana":"このボタンをおすと、おつりがでます。","vietnamese":"Hễ bấm nút này thì tiền thừa sẽ ra."},{"japanese":"右へ曲がると、郵便局があります。","hiragana":"みぎへまがると、ゆうびんきょくがあります。","vietnamese":"Hễ rẽ sang phải sẽ thấy bưu điện."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L24-KUREMASU', 'MINNA_N5', 'L24', 'N5', 'N1 (Người khác) は 私に N2 を くれます', 'N1 + は + 私に + N2 + を + くれます', 'Ai đó tặng / cho tôi (hoặc người nhà tôi)', 'Khi người nhận là bản thân mình (hoặc thành viên gia đình mình), PHẢI dùng 「くれます」, tuyệt đối không dùng 「あげます」.', 'Có thể lược bỏ 「私に」 khi đã rõ người nhận là bản thân người nói.', '[{"japanese":"姉が誕生日にネクタイをくれました。","hiragana":"あねがたんじょうびにネクタイをくれました。","vietnamese":"Chị gái đã tặng tôi chiếc cà vạt nhân sinh nhật."},{"japanese":"友達がお土産をくれました。","hiragana":"ともだちがおみやげをくれました。","vietnamese":"Bạn tôi đã tặng quà lưu niệm cho tôi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L24-TE-AGEMASU', 'MINNA_N5', 'L24', 'N5', 'Vて あげます', 'Vて + あげます', 'Làm V giúp ai đó (mang thiện ý)', 'Diễn tả hành động người nói (hoặc chủ ngữ) làm giúp cho người khác với thiện ý.', 'Tránh dùng thẳng 「～てあげます」 với người trên vì dễ gây cảm giác ban ơn; hãy dùng 「～ましょうか」.', '[{"japanese":"私はおばあさんに道を教えてあげました。","hiragana":"わたしはおばあさんにみちをおしえてあげました。","vietnamese":"Tôi đã chỉ đường cho bà cụ."},{"japanese":"妹に日本語の本を買ってあげます。","hiragana":"いもうとににほんごのほんをかってあげます。","vietnamese":"Tôi mua sách tiếng Nhật cho em gái."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L24-TE-MORAIMASU', 'MINNA_N5', 'L24', 'N5', 'Vて もらいます', 'Người giúp + に + Vて + もらいます', 'Nhờ ai đó làm giúp V / Được ai làm giúp', 'Chủ ngữ là người nhận ân huệ, nhờ vả hoặc nhận được sự giúp đỡ từ người làm hành động (đánh dấu bằng 「に」).', 'Đứng ở góc nhìn người nhận (「私は…」).', '[{"japanese":"私は先輩に漢字を教えてもらいました。","hiragana":"わたしはせんぱいにかんじをおしえてもらいました。","vietnamese":"Tôi đã được tiền bối dạy chữ Hán cho."},{"japanese":"先生に作文を直してもらいました。","hiragana":"せんせいにさくぶんをなおしてもらいました。","vietnamese":"Tôi đã được thầy sửa bài viết cho."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L24-TE-KUREMASU', 'MINNA_N5', 'L24', 'N5', 'Vて くれます', 'Người giúp + は + Vて + くれます', 'Ai đó chủ động làm giúp tôi (thể hiện lòng biết ơn)', 'Chủ ngữ là người thực hiện hành động giúp đỡ cho tôi (hoặc gia đình tôi), hàm ý biết ơn sâu sắc.', 'Nếu chủ ngữ là người giúp → 「てくれます」; nếu chủ ngữ là "tôi" → 「てもらいます」.', '[{"japanese":"山田さんが駅まで車で送ってくれました。","hiragana":"やまださんがえきまでくるまでおくってくれました。","vietnamese":"Anh Yamada đã lái xe đưa tôi ra tận ga."},{"japanese":"友達が重い荷物を持ってくれました。","hiragana":"ともだちがおもいにもつをもってくれました。","vietnamese":"Bạn tôi đã xách giúp hành lý nặng."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L25-TARA-IF', 'MINNA_N5', 'L25', 'N5', '[Vた / Adj-かった / Adj-な·Nだった] + ら、S2', '[Quá khứ thể thường] + ら、S2', 'Nếu… thì S2 / Sau khi… thì S2', 'Mẫu câu điều kiện đa năng nhất: lấy thể quá khứ thông thường + 「ら」. Có thể diễn tả giả thiết (nếu có tiền…) hoặc hành động chắc chắn xảy ra trong tương lai (khi nào đến ga thì gọi nhé).', 'Khác với 「と」, mệnh đề sau 「たら」 thoải mái dùng ý chí, yêu cầu, lời mời (～てください, ～ましょう). Thường đi cùng 「もし」(nếu giả sử).', '[{"japanese":"雨が降ったら、出かけません。","hiragana":"あめがふったら、でかけません。","vietnamese":"Nếu trời mưa thì tôi sẽ không ra ngoài."},{"japanese":"駅に着いたら、電話をかけてください。","hiragana":"えきについたら、でんわをかけてください。","vietnamese":"Khi nào tới ga thì hãy gọi điện cho tôi nhé."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-MNN-L25-TEMO-EVEN-IF', 'MINNA_N5', 'L25', 'N5', '[Vて / Adj-くて / Adj-な·Nで] + も、S2', 'Vて / Adj-くて / Nで + も、S2', 'Cho dù… đi nữa thì vẫn S2', 'Biểu thị điều kiện nhượng bộ: dù giả thiết ở vế trước có xảy ra thì kết quả ở vế sau vẫn không thay đổi.', 'Thường kết hợp với phó từ 「いくら」(cho dù bao nhiêu đi nữa) để nhấn mạnh: 「いくら考えても、わかりません」.', '[{"japanese":"雨が降っても、サッカーをします。","hiragana":"あめがふっても、サッカーをします。","vietnamese":"Dù trời có mưa tôi vẫn đá bóng."},{"japanese":"高くても、このカメラを買いたいです。","hiragana":"たかくても、このカメラをかいたいです。","vietnamese":"Dù đắt tôi vẫn muốn mua chiếc máy ảnh này."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-SMT-W01-GA-EXIST', 'SOUMATOME_N5', 'W01', 'N5', 'Phân biệt trợ từ 「に」 và 「で」 chỉ nơi chốn', 'Địa điểm + に (Tồn tại) / Địa điểm + で (Hành động)', 'Ở (nơi tồn tại) vs Tại (nơi diễn ra hành động)', '「に」 dùng với động từ chỉ sự tồn tại (います・あります・住んでいます). 「で」 dùng cho địa điểm diễn ra hành động (食べます・勉強します).', '', '[{"japanese":"部屋の机の上に猫がいます。","hiragana":"へやのつくえのうえにねこがいます。","vietnamese":"Ở trên bàn trong phòng có con mèo."},{"japanese":"図書館で友達と勉強します。","hiragana":"としょかんでともだちとべんきょうします。","vietnamese":"Tôi học bài cùng bạn ở thư viện."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-SMT-W01-TO-YA', 'SOUMATOME_N5', 'W01', 'N5', 'Liệt kê danh từ: ～と～ vs ～や～など', 'N1 + と + N2 / N1 + や + N2 + など', 'Và (liệt kê hết) vs Và... v.v. (liệt kê đại diện)', '「AとB」 liệt kê đầy đủ toàn bộ vật. 「AやBなど」 nêu vài ví dụ tiêu biểu trong nhiều vật.', '', '[{"japanese":"机の上にペンやノートなどがあります。","hiragana":"つくえのうえにペンやノートなどがあります。","vietnamese":"Trên bàn có bút, vở, v.v."},{"japanese":"冷蔵庫に牛乳と卵が入っています。","hiragana":"れいぞうこにぎゅうにゅうとたまごがはいっています。","vietnamese":"Trong tủ lạnh có sữa bò và trứng."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-SMT-W02-AMARI-ZENZEN', 'SOUMATOME_N5', 'W02', 'N5', 'Phó từ đi với phủ định: あまり / 全然 ～ない', 'あまり + Phủ định / 全然 + Phủ định', 'Không... lắm / Hoàn toàn không...', '「あまり」 đi với động từ hoặc tính từ phủ định diễn tả mức độ ít; 「ぜんぜん」 mang nghĩa phủ định hoàn toàn 100%.', '', '[{"japanese":"私は辛い料理があまり好きじゃありません。","hiragana":"わたしはからいりょうりがあまりすきじゃありません。","vietnamese":"Tôi không thích đồ ăn cay lắm."},{"japanese":"昨日は忙しくて全然寝ませんでした。","hiragana":"きのうはいそがしくてぜんぜんねませんでした。","vietnamese":"Hôm qua bận nên tôi hoàn toàn không ngủ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-SMT-W02-SUGIRU', 'SOUMATOME_N5', 'W02', 'N5', '～すぎる / ～やすい (Quá mức / Dễ làm)', 'Vます + すぎる / Adj + すぎる', 'Quá... (vượt mức) / Dễ...', 'Thể hiện trạng thái vượt quá mức bình thường (tính từ bỏ い/な + すぎる, động từ bỏ ます + すぎる).', '', '[{"japanese":"昨日の晩ご飯は食べすぎました。","hiragana":"きのうのばんごはんはたべすぎました。","vietnamese":"Bữa tối hôm qua tôi đã ăn quá nhiều."},{"japanese":"この靴は私には少し大きすぎます。","hiragana":"このくつはわたしにはすこしおおきすぎます。","vietnamese":"Đôi giày này hơi quá to với tôi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-SMT-W03-TE-OKU', 'SOUMATOME_N5', 'W03', 'N5', 'Vて みます (Thử làm V)', 'Vて + みます', 'Thử làm việc gì đó xem sao', 'Diễn tả hành động làm thử để kiểm tra kết quả hoặc cảm nhận.', '', '[{"japanese":"日本の抹茶を飲んでみます。","hiragana":"にほんのまっちゃをのんでみます。","vietnamese":"Tôi sẽ uống thử trà xanh Nhật Bản."},{"japanese":"この靴を履いてみてもいいですか。","hiragana":"このくつをはいてみてもいいですか。","vietnamese":"Tôi đi thử đôi giày này được không?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-SMT-W03-TE-SHIMAU', 'SOUMATOME_N5', 'W03', 'N5', 'Vて しまいます (Hoàn thành xong / Lỡ mất)', 'Vて + しまいます', 'Làm xong hết hoàn toàn / Lỡ làm (tiếc nuối)', 'Nghĩa 1: hoàn thành dứt điểm hành động. Nghĩa 2: lỡ làm gì ngoài ý muốn.', '', '[{"japanese":"宿題をもう全部やってしまいました。","hiragana":"しゅくだいをもうぜんぶやってしまいました。","vietnamese":"Tôi đã làm xong hết toàn bộ bài tập rồi."},{"japanese":"電車に傘を忘れてしまいました。","hiragana":"でんしゃにかさをわすれてしまいました。","vietnamese":"Tôi lỡ để quên ô trên tàu điện mất rồi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-SMT-W04-TSUMORI', 'SOUMATOME_N5', 'W04', 'N5', 'Vる / Vない + つもりです', 'Vる + つもりです / Vない + つもりです', 'Dự định làm / dự định không làm', 'Thể hiện ý định rõ ràng, kế hoạch của bản thân trong tương lai.', '', '[{"japanese":"夏休みに国へ帰るつもりです。","hiragana":"なつやすみにくにへかえるつもりです。","vietnamese":"Nghỉ hè tôi dự định sẽ về nước."},{"japanese":"明日からはお菓子を食べないつもりです。","hiragana":"あしたからはおかしをたべないつもりです。","vietnamese":"Từ mai tôi định sẽ không ăn đồ ngọt nữa."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-SMT-W04-KARA-NODE', 'SOUMATOME_N5', 'W04', 'N5', 'Nguyên nhân lịch sự: ～ので', 'V/Aい + ので / N/Aな + なので', 'Vì... cho nên... (mềm mỏng, khách quan)', 'Giống 「から」 nhưng mang sắc thái lịch sự, nhẹ nhàng, khách quan hơn khi trình bày lý do.', '', '[{"japanese":"風邪を引いたので、今日は学校を休みます。","hiragana":"かぜをひいたので、きょうはがっこうをやすみます。","vietnamese":"Vì bị cảm nên hôm nay tôi nghỉ học."},{"japanese":"雨が降っているので、傘を持って出かけます。","hiragana":"あめがふっているので、かさをもってでかけます。","vietnamese":"Vì trời đang mưa nên tôi mang ô ra ngoài."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-SMT-W05-HOU-GA-II', 'SOUMATOME_N5', 'W05', 'N5', 'Vた / Vない + ほうがいいです', 'Vた + ほうがいいです / Vない + ほうがいいです', 'Nên làm / Không nên làm...', 'Dùng để khuyên nhủ người khác nên làm hoặc tránh làm việc gì.', '', '[{"japanese":"早く寝たほうがいいですよ。","hiragana":"はやくねたほうがいいですよ。","vietnamese":"Bạn nên đi ngủ sớm đi nhé."},{"japanese":"夜遅くコーヒーを飲まないほうがいいです。","hiragana":"よるおそくコーヒーをのまないほうがいいです。","vietnamese":"Đêm muộn thì không nên uống cà phê."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N5-SMT-W05-KAMOSHIRENAI', 'SOUMATOME_N5', 'W05', 'N5', 'Thể thông thường + かもしれません', 'Thể thường + かもしれません', 'Có lẽ, biết đâu chừng (khả năng ~50%)', 'Dự đoán một sự việc có khả năng xảy ra nhưng người nói không chắc chắn lắm.', '', '[{"japanese":"午後から雪が降るかもしれません。","hiragana":"ごごからゆきがふるかもしれません。","vietnamese":"Từ chiều có lẽ tuyết sẽ rơi đấy."},{"japanese":"田中さんは今日来ないかもしれません。","hiragana":"たなかさんはきょうこないかもしれません。","vietnamese":"Có lẽ hôm nay anh Tanaka sẽ không đến."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L26-NDESU', 'MINNA_N4', 'L26', 'N4', '～んです (Giải thích lý do / Nhấn mạnh)', 'V/Aい + んです / N/Aな + なんです', 'Là vì... / Chẳng là... / (Hỏi xác nhận tình huống)', 'Dùng khi người nói muốn giải thích nguyên nhân, nhấn mạnh cảm xúc hoặc hỏi xác nhận điều vừa thấy/nghe.', 'Trong văn viết dùng ～のです.', '[{"japanese":"どうしたんですか。頭が痛いんです。","hiragana":"どうしたんですか。あたまがいたいんです。","vietnamese":"Có chuyện gì thế? Tôi bị đau đầu ạ."},{"japanese":"日本語が上手ですね。毎日練習しているんです。","hiragana":"にほんごがじょうずですね。まいにちれんしゅうしているんです。","vietnamese":"Tiếng Nhật bạn giỏi quá. Chẳng là ngày nào tôi cũng luyện tập."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L26-ITADAKEMASENKA', 'MINNA_N4', 'L26', 'N4', '～ていただけませんか (Nhờ vả lịch sự)', 'Vて + いただけませんか', 'Xin vui lòng giúp tôi... có được không ạ?', 'Cách nhờ vả lịch sự hơn nhiều so với ～てください, thường dùng với cấp trên hoặc người không quen.', 'Có thể dùng 「～てくれませんか」 trong giao tiếp thân mật hơn.', '[{"japanese":"すみませんが、日本語を教えていただけませんか。","hiragana":"すみませんが、にほんごをおしえていただけませんか。","vietnamese":"Xin lỗi, thầy có thể dạy tiếng Nhật cho em được không ạ?"},{"japanese":"ちょっと写真を見ていただけませんか。","hiragana":"ちょっとしゃしんをみていただけませんか。","vietnamese":"Anh xem giúp tôi bức ảnh một chút được không ạ?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L26-POTENTIAL', 'MINNA_N4', 'L26', 'N4', 'Động từ Thể Khả năng (可能形) & Trợ từ 「が」', 'N + が + V(khả năng)', 'Có thể làm V (Năng lực / Hoàn cảnh cho phép)', 'Thể hiện năng lực của chủ thể hoặc điều kiện cho phép thực hiện hành động. Tân ngữ đổi từ 「を」 sang 「が」.', 'Với 見える・聞こえる là nhìn/nghe tự nhiên lọt vào mắt tai.', '[{"japanese":"私は日本語が少し話せます。","hiragana":"わたしはにほんごがすこしはなせます。","vietnamese":"Tôi có thể nói được một chút tiếng Nhật."},{"japanese":"このカードで電車に乗れますか。","hiragana":"このカードのででんしゃにのれますか。","vietnamese":"Có thể đi tàu điện bằng thẻ này không?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L28-NAGARA', 'MINNA_N4', 'L28', 'N4', 'V1(bỏ ます) + ながら、V2', 'V1ます + ながら + V2', 'Vừa làm V1 vừa làm V2', 'Diễn tả hai hành động diễn ra đồng thời bởi cùng một chủ thể; V2 là hành động chính.', 'Chủ ngữ hai vế phải giống nhau.', '[{"japanese":"コーヒーを飲みながら新聞を読みます。","hiragana":"コーヒーをのみながらしんぶんをよみます。","vietnamese":"Tôi vừa uống cà phê vừa đọc báo."},{"japanese":"働きながら日本語学校に通っています。","hiragana":"はたらきながらにほんごがっこうにかよっています。","vietnamese":"Tôi vừa đi làm vừa học trường Nhật ngữ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L28-SHI-REASON', 'MINNA_N4', 'L28', 'N4', '～し、～し (Liệt kê tính chất / Nhiều lý do)', 'S1(thường) + し、S2(thường) + し', 'Vừa... lại vừa... / Nào là... lại còn...', 'Liệt kê nhiều đặc điểm đồng nhất hoặc nhiều nguyên nhân dẫn đến kết luận.', 'Trước danh từ / tính từ な dùng 「だし」.', '[{"japanese":"駅からも近いし、部屋も広いし、ここに決めます。","hiragana":"えきからもちかいし、へやもひろいし、ここにきめます。","vietnamese":"Vừa gần ga lại vừa rộng rãi, tôi quyết định chọn phòng này."},{"japanese":"彼は漢字も書けるし、英語も話せます。","hiragana":"かれはかんじもかけるし、えいごもはなせます。","vietnamese":"Cậu ấy vừa viết được Kanji, lại vừa nói được tiếng Anh."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L28-TE-SHIMAU', 'MINNA_N4', 'L28', 'N4', 'Vて しまいます (Hoàn tất / Tiếc nuối lỡ mất)', 'Vて + しまいます', 'Làm xong hẳn / Lỡ làm mất rồi', 'Nhấn mạnh hành động đã kết thúc hoàn toàn hoặc bày tỏ cảm giác hối tiếc ngoài ý muốn.', 'Văn nói thân mật rút gọn thành 「～ちゃう / ～じゃう」.', '[{"japanese":"宿題を全部やってしまいました。","hiragana":"しゅくだいをぜんぶやってしまいました。","vietnamese":"Tôi đã làm xong hết toàn bộ bài tập rồi."},{"japanese":"電車の中に傘を忘れてしまいました。","hiragana":"でんしゃのなかにかさをわすれてしまいました。","vietnamese":"Tôi lỡ để quên mất chiếc ô trên tàu rồi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L30-TE-ARU', 'MINNA_N4', 'L30', 'N4', 'N が V(tha động từ)て あります', 'N + が + V(tha)て + あります', 'Có sẵn cái gì đang được (ai đó) chuẩn bị / đặt để', 'Miêu tả trạng thái kết quả của hành động có chủ đích từ trước (ví dụ chữ viết trên bảng, hoa cắm sẵn).', 'Phân biệt với 「V(tự) + ている」 chỉ trạng thái tự nhiên.', '[{"japanese":"カレンダーに予定が書いてあります。","hiragana":"カレンダーによていがかいてあります。","vietnamese":"Trên lịch có ghi sẵn kế hoạch."},{"japanese":"冷蔵庫にビールが冷やしてあります。","hiragana":"れいぞうこにビールがひやしてあります。","vietnamese":"Trong tủ lạnh có ướp lạnh sẵn bia."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L30-TE-OKU', 'MINNA_N4', 'L30', 'N4', 'Vて おきます (Chuẩn bị trước)', 'Vて + おきます', 'Làm sẵn / Chuẩn bị trước cho việc gì', 'Thực hiện trước hành động để chuẩn bị cho sự việc sắp tới hoặc giữ nguyên hiện trạng.', 'Văn nói thân mật: 「～とく」.', '[{"japanese":"会議の前に資料をコピーしておきます。","hiragana":"かいぎのまえにしりょうをコピーしておきます。","vietnamese":"Trước cuộc họp tôi photo sẵn tài liệu."},{"japanese":"テストまでに漢字を復習しておきます。","hiragana":"テストまでにかんじをふくしゅうしておきます。","vietnamese":"Trước kỳ thi tôi ôn tập trước chữ Hán."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L30-VOLITIONAL-TO-OMOU', 'MINNA_N4', 'L30', 'N4', 'Thể Ý chí (Vよう) + と 思っています', 'V(ý chí) + と 思っています', 'Tôi đang dự định / tính sẽ làm...', 'Bày tỏ ý định nung nấu trong lòng đã có từ trước hoặc kế hoạch tương đối chắc chắn.', 'Nếu quyết tâm ngay tại thời điểm nói dùng 「～ようと思います」.', '[{"japanese":"夏休みに北海道へ旅行しようと思っています。","hiragana":"なつやすみにほっかいどうへりょこうしようとおもっています。","vietnamese":"Nghỉ hè tôi đang tính đi du lịch Hokkaido."},{"japanese":"今年中にN4を取ろうと思っています。","hiragana":"ことしじゅうにN4をとろうとおもっています。","vietnamese":"Trong năm nay tôi dự định lấy bằng N4."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L32-HOU-GA-II', 'MINNA_N4', 'L32', 'N4', 'Lời khuyên: Vた / Vない + ほうがいい', 'Vた + ほうがいい / Vない + ほうがいい', 'Nên làm... / Không nên làm...', 'Đưa ra lời khuyên trực tiếp dựa trên tình huống thực tế.', 'Không dùng cho bề trên trực tiếp nếu muốn giữ xã giao mềm.', '[{"japanese":"熱があるなら、今日は休んだほうがいいですよ。","hiragana":"ねつがあるなら、きょうはやすんだほうがいいですよ。","vietnamese":"Nếu bị sốt thì hôm nay bạn nên nghỉ đi nhé."},{"japanese":"夜遅くに甘いものを食べないほうがいいです。","hiragana":"よるおそくにあまいものをたべないほうがいいです。","vietnamese":"Đêm muộn thì không nên ăn đồ ngọt."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L32-IMPERATIVE-PROHIBITIVE', 'MINNA_N4', 'L32', 'N4', 'Thể Mệnh lệnh (しろ) & Cấm chỉ (するな)', 'V(mệnh lệnh) / Vる + な', 'Hãy làm đi! / Cấm không được làm!', 'Dùng trong khẩu hiệu, biển báo giao thông, huấn luyện viên cổ vũ hoặc trong tình huống khẩn cấp.', 'Không dùng trong hội thoại lịch sự thông thường.', '[{"japanese":"危ないから、早く逃げろ！","hiragana":"あぶないから、はやくにげろ！","vietnamese":"Nguy hiểm đấy, chạy ngay đi!"},{"japanese":"試験中なので、隣を見るな。","hiragana":"しけんちゅうなので、となりをみるな。","vietnamese":"Đang trong giờ thi, cấm nhìn sang bên cạnh."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L32-TO-IU-IMI', 'MINNA_N4', 'L32', 'N4', 'X は Y と いう 意味です', 'N1 + は + N2 + という意味です', 'X có nghĩa là Y', 'Giải thích ý nghĩa của một từ vựng, chữ Hán hoặc ký hiệu/biển báo.', 'Thường gặp trong đọc hiểu thông báo và giao tiếp hỏi nghĩa từ mới.', '[{"japanese":"「立入禁止」はここに入ってはいけないという意味です。","hiragana":"「たちいりきんし」はここにはいってはいけないといういみです。","vietnamese":"\"Cấm vào\" nghĩa là không được phép đi vào đây."},{"japanese":"このマークは「非常口」という意味です。","hiragana":"このマークは「ひじょうぐち」といういみです。","vietnamese":"Ký hiệu này có nghĩa là \"Lối thoát hiểm\"."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L34-TOORI-NI', 'MINNA_N4', 'L34', 'N4', 'Vた / Nの + とおりに', 'Vた + とおりに / N + の + とおりに', 'Làm theo đúng như... đã nói / hướng dẫn', 'Làm giống y hệt nội dung đã nghe, đã nhìn hoặc theo tài liệu hướng dẫn.', 'N + どおりに cũng dùng khi nối trực tiếp danh từ.', '[{"japanese":"説明書のとおりに組み立てました。","hiragana":"せつめいしょのとおりにくみたてました。","vietnamese":"Tôi đã lắp ráp theo đúng sách hướng dẫn."},{"japanese":"先生が書いたとおりに漢字を書いてみます。","hiragana":"せんせいがかいたとおりにかんじをかいてみます。","vietnamese":"Tôi thử viết chữ Hán giống theo đúng thầy đã viết."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L34-NAIDE-ATO-DE', 'MINNA_N4', 'L34', 'N4', 'Vないで / Vた + あとで', 'Vない + で / Vた / Nの + あとで', 'Không làm A mà làm B / Sau khi làm A rồi làm B', '「V1ないでV2」: làm V2 trong trạng thái bỏ qua V1. 「V1たあとでV2」: sau khi V1 hoàn tất rồi làm V2.', 'Thay cho 「てから」, 「あとで」 đi được với Danh từ + の.', '[{"japanese":"辞書を使わないで、この本を読んでみます。","hiragana":"じしょをつかわないで、このほんをよんでみます。","vietnamese":"Tôi thử đọc cuốn sách này mà không dùng từ điển."},{"japanese":"仕事が終わったあとで、友達と食事します。","hiragana":"しごとがおわったあとで、ともだちとしょくじします。","vietnamese":"Sau khi xong việc tôi sẽ đi ăn với bạn."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L34-BA-CONDITION', 'MINNA_N4', 'L34', 'N4', 'Thể Điều kiện 「～ば」 & 「～なら」', 'Vえば / Aければ / N + なら', 'Nếu... thì... (Điều kiện giả định)', '「～ば」 diễn tả điều kiện cần để kết quả xảy ra; 「～なら」 tiếp nhận chủ đề đối phương vừa nói để đưa ra lời khuyên.', 'Không dùng chủ ý người nói ở vế sau với ～ば khi vế 1 là động từ hành động của chính mình.', '[{"japanese":"安く買いたければ、この店がいいですよ。","hiragana":"やすくかいたければ、このみせがいいですよ。","vietnamese":"Nếu muốn mua rẻ thì cửa hàng này tốt đấy."},{"japanese":"日本料理なら、お寿司が一番好きです。","hiragana":"にほんりょうりなら、おすしがいちばんすきです。","vietnamese":"Nếu nói về món Nhật thì tôi thích Sushi nhất."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L36-YOUNI-GOAL', 'MINNA_N4', 'L36', 'N4', 'Vる / Vない + ように、～ (Để cho / Sao cho)', 'Vる/Vない + ように', 'Để có thể... / Để tránh...', 'Diễn tả mục tiêu đạt được trạng thái mong muốn; phía trước thường là động từ khả năng, phủ định hoặc tự động từ.', 'Khác với 「ために」 đi với động từ có chủ ý.', '[{"japanese":"日本語が話せるように、毎日練習しています。","hiragana":"にほんごがはなせるように、まいにちれんしゅうしています。","vietnamese":"Tôi luyện tập mỗi ngày để có thể nói tiếng Nhật."},{"japanese":"後ろの人にも聞こえるように、大きい声で話します。","hiragana":"うしろのひとにもきこえるように、おおきいこえではなします。","vietnamese":"Tôi nói to để người phía sau cũng có thể nghe thấy."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L36-YOUNI-NARU', 'MINNA_N4', 'L36', 'N4', 'Vる + ように なりました / ように しています', 'Vる + ようになる / Vる/Vない + ようにしている', 'Đã trở nên có thể... / Cố gắng duy trì thói quen...', '「ようになる」 diễn tả sự thay đổi năng lực/thói quen. 「ようにする」 diễn tả nỗ lực cố gắng làm điều gì đó thường xuyên.', 'Rất hay xuất hiện trong đề N4 & N3.', '[{"japanese":"やっと日本の新聞が読めるようになりました。","hiragana":"やっとにほんのしんぶんがよめるようになりました。","vietnamese":"Cuối cùng tôi cũng đã đọc được báo tiếng Nhật."},{"japanese":"寝る前に携帯を見ないようにしています。","hiragana":"ねるまえにけいたいをみないようにしています。","vietnamese":"Tôi cố gắng không xem điện thoại trước khi ngủ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L36-PASSIVE-VOICE', 'MINNA_N4', 'L36', 'N4', 'Thể Bị động (受身形): ～られる・～かれる', 'N(người) + に + V(bị động)', 'Bị / Được ai đó làm gì', 'Diễn tả người nói chịu tác động từ người khác (khen/rủ hoặc bị làm phiền/mưa rơi vào), hoặc câu bị động không chủ ngữ về sự kiện/sản phẩm.', 'Người thực hiện hành động đi với trợ từ 「に」 (hoặc 「によって」 khi là phát minh/tác phẩm).', '[{"japanese":"朝、満員電車の中で足を踏まれました。","hiragana":"あさ、まんいんでんしゃのなかであしをふまれました。","vietnamese":"Sáng nay trên tàu đông đúc tôi bị giẫm lên chân."},{"japanese":"この小説は世界中で読まれています。","hiragana":"このしょうせつはせかいじゅうでよまれています。","vietnamese":"Cuốn tiểu thuyết này được đọc trên khắp thế giới."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L38-NO-DESU-GA', 'MINNA_N4', 'L38', 'N4', 'Vる + のは / のが / のを', 'Vる + のは + Adj / Vる + のが + 好き/上手', 'Việc làm V... (Danh từ hóa động từ)', 'Biến một cụm động từ hoặc tính từ thành danh từ để làm chủ ngữ (のは), vị ngữ sở thích/giỏi kém (のが), hoặc tân ngữ (のを).', '「のが好き/上手/下手/早い」 dùng 「の」 tự nhiên hơn 「こと」.', '[{"japanese":"朝早く起きるのは少し大変です。","hiragana":"あさはやくおきるのはすこしたいへんです。","vietnamese":"Việc dậy sớm vào buổi sáng hơi vất vả một chút."},{"japanese":"友達に誕生日のプレゼントを渡すのを忘れました。","hiragana":"ともだちにたんじょうびのプレゼントをわたすのをわすれました。","vietnamese":"Tôi quên mất việc đưa quà sinh nhật cho bạn."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L38-TE-REASON', 'MINNA_N4', 'L38', 'N4', 'Nguyên nhân cảm xúc / trạng thái: Vて / Aくて / Nで', 'Vて・Aくて・Nで + Cảm xúc', 'Vì... nên... (cảm xúc / không thể làm gì)', 'Trình bày nguyên nhân tự nhiên dẫn đến cảm xúc (vui/buồn/giật mình) hoặc tình trạng không mong muốn ở vế sau.', 'Vế sau KHÔNG dùng câu mệnh lệnh, nhờ vả hay rủ rê.', '[{"japanese":"試験に合格できて、本当に嬉しいです。","hiragana":"しけんにごうかくできて、ほんとうにうれしいです。","vietnamese":"Thi đỗ được kỳ thi tôi thực sự rất vui."},{"japanese":"道が複雑で、なかなか駅に着きませんでした。","hiragana":"みちがふくざつで、なかなかえきにつきませんでした。","vietnamese":"Vì đường phức tạp nên mãi tôi mới tới được ga."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L38-NODE-POLITE-REASON', 'MINNA_N4', 'L38', 'N4', '～ので (Lý do nhẹ nhàng, lịch sự)', 'V/Aい + ので / N/Aな + なので', 'Vì... cho nên...', 'Trình bày nguyên nhân một cách khách quan, lịch sự, dùng được khi xin phép hoặc từ chối.', 'Nhẹ nhàng hơn 「から」.', '[{"japanese":"バスが遅れたので、会議に間に合いませんでした。","hiragana":"バスがおくれたので、かいぎにまにあいませんでした。","vietnamese":"Vì xe buýt đến muộn nên tôi không kịp cuộc họp."},{"japanese":"明日は祝日なので、銀行はお休みです。","hiragana":"あしたはしゅくじつなので、ぎんこうはおやすみです。","vietnamese":"Vì ngày mai là ngày lễ nên ngân hàng nghỉ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L40-KADOUKA', 'MINNA_N4', 'L40', 'N4', 'Câu hỏi lồng: [Từ để hỏi] ～か / ～かどうか', 'S(thường) + かどうか + 分かりません', 'Có... hay không / ...như thế nào (làm tân ngữ cho 知っています/分かりません)', 'Lồng một câu hỏi vào trong câu lớn để hỏi hoặc xác nhận thông tin.', 'Với danh từ/tính từ な bỏ だ trước か/かどうか.', '[{"japanese":"パーティーに行けるかどうか、まだ決めていません。","hiragana":"パーティーにいけるかどうか、まだきめていません。","vietnamese":"Tôi vẫn chưa quyết định xem có đi tiệc được hay không."},{"japanese":"テストが何時に始まるか教えてください。","hiragana":"テストがなんじにはじまるかおしえてください。","vietnamese":"Xin hãy cho tôi biết bài thi bắt đầu lúc mấy giờ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L40-TEMIRU', 'MINNA_N4', 'L40', 'N4', 'Vて みます (Thử làm xem sao)', 'Vて + みます', 'Thử làm... xem kết quả thế nào', 'Thử làm một hành động để kiểm chứng, trải nghiệm hoặc xem cảm giác.', 'Dùng rất nhiều khi thử đồ, nếm đồ ăn, thử cách làm mới.', '[{"japanese":"とても美味しそうなので、食べてみます。","hiragana":"とてもおいしそうなので、たべてみます。","vietnamese":"Trông ngon quá nên tôi ăn thử xem sao."},{"japanese":"日本のアニメを字幕なしで見てみましたか。","hiragana":"にほんのアニメをじまくなしでみてみましたか。","vietnamese":"Bạn đã thử xem Anime Nhật không phụ đề bao giờ chưa?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L40-SOU-DESU-APPEAR', 'MINNA_N4', 'L40', 'N4', 'Vます / Aい / Aな + そうです (Có vẻ sắp / Trông có vẻ)', 'Vます + そうです / Adj(gốc) + そうです', 'Trông có vẻ... / Sắp sửa...', 'Dự đoán trực quan dựa vào những gì mắt nhìn thấy (mây đen sắp mưa, bánh trông ngon).', 'Tính từ 「いい」 đổi thành 「よさそうです」, 「ない」 thành 「なさそうです」.', '[{"japanese":"このケーキはとても美味しそうですね。","hiragana":"このケーキはとてもおいしそうですね。","vietnamese":"Cái bánh này trông có vẻ ngon quá nhỉ."},{"japanese":"ボタンが取れそうですから気をつけて。","hiragana":"ボタンがとれそうですからきをつけて。","vietnamese":"Cúc áo sắp rơi ra rồi đấy nên cẩn thận nhé."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L44-YASUI-NIKUI', 'MINNA_N4', 'L44', 'N4', 'V(bỏ ます) + やすい / にくい', 'Vます + やすい / Vます + にくい', 'Dễ làm... / Khó làm...', 'Diễn tả tính chất của sự vật khiến hành động dễ hoặc khó thực hiện.', 'Chia như tính từ đuôi い.', '[{"japanese":"駅に近いので、このアパートは住みやすいです。","hiragana":"えきにちかいので、このアパートはすみやすいです。","vietnamese":"Vì gần ga nên căn hộ này rất dễ sống."},{"japanese":"先生の字は少し小さくて読みにくいです。","hiragana":"せんせいのじはすこしちいさくてよみにくいです。","vietnamese":"Chữ của thầy hơi nhỏ nên khó đọc."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L44-BA-AI-WA', 'MINNA_N4', 'L44', 'N4', '～場合は、～ (Trong trường hợp...)', 'Vる/Nの + 場合は', 'Trong trường hợp / Nếu xảy ra tình huống...', 'Đưa ra cách xử lý khi một tình huống giả định (thường ít mong muốn hoặc quy định) xảy ra.', 'Hay gặp trong bảng quy định nơi công cộng.', '[{"japanese":"電車に遅れる場合は、すぐ電話してください。","hiragana":"でんしゃにおくれるばあいは、すぐでんわしてください。","vietnamese":"Trường hợp bị trễ tàu thì hãy gọi điện ngay nhé."},{"japanese":"使い方が分からない場合は、店員に聞いてください。","hiragana":"つかいかたがわからないばあいは、てんいんにきいてください。","vietnamese":"Trường hợp không biết cách dùng hãy hỏi nhân viên."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L44-TOKORO-ASPECT', 'MINNA_N4', 'L44', 'N4', 'Vる / Vている / Vた + ところ', 'Vる/Vている/Vた + ところです', 'Vừa mới định / Đang ngay lúc / Vừa mới xong...', 'Nhấn mạnh thời điểm chính xác của hành động: sắp sửa (Vる), đang diễn ra (Vている), hoặc vừa mới kết thúc tức thì (Vた).', 'Thường đi với これから (sắp), 今 (đang), たった今 (vừa mới).', '[{"japanese":"これから昼ご飯を食べるところです。","hiragana":"これからひるごはんをたべるところです。","vietnamese":"Bây giờ tôi chuẩn bị ăn trưa đây."},{"japanese":"ただいま資料をコピーしているところです。","hiragana":"ただいましりょうをコピーしているところです。","vietnamese":"Hiện tại tôi đang photo tài liệu đây ạ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L47-SOU-DESU-HEARSAY', 'MINNA_N4', 'L47', 'N4', 'Nghe nói: [Thể thông thường] + そうです', 'S(thường) + そうです', 'Nghe nói là... / Theo thông tin nghe được thì...', 'Truyền đạt lại thông tin mình nghe từ người khác, báo chí, dự báo thời tiết.', 'Khác với 「trông có vẻ」 là N/Aな có giữ 「だ」.', '[{"japanese":"ミラーさんは来月結婚するそうです。","hiragana":"ミラーさんはらいげつけっこんするそうです。","vietnamese":"Nghe nói tháng sau anh Miller sẽ kết hôn đấy."},{"japanese":"あのレストランのケーキはとても美味しいそうです。","hiragana":"あのレストランのケーキはとてもおいしいそうです。","vietnamese":"Nghe nói bánh ngọt của nhà hàng kia ngon lắm."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L47-SONKEIGO', 'MINNA_N4', 'L47', 'N4', 'Tôn kính ngữ (尊敬語): お + Vます + に なります / 特別動詞', 'お + Vます + になります', 'Ngài / Thầy / Sếp làm (Nâng cao hành động đối phương)', 'Dùng để nói về hành động của người bề trên (thầy cô, sếp, khách hàng) một cách tôn kính.', 'Tuyệt đối không dùng Tôn kính ngữ cho hành động của chính mình.', '[{"japanese":"部長は今、資料をご覧になっています。","hiragana":"ぶちょうはいま、しりょうをごらんになっています。","vietnamese":"Trưởng phòng hiện đang xem tài liệu ạ."},{"japanese":"どうぞ温かいお茶をお召し上がりください。","hiragana":"どうぞあたたかいおちゃをおめしあがりください。","vietnamese":"Xin mời ngài dùng trà nóng ạ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-MNN-L47-KENJOUGO', 'MINNA_N4', 'L47', 'N4', 'Khiêm nhường ngữ (謙譲語): お + Vます + します / 特別動詞', 'お + Vます + します / ご + N(Hán) + します', 'Em / Tôi xin phép làm (Hạ mình xuống với người trên)', 'Dùng cho hành động của chính mình (hoặc người nhà mình) hướng tới người bề trên / khách hàng.', 'Dùng kèm câu xin phép hoặc phục vụ khách hàng.', '[{"japanese":"明日、午後三時に事務所へ伺います。","hiragana":"あした、ごごさんじにじむしょへうかがいます。","vietnamese":"Ngày mai 3 giờ chiều tôi xin phép ghé văn phòng ạ."},{"japanese":"ただいまスケジュールをご案内いたします。","hiragana":"ただいまスケジュールをごあんないいたします。","vietnamese":"Ngay sau đây tôi xin hướng dẫn lịch trình ạ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-01-TEKURU-TEIKU', 'SHINKANZEN_N4', 'SK4-01', 'N4', 'Vて きました / Vて いきます', 'Vて + くる / Vて + いく', 'Bắt đầu / Dần dần trở nên (đến hiện tại) vs Tiếp diễn về tương lai', 'Diễn tả sự biến đổi kéo dài từ quá khứ tới hiện tại (てきた) hoặc tiếp tục tiến triển từ hiện tại sang tương lai (ていく).', 'Hay dùng chung với だんだん・これから.', '[{"japanese":"急に寒い風が吹いてきました。","hiragana":"きゅうにかぜがふいてきました。","vietnamese":"Đột nhiên gió lạnh bắt đầu thổi tới."},{"japanese":"これからも日本語の勉強を続けていきます。","hiragana":"これからもにほんごのべんきょうをつづけていきます。","vietnamese":"Từ nay về sau tôi vẫn sẽ tiếp tục học tiếng Nhật."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-01-TABAKARI', 'SHINKANZEN_N4', 'SK4-01', 'N4', 'Vた ばかりです (Vừa mới xong — theo cảm nhận)', 'Vた + ばかりです', 'Vừa mới làm xong (cảm giác thời gian còn rất gần)', 'Diễn tả sự việc vừa mới diễn ra chưa lâu theo cảm nhận chủ quan của người nói (có thể vài phút hoặc vài tháng trước).', 'Khác 「ところ」 ở chỗ vẫn dùng được nếu sự việc cách đây vài tuần/tháng (VD: mới tới Nhật 1 tháng).', '[{"japanese":"さっき昼ご飯を食べたばかりなので、まだお腹がいっぱいです。","hiragana":"さっきひるごはんをたべたばかりなので、まだおなかがいっぱいです。","vietnamese":"Vì vừa mới ăn trưa lúc nãy nên giờ vẫn no."},{"japanese":"去年卒業したばかりなのに、もう仕事を任されている。","hiragana":"きょねんそつぎょうしたばかりなのに、もうしごとをまかされている。","vietnamese":"Mới tốt nghiệp năm ngoái mà giờ đã được giao việc lớn rồi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-01-SHIKA-NAI', 'SHINKANZEN_N4', 'SK4-01', 'N4', 'N + しか ～ない (Chỉ... mà thôi)', 'N + しか + Vない', 'Chỉ có... (không còn lựa chọn/số lượng nhiều hơn)', 'Luôn đi kèm động từ phủ định để nhấn mạnh sự ít ỏi, giới hạn không như mong đợi.', 'Không dùng trợ từ 「が」「を」 trước 「しか」; 「で・に・へ」 đặt trước 「しか」.', '[{"japanese":"忙しいので、一日五時間しか寝られません。","hiragana":"いそがしいので、いちにちごじかんしかねられません。","vietnamese":"Vì bận nên một ngày tôi chỉ ngủ được có 5 tiếng."},{"japanese":"ひらがなしか読めません。","hiragana":"ひらがなしかよめません。","vietnamese":"Tôi chỉ đọc được mỗi chữ Hiragana thôi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-02-SHIEKI', 'SHINKANZEN_N4', 'SK4-02', 'N4', 'Thể Sai khiến (使役形): ～させる・～せる', 'N(người) + に/を + V(sai khiến)', 'Bắt làm / Cho phép làm', 'Người có thẩm quyền (bố mẹ, sếp, thầy) bắt buộc hoặc cho phép người dưới làm hành động gì.', 'Tự động từ dùng 「NをVさせる」; Tha động từ dùng 「Nに～をVさせる」.', '[{"japanese":"部長は部下を大阪へ出張させました。","hiragana":"ぶちょうはぶかをおおさかへしゅっちょうさせました。","vietnamese":"Trưởng phòng cử nhân viên đi công tác Osaka."},{"japanese":"子供が好きな音楽を習わせてあげます。","hiragana":"こどもがすきなおんがくをならわせてあげます。","vietnamese":"Tôi cho phép con học môn âm nhạc mà bé thích."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-02-SASETE-KUDASAI', 'SHINKANZEN_N4', 'SK4-02', 'N4', 'V(sai khiến)て ください / させていただけませんか', 'V(sai khiến)て + ください', 'Xin hãy cho phép tôi được làm...', 'Lịch sự xin phép người khác cho mình được làm một việc gì đó.', 'Rất thường dùng khi xin nghỉ phép hoặc xin trình bày ý kiến.', '[{"japanese":"自分の意見を言わせてください。","hiragana":"じぶんのいけんをいわせてください。","vietnamese":"Xin hãy cho phép tôi nói ý kiến của mình."},{"japanese":"体調が悪いので、今日は早退させていただけませんか。","hiragana":"たいちょうがわるいので、きょうはそうたいさせていただけませんか。","vietnamese":"Vì sức khỏe không tốt, hôm nay cho phép tôi về sớm được không ạ?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-02-SHIEKI-UKEMI', 'SHINKANZEN_N4', 'SK4-02', 'N4', 'Thể Sai khiến Bị động (使役受身): ～させられる', 'N + に + V(sai khiến bị động)', 'Bị bắt ép phải làm (dù không muốn)', 'Diễn tả tâm trạng miễn cưỡng của người bị người khác (thầy, sếp, cha mẹ) ép làm việc gì.', 'Trong văn nói nhóm I rút gọn thành 「～される」 (trừ động từ tận cùng là す).', '[{"japanese":"先生に漢字を百回書かされました。","hiragana":"せんせいにかんじをひゃっかいかかされました。","vietnamese":"Tôi bị thầy bắt chép chữ Hán 100 lần."},{"japanese":"嫌いな野菜を無理やり食べさせられました。","hiragana":"きらいなやさいをむりやりたべさせられました。","vietnamese":"Tôi bị ép ăn món rau mà mình ghét."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-03-HAZU-DA', 'SHINKANZEN_N4', 'SK4-03', 'N4', '[Thể thông thường] + はずです', 'Thể thường + はずです', 'Chắc chắn là... (dựa trên căn cứ suy luận)', 'Thể hiện sự tin chắc có cơ sở logic. Phủ định: 「～はずがありません」 (Không đời nào có chuyện...).', 'Không dùng cho điều mình trực tiếp làm ở hiện tại.', '[{"japanese":"彼は毎日勉強しているから、試験に合格するはずです。","hiragana":"かれはまいにちべんきょうしているから、しけんにごうかくするはずです。","vietnamese":"Vì cậu ấy học mỗi ngày nên chắc chắn sẽ đỗ kỳ thi."},{"japanese":"そんな難しい漢字、小学生に読めるはずがありません。","hiragana":"そんなむずかしいかんじ、しょうがくせいによめるはずがありません。","vietnamese":"Chữ Hán khó thế thì học sinh tiểu học không thể nào đọc được."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-03-WA-KE-DEWA-NAI', 'SHINKANZEN_N4', 'SK4-03', 'N4', '～わけではありません / ～てばかりいる', 'Thể thường + わけではない / Vて + ばかりいる', 'Không hẳn là... / Chỉ toàn làm...', '「わけではない」 phủ định một phần để tránh hiểu nhầm hoàn toàn. 「てばかりいる」 chê trách ai đó cứ lặp đi lặp lại một việc mãi.', '「甘いものが嫌いなわけではありません」: Không hẳn là tôi ghét đồ ngọt (chỉ đang ăn kiêng).', '[{"japanese":"お金がないわけではありませんが、節約したいだけです。","hiragana":"おかねがないわけではありませんが、せつやくしたいだけです。","vietnamese":"Không phải là không có tiền, chỉ là tôi muốn tiết kiệm thôi."},{"japanese":"弟は勉強しないでゲームをしてばかりいます。","hiragana":"おとうとはべんきょうしないでゲームをしてばかりいます。","vietnamese":"Em trai tôi không chịu học mà cứ chơi game suốt."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-03-SHIKATA-GA-NAI', 'SHINKANZEN_N4', 'SK4-03', 'N4', '～てほしい / ～といいですね', 'Nに + Vて + ほしい', 'Mong muốn ai đó làm gì cho mình / Chúc cho...', '「NにVてほしい」 bày tỏ mong muốn người khác hành động. 「～といいですね」 chúc điều tốt đẹp xảy ra.', 'Không dùng 「てほしい」 để yêu cầu trực tiếp người bề trên.', '[{"japanese":"大事なことなので、誰にも言わないでほしいです。","hiragana":"だいじなことなので、だれにもいわないでほしいです。","vietnamese":"Vì là chuyện quan trọng nên tôi mong bạn đừng nói với ai."},{"japanese":"明日の運動会、晴れるといいですね。","hiragana":"あしたのうんどうかい、はれるといいですね。","vietnamese":"Hội thao ngày mai trời nắng đẹp thì tốt quá nhỉ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-04-OKAGE-DE', 'SHINKANZEN_N4', 'SK4-04', 'N4', '～おかげで (Nhờ có — kết quả tốt)', 'V(thường)/Nの + おかげで', 'Nhờ có... mà (kết quả tích cực)', 'Bày tỏ lòng biết ơn vì nhờ ai đó hoặc sự việc nào đó mà kết quả tốt xảy ra.', 'Không dùng cho kết quả tiêu cực.', '[{"japanese":"毎日復習したおかげで、試験に合格できました。","hiragana":"まいにちふくしゅうしたおかげで、しけんにごうかくできました。","vietnamese":"Nhờ ôn tập mỗi ngày mà tôi đã thi đỗ."},{"japanese":"便利なアプリのおかげで漢字をたくさん覚えました。","hiragana":"べんりなアプリのおかげでかんじをたくさんおぼえました。","vietnamese":"Nhờ ứng dụng tiện lợi mà tôi nhớ được nhiều chữ Hán."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-04-SEI-DE', 'SHINKANZEN_N4', 'SK4-04', 'N4', '～せいで / ～せいだ (Tại vì — kết quả xấu)', 'V(thường)/Nの + せいで', 'Tại vì... nên mới bị (đổ lỗi / kết quả tiêu cực)', 'Diễn tả nguyên nhân dẫn đến kết quả bất lợi, thất vọng hoặc rắc rối.', 'Cũng hay dùng kết thúc câu 「～せいだ」.', '[{"japanese":"台風のせいで、飛行機が飛ばなくなりました。","hiragana":"たいふうのせいで、ひこうきがとばなくなりました。","vietnamese":"Tại vì cơn bão nên máy bay không cất cánh được."},{"japanese":"ゲームをしすぎたせいで、目が悪くなりました。","hiragana":"ゲームをしすぎたせいで、めがわるくなりました。","vietnamese":"Tại chơi game quá nhiều nên mắt bị kém đi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-04-NONI-CONTRAST', 'SHINKANZEN_N4', 'SK4-04', 'N4', '～のに (Tuy... vậy mà lại...)', 'V/Aい + のに / N/Aな + なのに', 'Thế mà / Mặc dù vậy mà lại (ngạc nhiên, trách móc)', 'Diễn tả kết quả trái ngược hoàn toàn với điều kiện vế 1, mang hàm ý bất ngờ hoặc thất vọng.', 'Chú ý N và Tính từ な phải thêm 「な」 trước 「のに」.', '[{"japanese":"一生懸命勉強したのに、合格できませんでした。","hiragana":"いっしょうけんめいべんきょうしたのに、ごうかくできませんでした。","vietnamese":"Dù đã học hết sức vậy mà vẫn không đỗ."},{"japanese":"今日は日曜日なのに、仕事に行かなければなりません。","hiragana":"きょうはにちようびなのに、しごとにいかなければなりません。","vietnamese":"Hôm nay là Chủ nhật vậy mà vẫn phải đi làm."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-05-YOU-DA', 'SHINKANZEN_N4', 'SK4-05', 'N4', '～ようです / ～みたいです', 'Thể thường + ようです / N + みたいです', 'Hình như là... / Giống như là...', 'Suy đoán dựa vào ngũ quan quan sát (nghe/ngửi/nhìn) hoặc ví von giống cái gì. 「みたい」 dùng nhiều trong hội thoại.', 'Khi bổ nghĩa danh từ: 「～ようなN」 / 「～みたいなN」.', '[{"japanese":"誰もいませんね。みんなもう帰ったようです。","hiragana":"だれもいませんね。みんなもうかえったようです。","vietnamese":"Không có ai cả nhỉ. Hình như mọi người về hết rồi."},{"japanese":"彼はまるで日本人のように日本語を話します。","hiragana":"かれはまるでにほんじんのようににほんごをはなします。","vietnamese":"Anh ấy nói tiếng Nhật cứ như thể người Nhật vậy."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-05-RASHII-INFERENCE', 'SHINKANZEN_N4', 'SK4-05', 'N4', '～らしいです (Nghe đâu / Rất đúng chất...)', 'S(thường) + らしいです / N + らしい', 'Nghe nói có vẻ là... / Đúng chất...', 'Nghĩa 1: Phỏng đoán từ thông tin nghe kể có độ tin cậy nhất định. Nghĩa 2: N + らしい mang nét tiêu biểu của N đó.', '「男らしい」 (rất ra dáng đàn ông), 「春らしい天気」 (thời tiết đúng chất mùa xuân).', '[{"japanese":"新しい店はとても人気があるらしいですよ。","hiragana":"あたらしいみせはとてもにんきがあるらしいですよ。","vietnamese":"Nghe đâu cửa hàng mới đó được yêu thích lắm đấy."},{"japanese":"今日は春らしい暖かい日ですね。","hiragana":"きょうははるらしいあたたかいひですね。","vietnamese":"Hôm nay là một ngày ấm áp đúng chất mùa xuân nhỉ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-05-TAME-NI', 'SHINKANZEN_N4', 'SK4-05', 'N4', 'Mục đích & Nguyên nhân: ～ために', 'Vる + ために / N + の + ために', 'Vì mục đích... / Do nguyên nhân...', '「Vる/Nの + ために」 chỉ mục đích phấn đấu (đi với động từ có ý chí); cũng có thể chỉ nguyên nhân ở văn viết trang trọng.', 'Chủ ngữ hai vế khi diễn tả mục đích phải giống nhau.', '[{"japanese":"健康のために、毎朝ジョギングをしています。","hiragana":"けんこうのために、まいあさジョギングをしています。","vietnamese":"Vì sức khỏe nên mỗi sáng tôi đều chạy bộ."},{"japanese":"家族のために美味しい料理を作りたいです。","hiragana":"かぞくのためにおいしいりょうりをつくりたいです。","vietnamese":"Tôi muốn nấu món ăn ngon cho gia đình."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-06-KA-SHIRA-KANA', 'SHINKANZEN_N4', 'SK4-06', 'N4', '～か知っていますか / ～ながら・～まま', 'Vた + まま / Vない + まま', 'Vẫn giữ nguyên trạng thái... (không thay đổi)', 'Làm hành động V2 trong khi vẫn giữ nguyên trạng thái V1/Danh từ trước đó.', 'VD: 靴を履いたまま部屋に入る (giữ nguyên giày đi vào phòng).', '[{"japanese":"靴を履いたまま家に入らないでください。","hiragana":"くつをはいたままいえにはいらないでください。","vietnamese":"Đừng giữ nguyên giày mà đi vào trong nhà nhé."},{"japanese":"眼鏡をかけたままお風呂に入ってしまいました。","hiragana":"めがねをかけたままおふろにはいってしまいました。","vietnamese":"Tôi lỡ đeo nguyên kính mắt đi vào bồn tắm."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-06-TO-SHITEMO-TEMO', 'SHINKANZEN_N4', 'SK4-06', 'N4', '～のに・～ても (Tổng ôn đối lập)', 'いくら + Vても/Aくても', 'Cho dù có... đi chăng nữa thì vẫn...', 'Giả định điều kiện ngược đời nhưng kết quả vẫn không đổi; hay đi kèm 「いくら・どんなに」.', '「いくら高くても買います」 (Dù đắt đến mấy tôi cũng mua).', '[{"japanese":"どんなに忙しくても、朝ご飯は必ず食べます。","hiragana":"どんなにいそがしくても、あさごはんはかならずたべます。","vietnamese":"Dù bận thế nào thì sáng nào tôi cũng ăn sáng."},{"japanese":"雨が降っても、試合は予定どおり行われます。","hiragana":"あめがふっても、しあいはよていどおりおこなわれます。","vietnamese":"Dù trời có mưa thì trận đấu vẫn diễn ra đúng lịch."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N4-SKZ-SK4-06-NARA-TARA-BA-TO', 'SHINKANZEN_N4', 'SK4-06', 'N4', 'Phân biệt 4 thể Điều kiện (と・ば・たら・なら)', 'Vる+と / Vえば / Vたら / Nなら', 'Hệ thống đầy đủ 4 điều kiện sơ-trung cấp', '「と」: tất yếu/máy móc. 「ば」: điều kiện giả thiết chung. 「たら」: nhấn mạnh thứ tự sau khi X xong. 「なら」: tiếp nhận chủ đề từ người nghe.', 'Luyện phân biệt kỹ là chìa khóa đạt điểm tối đa ngữ pháp N4.', '[{"japanese":"右へ曲がると、大きな本屋が見えます。","hiragana":"みぎへまがると、おおきなほんやがみえます。","vietnamese":"Hễ rẽ phải là sẽ nhìn thấy hiệu sách lớn."},{"japanese":"北海道へ行くなら、冬より夏がおすすめです。","hiragana":"ほっかいどうへいくなら、ふゆよりなつがおすすめです。","vietnamese":"Nếu bạn đi Hokkaido thì mùa hè đáng đi hơn mùa đông đấy."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-UCHINI-01', 'SHINKANZEN_N3', 'L01', 'N3', '～うちに（状態）', 'Vている + うちに / Vない + うちに / Aい + うちに / Aな + な + うちに', 'Trong lúc (trạng thái chưa thay đổi) thì làm V...', 'Sử dụng khi muốn diễn tả ý: "Trong lúc trạng thái A vẫn chưa thay đổi, thì hãy tranh thủ làm việc B". Nếu để trạng thái A thay đổi thì sẽ khó hoặc không thể làm việc B được nữa.', 'Không dùng cho những việc xảy ra ngoài ý muốn ở vế B.', '[{"japanese":"忘れないうちに、予定をメモしてください。","hiragana":"わすれないうちに、よていをメモしてください。","vietnamese":"Hãy ghi lại kế hoạch trước khi quên."},{"japanese":"料理が熱いうちに、早く食べてください。","hiragana":"りょうりがあついうちに、はやくたべてください。","vietnamese":"Hãy ăn nhanh trong lúc thức ăn còn nóng."},{"japanese":"明るいうちに、家に帰りましょう。","hiragana":"あかるいうちに、いえにかえりましょう。","vietnamese":"Hãy về nhà trong lúc trời còn sáng."},{"japanese":"元気なうちに、いろいろな国へ旅行したいです。","hiragana":"げんきなうちに、いろいろなくにへりょこうしたいです。","vietnamese":"Tôi muốn đi du lịch nhiều nước trong lúc còn khỏe."},{"japanese":"若いうちに、たくさん本を読んだほうがいいです。","hiragana":"わかいうちに、たくさんほんをよんだほうがいいです。","vietnamese":"Nên đọc nhiều sách trong lúc còn trẻ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-UCHINI-02', 'SHINKANZEN_N3', 'L01', 'N3', '～うちに（変化）', 'Vる + うちに / Vている + うちに', 'Trong khi đang (làm V) thì có một sự thay đổi xảy ra...', 'Sử dụng khi muốn diễn tả ý: "Trong quá trình đang làm việc A, thì một sự thay đổi B diễn ra một cách tự nhiên (ngoài ý muốn)".', 'Vế B KHÔNG PHẢI là hành động có chủ ý của người nói.', '[{"japanese":"日本で生活しているうちに、日本語が上手になりました。","hiragana":"にほんでせいかつしているうちに、にほんごがじょうずになりました。","vietnamese":"Sống ở Nhật một thời gian thì tiếng Nhật đã giỏi lên lúc nào không hay."},{"japanese":"何度も練習しているうちに、自転車に乗れるようになりました。","hiragana":"なんどもれんしゅうしているうちに、じてんしゃにのれるようになりました。","vietnamese":"Trong lúc luyện tập nhiều lần thì tôi đã biết đi xe đạp."},{"japanese":"友達と話しているうちに、悩みが消えてしまいました。","hiragana":"ともだちとはなしているうちに、なやみがきえてしまいました。","vietnamese":"Trong lúc nói chuyện với bạn thì những muộn phiền đã biến mất."},{"japanese":"本を読んでいるうちに、だんだん眠くなりました。","hiragana":"ほんをよんでいるうちに、だんだんねむくなりました。","vietnamese":"Trong lúc đang đọc sách thì tôi dần thấy buồn ngủ."},{"japanese":"その音楽を聞いているうちに、昔のことを思い出しました。","hiragana":"そのおんがくをきいているうちに、むかしのことをおもいだしました。","vietnamese":"Trong khi đang nghe bản nhạc đó thì tôi nhớ lại chuyện ngày xưa."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-AIDA', 'SHINKANZEN_N3', 'L01', 'N3', '～間（ずっと）', 'Vている + 間 / N + の + 間', 'Trong suốt (khoảng thời gian) ...', 'Dùng khi muốn nói: "Trong suốt khoảng thời gian A diễn ra, thì trạng thái/hành động B cũng liên tục diễn ra theo".', 'Nếu vế B là một hành động xảy ra chớp nhoáng (không kéo dài) thì phải dùng ～間に, không được dùng ～間.', '[{"japanese":"夏休みの間、ずっとアルバイトをしていました。","hiragana":"なつやすみのあいだ、ずっとアルバイトをしていました。","vietnamese":"Trong suốt kỳ nghỉ hè, tôi liên tục làm thêm."},{"japanese":"日本にいる間、ずっと日本語を勉強していました。","hiragana":"にほんにいるあいだ、ずっとにほんごをべんきょうしていました。","vietnamese":"Trong suốt thời gian ở Nhật, tôi đã liên tục học tiếng Nhật."},{"japanese":"授業の間、ずっと静かにしていました。","hiragana":"じゅぎょうのあいだ、ずっとしずかにしていました。","vietnamese":"Trong suốt buổi học, tôi đã luôn giữ im lặng."},{"japanese":"旅行の間、ずっと写真を撮っていました。","hiragana":"りょこうのあいだ、ずっとしゃしんをとっていました。","vietnamese":"Trong suốt chuyến du lịch, tôi đã liên tục chụp ảnh."},{"japanese":"映画を見ている間、ずっと彼と手をつないでいました。","hiragana":"えいがをみているあいだ、ずっとかれとてをつないでいました。","vietnamese":"Trong suốt lúc xem phim, tôi đã luôn nắm tay anh ấy."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-AIDANI', 'SHINKANZEN_N3', 'L01', 'N3', '～間に（瞬間）', 'Vている + 間に / N + の + 間に', 'Trong lúc (một khoảnh khắc nào đó) ...', 'Dùng khi muốn nói: "Trong khoảng thời gian A đang diễn ra, thì hành động B chen ngang hoặc hoàn thành".', 'Chú ý phân biệt với ～間. (間: A kéo dài, B cũng kéo dài. 間に: A kéo dài, B chỉ là một điểm).', '[{"japanese":"私が寝ている間に、電話がありました。","hiragana":"わたしがねているあいだに、でんわがありました。","vietnamese":"Trong lúc tôi đang ngủ thì có điện thoại."},{"japanese":"日本にいる間に、富士山を見たいです。","hiragana":"にほんにいるあいだに、ふじさんをみたいです。","vietnamese":"Trong khoảng thời gian ở Nhật, tôi muốn được nhìn thấy núi Phú Sĩ."},{"japanese":"母が料理している間に、宿題をしました。","hiragana":"ははがりょうりしているあいだに、しゅくだいをしました。","vietnamese":"Trong lúc mẹ đang nấu ăn, tôi đã làm bài tập."},{"japanese":"夏休みの間に、京都へ行きました。","hiragana":"なつやすみのあいだに、きょうとへいきました。","vietnamese":"Trong khoảng thời gian nghỉ hè, tôi đã đi Kyoto."},{"japanese":"独身の間に、いろいろなことに挑戦したいです。","hiragana":"どくしんのあいだに、いろいろなことにちょうせんしたいです。","vietnamese":"Trong lúc còn độc thân, tôi muốn thử thách nhiều điều."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-TEKARA-DENAITO', 'SHINKANZEN_N3', 'L01', 'N3', '～てからでないと / ～てからでなければ', 'Vて + からでないと', 'Nếu chưa ... thì không thể ...', 'Dùng khi muốn nhấn mạnh thứ tự trước sau: "Hành động A bắt buộc phải được thực hiện trước, nếu không có A thì B không thể xảy ra hoặc không được phép xảy ra".', 'Thường dùng trong các quy định, cảnh báo, hoặc điều kiện tiên quyết.', '[{"japanese":"切符を買ってからでないと、電車に乗れません。","hiragana":"きっぷをかってからでないと、でんしゃにのれません。","vietnamese":"Nếu chưa mua vé thì không thể lên tàu."},{"japanese":"予約してからでないと、ホテルに泊まれません。","hiragana":"よやくしてからでないと、ホテルにとまれません。","vietnamese":"Nếu chưa đặt trước thì không thể ở khách sạn."},{"japanese":"申し込んでからでないと、参加できません。","hiragana":"もうしこんでからでないと、さんかできません。","vietnamese":"Nếu chưa đăng ký thì không thể tham gia."},{"japanese":"宿題をしてからでないと、ゲームをしてはいけません。","hiragana":"しゅくだいをしてからでないと、ゲームをしてはいけません。","vietnamese":"Nếu chưa làm xong bài tập thì không được chơi game."},{"japanese":"お金を払ってからでないと、商品を受け取れません。","hiragana":"おかねをはらってからでないと、しょうひんをうけとれません。","vietnamese":"Nếu chưa trả tiền thì không thể nhận hàng."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-TOKORO', 'SHINKANZEN_N3', 'L01', 'N3', '～ところだ', 'Vる + ところ / Vている + ところ / Vた + ところ', 'Đúng lúc sắp / đang / vừa mới ...', 'Nhấn mạnh một thời điểm cụ thể của hành động. Tùy thuộc vào thì của động từ đi trước mà ý nghĩa khác nhau: Vるところ (chuẩn bị làm), Vているところ (đang làm dở), Vたところ (vừa mới làm xong).', 'Có thể đi kèm trợ từ (ところへ、ところで、ところを) tùy thuộc vào động từ ở vế sau.', '[{"japanese":"これからご飯を食べるところです。","hiragana":"これからごはんをたべるところです。","vietnamese":"Bây giờ chuẩn bị ăn cơm."},{"japanese":"今から出かけるところです。","hiragana":"いまからでかけるところです。","vietnamese":"Bây giờ tôi chuẩn bị đi ra ngoài."},{"japanese":"これから勉強するところです。","hiragana":"これからべんきょうするところです。","vietnamese":"Bây giờ chuẩn bị bắt đầu học."},{"japanese":"今からお風呂に入るところです。","hiragana":"いまからおふろにはいるところです。","vietnamese":"Bây giờ chuẩn bị đi tắm."},{"japanese":"これから映画が始まるところです。","hiragana":"これからえいががはじまるところです。","vietnamese":"Bây giờ bộ phim chuẩn bị bắt đầu."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3_L02_G001', 'SHINKANZEN_N3', 'L02', 'N3', '～とおりだ・～とおり（に）／～どおりだ・～どおり（に）', 'Vる・Vた + とおりに / N + の + とおりに / N + どおりに', 'Theo đúng như / Y như ...', 'Sử dụng khi muốn nói hành động ở vế sau được thực hiện giống hệt, tuân theo đúng nội dung, quy định, dự đoán hay chỉ dẫn ở vế trước.', 'Đây là cấu trúc thường gặp khi mô tả việc làm theo bản vẽ, sách hướng dẫn, hoặc việc xảy ra đúng như dự đoán.', '[{"japanese":"先輩に教えてもらったとおりに、パソコンを設定しました。","hiragana":"せんぱいにおしえてもらったとおりに、パソコンをせっていしました。","vietnamese":"Tôi đã cài đặt máy tính theo đúng như tiền bối đã chỉ dạy."},{"japanese":"説明書に書いてあるとおりに、組み立ててください。","hiragana":"せつめいしょにかいてあるとおりに、くみたててください。","vietnamese":"Xin hãy lắp ráp theo đúng như được viết trong sách hướng dẫn."},{"japanese":"今から私が言うとおりに、書いてください。","hiragana":"いまからわたしがいうとおりに、かいてください。","vietnamese":"Bây giờ xin hãy viết theo đúng như những gì tôi nói."},{"japanese":"予想したとおり、今日の試合は私たちのチームが勝ちました。","hiragana":"よそうしたとおり、きょうのしあいはわたしたちのチームがかちました。","vietnamese":"Đúng như dự đoán, trận đấu hôm nay đội của chúng tôi đã thắng."},{"japanese":"予定どおりに、会議は３時に終わりました。","hiragana":"よていどおりに、かいぎは３じにおわりました。","vietnamese":"Theo đúng kế hoạch, cuộc họp đã kết thúc lúc 3 giờ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3_L02_G002', 'SHINKANZEN_N3', 'L02', 'N3', '～によって・～によっては', 'N + によって / N + によっては', 'Tùy vào / Tùy theo ... mà khác nhau', 'Diễn tả ý nghĩa: tùy thuộc vào từng người, từng nơi, từng thời điểm hay từng trường hợp (A) mà kết quả, cách thức hoặc sự việc (B) sẽ khác nhau hoặc thay đổi theo.', 'Trong bài này chỉ tập trung vào ý nghĩa "Tùy theo sự khác biệt", không trộn với các nghĩa khác của によって như "Bởi ai đó" (câu bị động) hay "Do/Vì" (nguyên nhân).', '[{"japanese":"国によって、文化や習慣が違います。","hiragana":"くにによって、ぶんかやしゅうかんがちがいます。","vietnamese":"Tùy vào mỗi quốc gia mà văn hóa và phong tục sẽ khác nhau."},{"japanese":"人によって、考え方が異なります。","hiragana":"ひとによって、かんがえかたがことなります。","vietnamese":"Tùy vào mỗi người mà cách suy nghĩ sẽ khác biệt."},{"japanese":"季節によって、見える景色が変わります。","hiragana":"きせつによって、みえるけしきがかわります。","vietnamese":"Tùy vào mùa mà phong cảnh có thể nhìn thấy sẽ thay đổi."},{"japanese":"時代によって、流行する服が変わります。","hiragana":"じだいによって、りゅうこうするふくがかわります。","vietnamese":"Tùy vào từng thời đại mà quần áo thịnh hành sẽ thay đổi."},{"japanese":"天気によっては、明日のイベントは中止になるかもしれません。","hiragana":"てんきによっては、あしたのイベントはちゅうしになるかもしれません。","vietnamese":"Tùy thuộc vào thời tiết mà sự kiện ngày mai có thể bị hủy (đôi khi xảy ra)."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3_L02_G003', 'SHINKANZEN_N3', 'L02', 'N3', '～たびに', 'Vる + たびに / N + の + たびに', 'Mỗi khi / Cứ mỗi lần ...', 'Dùng khi muốn nói: "Cứ mỗi lần hành động A xảy ra, thì chắc chắn hành động/sự việc B cũng sẽ xảy ra theo". Nhấn mạnh tính lặp đi lặp lại một cách thường xuyên.', 'Thường đi kèm với những từ thể hiện cảm xúc, nhận xét, hoặc một hành động đặc trưng.', '[{"japanese":"この写真を見るたびに、学生時代を思い出します。","hiragana":"このしゃしんをみるたびに、がくせいじだいをおもいだします。","vietnamese":"Mỗi khi nhìn bức ảnh này, tôi lại nhớ về thời sinh viên."},{"japanese":"父は出張のたびに、お土産を買ってきてくれます。","hiragana":"ちちはしゅっちょうのたびに、おおみやげをかってきてくれます。","vietnamese":"Bố tôi cứ mỗi lần đi công tác lại mua quà lưu niệm về cho tôi."},{"japanese":"彼女は会うたびに、きれいになっていきます。","hiragana":"かのじょはあうたびに、きれいになっていきます。","vietnamese":"Cô ấy cứ mỗi lần gặp lại trở nên xinh đẹp hơn."},{"japanese":"辞書を引くたびに、新しい漢字を覚えます。","hiragana":"じしょをひくたびに、あたらしいかんじをおぼえます。","vietnamese":"Mỗi lần tra từ điển, tôi lại nhớ thêm được chữ Kanji mới."},{"japanese":"日本へ行くたびに、新しい友達ができます。","hiragana":"にほんへいくたびに、あたらしいともだちができます。","vietnamese":"Mỗi lần đi Nhật, tôi lại có thêm bạn mới."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3_L02_G004', 'SHINKANZEN_N3', 'L02', 'N3', '（～ば）～ほど・（～なら）～ほど・～ほど', 'Vば + Vる + ほど / Aければ + Aい + ほど / Naなら + Naな + ほど / N + ほど', 'Càng ... càng ...', 'Diễn tả ý nghĩa: Nếu mức độ của A tăng lên thì mức độ của B cũng tăng lên (hoặc giảm đi) tương ứng.', 'Chủ ngữ của cả 2 vế thường giống nhau. Động từ và tính từ phải được lặp lại.', '[{"japanese":"外国語は、勉強すればするほど難しくなります。","hiragana":"がいこくごは、べんきょうすればするほどむずかしくなります。","vietnamese":"Ngoại ngữ thì càng học càng trở nên khó."},{"japanese":"荷物は軽ければ軽いほど、旅行に便利です。","hiragana":"にもつはかるければかるいほど、りょこうにべんりです。","vietnamese":"Hành lý càng nhẹ thì càng tiện lợi cho chuyến du lịch."},{"japanese":"この本は、読めば読むほど面白くなります。","hiragana":"このほんは、よめばよむほどおもしろくなります。","vietnamese":"Quyển sách này càng đọc thì càng thấy thú vị."},{"japanese":"アパートは駅から近ければ近いほど、家賃が高くなります。","hiragana":"アパートはえきからちかければちかいほど、やちんがたかくなります。","vietnamese":"Căn hộ càng gần nhà ga thì tiền thuê nhà càng cao."},{"japanese":"パソコンの操作は、使えば使うほど慣れてきます。","hiragana":"パソコンのそうさは、つかえばつかうほどなれてきます。","vietnamese":"Thao tác máy tính thì càng dùng nhiều sẽ càng quen."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3_L02_G005', 'SHINKANZEN_N3', 'L02', 'N3', '～ついでに', 'Vる・Vた + ついでに / N + の + ついでに', 'Nhân tiện / Tiện thể ...', 'Dùng khi muốn nói: "Nhân cơ hội đang làm việc chính (A), thì tranh thủ làm luôn việc phụ (B)".', 'Không dùng cho những sự việc tự nhiên xảy ra ngoài ý muốn.', '[{"japanese":"銀行へ行くついでに、郵便局にも寄りました。","hiragana":"ぎんこうへいくついでに、ゆうびんきょくにもよりました。","vietnamese":"Nhân tiện đi ngân hàng, tôi đã ghé qua cả bưu điện."},{"japanese":"スーパーへ買い物のついでに、本屋へ行きました。","hiragana":"スーパーへかいもののついでに、ほんやへいきました。","vietnamese":"Nhân tiện đi siêu thị mua sắm, tôi đã đến hiệu sách."},{"japanese":"散歩のついでに、コンビニでパンを買ってきました。","hiragana":"さんぽのついでに、コンビニでパンをかってきました。","vietnamese":"Nhân tiện đi dạo, tôi đã mua bánh mì ở cửa hàng tiện lợi."},{"japanese":"仕事で東京へ行ったついでに、友達に会いました。","hiragana":"しごとでとうきょうへいったついでに、ともだちにあいました。","vietnamese":"Nhân tiện đi Tokyo công tác, tôi đã gặp bạn bè."},{"japanese":"部屋の掃除をするついでに、窓も拭きました。","hiragana":"へやのそうじをするついでに、まどもふきました。","vietnamese":"Nhân tiện dọn dẹp phòng, tôi đã lau luôn cả cửa sổ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L03-BAKARINI', 'SHINKANZEN_N3', 'L03', 'N3', '～ばかりに (Chỉ vì... mà ra nông nỗi)', 'V(thường) + ばかりに', 'Chỉ vì... mà lại (dẫn tới hậu quả đáng tiếc)', 'Nhấn mạnh một lý do tưởng nhỏ hoặc đáng tiếc duy nhất khiến sự việc trở nên tồi tệ.', 'Vế sau luôn mang ý nghĩa tiêu cực, hối tiếc.', '[{"japanese":"うっかり寝坊したばかりに、大切な飛行機に乗り遅れた。","hiragana":"うっかりねぼうしたばかりに、たいせつなひこうきにのりおくれた。","vietnamese":"Chỉ vì lỡ ngủ quên mà trễ mất chuyến bay quan trọng."},{"japanese":"確認しなかったばかりに、大きなミスをしてしまった。","hiragana":"かくにんしなかったばかりに、おおきなミスをしてしまった。","vietnamese":"Chỉ vì không kiểm tra kỹ mà mắc phải sai lầm lớn."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L03-KOTO-KARA', 'SHINKANZEN_N3', 'L03', 'N3', '～ことから (Từ việc... mà dẫn đến tên gọi/kết luận)', 'V(thường) + ことから', 'Từ việc / Xuất phát từ chuyện...', 'Giải thích nguồn gốc tên gọi, biệt danh hoặc lý do dẫn đến một nhận định chung.', 'Thường đi với các động từ ở vế sau như 「呼ばれる・名付けられる・分かる」.', '[{"japanese":"毎日挨拶を欠かさないことから、彼はみんなに信頼されている。","hiragana":"まいにちあいさつをかかさないことから、かれはみんなにしんらいされている。","vietnamese":"Từ việc ngày nào cũng chào hỏi, cậu ấy được mọi người tin tưởng."},{"japanese":"道が濡れていることから、夜中に雨が降ったことが分かる。","hiragana":"みちがぬれていることから、よなかにあめがふったことがわかる。","vietnamese":"Từ việc đường bị ướt có thể biết đêm qua trời đã mưa."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L03-DAKE-ATTE', 'SHINKANZEN_N3', 'L03', 'N3', '～だけに / ～だけあって (Chính vì... nên quả nhiên)', 'Thể thường + だけに / Thể thường + だけあって', 'Đúng là... có khác / Chính vì... nên càng...', 'Nhấn mạnh kết quả xảy ra hoàn toàn xứng đáng hoặc tương ứng với nguyên nhân phía trước.', '「だけに」 dùng được cho cả khen lẫn chê; 「だけあって」 dùng nhiều để khen ngợi.', '[{"japanese":"長年練習しただけあって、日本語がとても自然です。","hiragana":"ながねんれんしゅうしただけあって、にほんごがとてもしぜんです。","vietnamese":"Đúng là luyện tập nhiều năm có khác, tiếng Nhật thật tự nhiên."},{"japanese":"期待が大きかっただけに、負けたときは悔しかった。","hiragana":"きたいがおおきかっただけに、まけたときはくやしかった。","vietnamese":"Chính vì kỳ vọng lớn nên lúc thua càng thấy tiếc."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L04-TO-SHITARA', 'SHINKANZEN_N3', 'L04', 'N3', '～としたら / ～とすれば (Nếu giả sử là...)', 'Thể thường + としたら', 'Giả sử như... thì sao / Nếu cho là...', 'Đặt ra một giả thuyết chưa có thật để suy luận kết quả hoặc nêu ý kiến.', 'Hay đi kèm 「もし / 仮に」 ở đầu câu.', '[{"japanese":"今から電車に乗るとしたら、三時には着くでしょう。","hiragana":"いまからでんしゃにのるとしたら、さんじにはつくでしょう。","vietnamese":"Nếu bây giờ lên tàu điện thì khoảng 3 giờ sẽ tới nơi nhỉ."},{"japanese":"一億円当たったとすれば、まず家を買います。","hiragana":"いちおくえんあたったとすれば、まずいえをかいます。","vietnamese":"Giả sử trúng 100 triệu yên, trước tiên tôi sẽ mua nhà."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L04-SAE-BA', 'SHINKANZEN_N3', 'L04', 'N3', '～さえ ～ば (Chỉ cần... là đủ)', 'N + さえ + Vえば', 'Miễn là có... / Chỉ cần... thì...', 'Đưa ra một điều kiện tối thiểu duy nhất: chỉ cần thỏa điều kiện đó thì mọi chuyện đều ổn.', 'Mang sắc thái nhấn mạnh điều kiện duy nhất.', '[{"japanese":"毎日三十分勉強さえすれば、きっと合格できます。","hiragana":"まいにちさんじゅっぷんべんきょうさえすれば、きっとごうかくできます。","vietnamese":"Chỉ cần mỗi ngày học 30 phút thì chắc chắn đỗ được."},{"japanese":"スマホさえあれば、道に迷うことはありません。","hiragana":"スマホさえあれば、みちにまようことはありません。","vietnamese":"Chỉ cần có điện thoại thông minh là không lo lạc đường."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L04-NAI-KOTONIWA', 'SHINKANZEN_N3', 'L04', 'N3', '～ないことには ～ない (Nếu không... thì không thể...)', 'Vない + ことには', 'Hễ mà chưa / nếu không làm A thì B cũng chịu', 'Khẳng định A là điều kiện tiên quyết bắt buộc; nếu chưa làm A thì kết quả B không thể xảy ra.', 'Vế sau luôn mang tính phủ định hoặc khó thực hiện.', '[{"japanese":"まず始めてみないことには、できるかどうか分かりません。","hiragana":"まずはじめてみないことには、できるかどうかわかりません。","vietnamese":"Nếu chưa thử bắt đầu thì chẳng biết có làm được hay không."},{"japanese":"本人の話を聞かないことには、判断できません。","hiragana":"ほんにんのはなしをきかないことには、はんだんできません。","vietnamese":"Nếu không nghe chính chủ nói thì tôi không phán đoán được."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L05-KUSE-NI', 'SHINKANZEN_N3', 'L05', 'N3', '～くせに (Vậy mà / Thế mà lại... — phê phán)', 'Thể thường + くせに', 'Mang tiếng là / Biết rõ thế vậy mà lại...', 'Diễn tả thái độ chê trách, bực mình trước sự mâu thuẫn của đối phương.', 'KHÔNG dùng cho chính bản thân mình; không dùng với câu kính trọng.', '[{"japanese":"知っているくせに、知らないふりをしている。","hiragana":"しっているくせに、しらないふりをしている。","vietnamese":"Rõ ràng là biết mà cứ giả vờ không biết."},{"japanese":"もうすぐテストのくせに、ちっとも勉強しない。","hiragana":"もうすぐテストのくせに、ちっともべんきょうしない。","vietnamese":"Sắp thi đến nơi rồi vậy mà chẳng học chút nào."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L05-NIMOKAKAWARAZU', 'SHINKANZEN_N3', 'L05', 'N3', '～にもかかわらず (Bất chấp / Mặc dù...)', 'N/V(thường) + にもかかわらず', 'Mặc dù / Bất chấp (trang trọng)', 'Nêu kết quả trái hẳn với điều kiện thông thường; hay dùng trong tin tức, bài phát biểu.', 'Trang trọng hơn 「のに」 và dùng được sau Danh từ trực tiếp (không có な/の).', '[{"japanese":"何度も注意したにもかかわらず、また同じミスをした。","hiragana":"なんどもちゅういしたにもかかわらず、またおなじミスをした。","vietnamese":"Dù đã nhắc nhở bao lần vậy mà lại mắc cùng lỗi cũ."},{"japanese":"忙しいにもかかわらず、わざわざ来ていただきありがとうございます。","hiragana":"いそがしいにもかかわらず、わざわざきていただきありがとうございます。","vietnamese":"Dù anh bận rộn nhưng vẫn cất công tới, xin cảm ơn."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L05-TO-ITTEMO', 'SHINKANZEN_N3', 'L05', 'N3', '～といっても (Nói là... nhưng thực ra...)', 'N/V + といっても', 'Nói là vậy thôi chứ thực chất mức độ không như người nghe tưởng', 'Đính chính hoặc làm rõ giới hạn thực tế so với ấn tượng ban đầu của từ vừa nói.', 'Ví dụ: Nói là biết nấu ăn nhưng chỉ làm được món trứng rán thôi.', '[{"japanese":"北海道は涼しいといっても、昼間は少し暑いです。","hiragana":"ほっかいどうはすずしいといっても、ひるまはすこしあついです。","vietnamese":"Nói Hokkaido mát thôi chứ ban trưa vẫn hơi nóng đấy."},{"japanese":"一人暮らしといっても、実家のすぐ近くです。","hiragana":"ひとりぐらしといっても、じっかのすぐちかくです。","vietnamese":"Nói là sống một mình thôi chứ ở ngay sát nhà bố mẹ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L06-GACHI', 'SHINKANZEN_N3', 'L06', 'N3', 'Vます / N + がちだ (Hay có xu hướng xấu)', 'Vます + がち / N + がち', 'Thường hay bị / Có khuynh hướng thiên về (thường tiêu cực)', 'Chỉ thói quen hoặc hiện tượng không tốt dễ lặp đi lặp lại.', 'VD: 休みがち (hay nghỉ), 忘れがち (hay quên), 病気がち (hay ốm vặt).', '[{"japanese":"最近は忙しくて、連絡を忘れがちです。","hiragana":"さいきんはいそがしくて、れんらくをわすれがちです。","vietnamese":"Gần đây bận quá nên tôi rất hay quên liên lạc."},{"japanese":"一人暮らしだと野菜が不足しがちになる。","hiragana":"ひとりぐらしだとやさいがふそくしがちになる。","vietnamese":"Sống một mình thường hay bị thiếu hụt rau củ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L06-GIMI', 'SHINKANZEN_N3', 'L06', 'N3', 'Vます / N + ぎみ (Có hơi hướng / Hơi có dấu hiệu)', 'Vます/N + ぎみ', 'Hơi có vẻ / Cảm thấy hơi bị... (trạng thái cơ thể, tình hình)', 'Diễn tả dấu hiệu nhẹ của một trạng thái đang xuất hiện (hơi cảm, hơi mệt, hơi muộn).', 'Khác với 「がち」 (tần suất nhiều lần), 「ぎみ」 nói trạng thái hiện tại.', '[{"japanese":"最近少し太りぎみなので、運動を始めました。","hiragana":"さいきんすこしふとりぎみなので、うんどうをはじめました。","vietnamese":"Gần đây hơi tăng cân chút nên tôi bắt đầu tập thể dục."},{"japanese":"電車は五分ほど遅れぎみに走っています。","hiragana":"でんしゃはごふんほどおくれぎみにはしっています。","vietnamese":"Tàu điện đang chạy hơi trễ khoảng 5 phút."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L06-KAKERU', 'SHINKANZEN_N3', 'L06', 'N3', 'Vます + かける (Đang làm dở / Sắp sửa)', 'Vます + かける / Vます + かけの + N', 'Làm dở dang giữa chừng / Sắp sửa', 'Chỉ hành động bắt đầu làm nhưng dừng giữa chừng, hoặc sắp sửa xảy ra ngay tức khắc.', 'VD: 読みかけの本 (cuốn sách đang đọc dở), 消えかける (sắp tắt lịm).', '[{"japanese":"何か言いかけたのに、急に黙ってしまった。","hiragana":"なにかいいかけたのに、きゅうにだまってしまった。","vietnamese":"Định nói điều gì đó dở lời vậy mà lại im bặt."},{"japanese":"沈みかけた太陽がとても綺麗でした。","hiragana":"しずみかけたたいようがとてもきれいでした。","vietnamese":"Mặt trời lúc sắp lặn trông đẹp tuyệt vời."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L07-PPANASHI', 'SHINKANZEN_N3', 'L07', 'N3', 'Vます + っぱなし (Cứ để nguyên vậy chẳng dọn)', 'Vます + っぱなし', 'Làm xong rồi để mặc nguyên trạng như vậy (trách móc / lơ đễnh)', 'Chê trách việc làm gì đó rồi bỏ mặc không xử lý bước tiếp theo (bật đèn quên tắt, mở cửa quên đóng).', 'Dùng với động từ hành động một lần rồi kéo dài hậu quả.', '[{"japanese":"窓を開けっぱなしにすると虫が入ってきますよ。","hiragana":"まどをあけっぱなしにするとむしがはいってきますよ。","vietnamese":"Cứ mở toang cửa sổ để nguyên thế thì côn trùng bay vào đấy."},{"japanese":"電車の中で二時間も立ちっぱなしで足が痛い。","hiragana":"でんしゃのなかでにじかんもたちっぱなしであしがいたい。","vietnamese":"Đứng suốt 2 tiếng trên tàu không nghỉ làm chân đau quá."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L07-KIRI', 'SHINKANZEN_N3', 'L07', 'N3', 'Vた + きり / N + きり (Kể từ đó tới nay không... nữa)', 'Vた + きり / N + きり', 'Kể từ sau lần đó là thôi biệt tăm / Chỉ có ngần ấy', 'Nghĩa 1: Vた + きり chỉ từ lúc sự việc ấy xảy ra xong không thấy tiếp diễn nữa. Nghĩa 2: 二人きり (chỉ có hai người).', 'Văn nói cũng dùng 「～っきり」.', '[{"japanese":"息子は部屋に入ったきり、外に出てこない。","hiragana":"むすこはへやにはいったきり、そとにでてこない。","vietnamese":"Con trai vào phòng xong là ở lì trong đó chẳng ra ngoài."},{"japanese":"二人きりでゆっくり話したいことがあります。","hiragana":"ふたりきりでゆっくりはなしたいことがあります。","vietnamese":"Tôi có chuyện muốn nói riêng chỉ hai người với nhau."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L07-DARAKE', 'SHINKANZEN_N3', 'L07', 'N3', 'N + だらけ (Toàn là / Đầy rẫy — nghĩa tiêu cực)', 'N + だらけ', 'Đầy dẫy, toàn là (những thứ lộn xộn / bẩn / sai)', 'Diễn tả bề mặt hoặc nội dung bị phủ kín bởi thứ không mong muốn (bùn đất, lỗi sai, vết xước).', 'Khác với 「ばかり」 hoặc 「いっぱい」 không mang nghĩa tiêu cực thuần như 「だらけ」.', '[{"japanese":"雨の日にサッカーをして靴が泥だらけになった。","hiragana":"あめのひにサッカーをしてくつがどろだらけになった。","vietnamese":"Đá bóng ngày mưa nên giày dính đầy bùn đất."},{"japanese":"机の上が古い書類だらけで片付かない。","hiragana":"つくえのうえがふるいしょるいだらけでかたづかない。","vietnamese":"Trên bàn toàn giấy tờ cũ lộn xộn không dọn nổi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L08-NI-TOTTE', 'SHINKANZEN_N3', 'L08', 'N3', 'N + にとって (Đối với — xét trên lập trường của N)', 'N + にとって', 'Đối với ai đó mà nói (đánh giá giá trị/tầm quan trọng)', 'Đưa ra nhận xét, đánh giá đứng từ góc nhìn của một cá nhân hay tập thể.', 'Phân biệt với 「に対して」 (hành động/thái độ hướng vào đối tượng).', '[{"japanese":"私にとって、家族の笑顔が一番大切です。","hiragana":"わたしにとって、かぞくのえがおがいちばんたいせつです。","vietnamese":"Đối với tôi, nụ cười của gia đình là quan trọng nhất."},{"japanese":"この漢字辞典は初心者にとってとても使いやすい。","hiragana":"このかんじじてんはしょしんしゃにとってとてもつかいやすい。","vietnamese":"Cuốn từ điển Kanji này rất dễ dùng đối với người mới học."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L08-TE-TAMARANAI', 'SHINKANZEN_N3', 'L08', 'N3', '～てたまらない / ～てしかたがない', 'Aくて/Vて + たまらない', 'Rất... không thể chịu nổi (cảm xúc mãnh liệt)', 'Diễn tả cảm giác cơ thể hoặc tâm lý dâng trào tự nhiên đến mức không kìm nén được.', 'Thường đi với từ chỉ cảm xúc/sinh lý: 嬉しい, 眠い, 寂しい, 会いたい.', '[{"japanese":"夏休みで国へ帰れるので、嬉しくてたまらない。","hiragana":"なつやすみでくにへかえるので、うれしくてたまらない。","vietnamese":"Nghỉ hè được về nước nên tôi vui sướng vô cùng."},{"japanese":"夜遅くまで起きていたので、眠くてしかたがない。","hiragana":"よるおそくまでおきていたので、ねむくてしかたがない。","vietnamese":"Thức khuya quá nên giờ buồn ngủ không chịu nổi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L08-WAKE-GA-NAI', 'SHINKANZEN_N3', 'L08', 'N3', '～わけがない / ～わけにはいかない', 'Vる + わけがない / Vる + わけにはいかない', 'Làm gì có chuyện... / Không thể làm được vì ràng buộc đạo lý', '「わけがない」: phủ định tuyệt đối theo logic. 「わけにはいかない」: dù muốn cũng không thể vì lý do xã hội/trách nhiệm.', 'Cặp ngữ pháp hay xuất hiện cùng nhau trong đề thi N3.', '[{"japanese":"練習もせずに上手になるわけがない。","hiragana":"れんしゅうもせずにじょうずになるわけがない。","vietnamese":"Không luyện tập mà đòi giỏi lên thì làm gì có chuyện đó."},{"japanese":"みんなが頑張っているので、私だけ休むわけにはいきません。","hiragana":"みんなががんばっているので、わたしだけやすむわけにはいきません。","vietnamese":"Mọi người đều đang cố gắng nên mình tôi nghỉ sao được."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W01-TOTAN', 'SOUMATOME_N3', 'W01', 'N3', 'Vた + とたん(に) (Ngay khoảnh khắc vừa mới... thì bất ngờ)', 'Vた + とたんに', 'Ngay vừa lúc... thì bỗng nhiên (điều bất ngờ xảy ra)', 'Hai sự việc nối tiếp nhau ngay trong tích tắc; vế sau mang tính bất ngờ ngoài dự đoán.', 'Vế sau KHÔNG dùng câu ý chí/mệnh lệnh.', '[{"japanese":"窓を開けたとたん、強い風が入ってきた。","hiragana":"まどをあけたとたん、つよいかぜがはいってきた。","vietnamese":"Vừa mở cửa sổ ra thì gió mạnh thổi ùa vào."},{"japanese":"電車を降りたとたんに、雨が降り出した。","hiragana":"でんしゃをおりたとたんに、あめがふりだした。","vietnamese":"Ngay lúc vừa bước xuống tàu thì trời đổ mưa."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W01-SAICHUU', 'SOUMATOME_N3', 'W01', 'N3', 'Vている / Nの + 最中に (Đúng ngay giữa lúc đang...)', 'Vている/Nの + 最中に', 'Đúng ngay lúc đang làm gì thì có chuyện xen vào', 'Nhấn mạnh hành động đang diễn ra ở cao trào nhất thì sự việc khác bất ngờ cắt ngang.', 'N là danh từ mang tính sự kiện (会議・授業・食事).', '[{"japanese":"試験を受けている最中に、急に停電になった。","hiragana":"しけんをうけているさいちゅうに、きゅうにていでんになった。","vietnamese":"Đúng lúc đang làm bài thi thì bỗng nhiên mất điện."},{"japanese":"大事な話をしている最中に、邪魔をしないでほしい。","hiragana":"だいじなはなしをしているさいちゅうに、じゃまをしないでほしい。","vietnamese":"Đúng lúc đang nói chuyện quan trọng đừng làm phiền nhé."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W02-NI-TAISHITE', 'SOUMATOME_N3', 'W02', 'N3', 'N + に対して (Đối với / Trái ngược với)', 'N + に対して', 'Hướng thái độ/hành động tới đối tượng N / Trong khi ngược lại...', 'Nghĩa 1: Thái độ, ứng xử đối với ai đó. Nghĩa 2: So sánh tương phản giữa hai đối tượng.', 'Phân biệt với 「にとって」 (đánh giá từ góc nhìn của N).', '[{"japanese":"客に対して失礼な態度をとってはいけません。","hiragana":"きゃくにたいしてしつれいなたいどをとってはいけません。","vietnamese":"Không được có thái độ thất lễ đối với khách hàng."},{"japanese":"兄が活発なのに対して、弟は静かだ。","hiragana":"あにがかっぱつなのに対して、おとうとはしずかだ。","vietnamese":"Trái với anh trai năng động, em trai rất trầm tính."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W02-WO-MEGUTTE', 'SOUMATOME_N3', 'W02', 'N3', 'N + をめぐって (Xoay quanh vấn đề tranh luận)', 'N + をめぐって', 'Xoay quanh chủ đề / tranh cãi về vấn đề N', 'Nhiều người cùng tranh luận, bàn bạc hoặc cạnh tranh xoay quanh một chủ đề trọng tâm.', 'Vế sau thường là 議論する・話し合う・対立する.', '[{"japanese":"環境問題をめぐって、各国の代表が話し合っている。","hiragana":"かんきょうもんだいをめぐって、かっこくのだいひょうがはなしあっている。","vietnamese":"Đại biểu các nước đang bàn bạc xoay quanh vấn đề môi trường."},{"japanese":"計画の方針をめぐって意見が対立した。","hiragana":"けいかくのほうしんをめぐっていけんがたいりつした。","vietnamese":"Ý kiến đối lập nhau xoay quanh phương châm kế hoạch."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W03-WO-HAJIME', 'SOUMATOME_N3', 'W03', 'N3', 'N + をはじめ(として) (Trước hết phải kể đến / Tiêu biểu là...)', 'N + をはじめ', 'Tiêu biểu như N, và còn nhiều thứ khác tương tự', 'Nêu ra một đại diện tiêu biểu nhất trước khi liệt kê phạm vi rộng hơn.', 'Trang trọng, hay gặp trong tin tức và giới thiệu văn hóa.', '[{"japanese":"東京をはじめ、日本の大都市はどこも交通が便利だ。","hiragana":"とうきょうをはじめ、にほんのだいとしはどこもこうつうがべんりだ。","vietnamese":"Các thành phố lớn ở Nhật tiêu biểu là Tokyo nơi nào giao thông cũng tiện."},{"japanese":"部長をはじめ、社員全員がその計画に賛成した。","hiragana":"ぶちょうをはじめ、しゃいんぜんいんがそのけいかくにさんせいした。","vietnamese":"Từ trưởng phòng cho tới toàn thể nhân viên đều đồng ý kế hoạch."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W03-TOWA-KAGIRANAI', 'SOUMATOME_N3', 'W03', 'N3', '～とは限らない (Chưa chắc đã... / Không hẳn lúc nào cũng...)', 'Thể thường + とは限らない', 'Chưa chắc đã / Không nhất thiết lúc nào cũng đúng như vậy', 'Phủ định nhẹ một nhận định chung có tính tuyệt đối, thường đi với 「いつも・必ずしも・みんな」.', 'Hay thi ở phần Ngữ pháp N3 & Đọc hiểu!', '[{"japanese":"有名な店だからといって、いつも美味しいとは限らない。","hiragana":"ゆうめいなみせだからといって、いつもおいしいとはかぎらない。","vietnamese":"Không phải cứ là quán nổi tiếng thì lúc nào cũng ngon."},{"japanese":"日本人がみんな漢字を全部書けるとは限りません。","hiragana":"にほんじんがみんなかんじをぜんぶかけるとはかぎりません。","vietnamese":"Không hẳn mọi người Nhật đều viết được hết tất cả Kanji."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W04-WO-MOTONI', 'SOUMATOME_N3', 'W04', 'N3', 'N + をもとに(して) (Dựa trên cơ sở, chất liệu gốc là N)', 'N + をもとに', 'Dựa trên / Lấy cảm hứng từ nguyên bản N để sáng tạo ra...', 'Lấy dữ liệu, câu chuyện thật, tiểu thuyết làm nền tảng để viết phim, báo cáo hoặc tạo tác phẩm mới.', 'Thường dùng trong sản xuất phim ảnh, nghiên cứu, viết báo cáo.', '[{"japanese":"アンケートの結果をもとに、新しい商品を開発します。","hiragana":"アンケートのけっかをもとに、あたらしいしょうひんをかいはつします。","vietnamese":"Phát triển sản phẩm mới dựa trên kết quả khảo sát."},{"japanese":"昔の有名な小説をもとにアニメが制作された。","hiragana":"むかしのゆうめいなしょうせつをもとにアニメがせいさくされた。","vietnamese":"Bộ Anime được sản xuất dựa trên cuốn tiểu thuyết nổi tiếng xưa."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W04-WO-TSUUJITE', 'SOUMATOME_N3', 'W04', 'N3', 'N + を通じて / を通して (Thông qua N / Suốt khoảng thời gian N)', 'N + を通じて / N + を通して', 'Thông qua cầu nối N / Xuyên suốt cả giai đoạn N', 'Nghĩa 1: qua trung gian người/phương tiện. Nghĩa 2: diễn ra đều đặn suốt một năm/bốn mùa.', '「一年を通じて暖かい」 = ấm áp suốt cả năm.', '[{"japanese":"この地域は一年を通して気候が温暖で住みやすい。","hiragana":"このちいきはいちねんをとおしてきこうがおんだんですみやすい。","vietnamese":"Khu vực này khí hậu ôn hòa dễ sống suốt cả năm."},{"japanese":"友人を通じて、今の仕事を紹介してもらいました。","hiragana":"ゆうじんをつうじて、いまのしごとをしょうかいしてもらいました。","vietnamese":"Thông qua bạn bè tôi được giới thiệu công việc hiện tại."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W05-NI-CHIGAINAI', 'SOUMATOME_N3', 'W05', 'N3', '～に違いない (Chắc chắn không sai được)', 'Thể thường + に違いない', 'Chắc chắn là... (suy đoán đầy tin tưởng của người nói)', 'Người nói tin chắc gần như 90% dựa trên trực giác hoặc bằng chứng bản thân nắm rõ.', 'Khác 「はずだ」 (dựa trên quy luật khách quan), 「に違いない」 mang chủ quan mạnh hơn.', '[{"japanese":"こんな時間に連絡が来るなんて、何かあったに違いない。","hiragana":"こんなじかんにれんらくがくるなんて、なにかあったにちがいない。","vietnamese":"Giờ này mà có người gọi chắc chắn là có chuyện gì rồi."},{"japanese":"彼の日本語の発音なら、面接も合格するに違いありません。","hiragana":"かれのにほんごのはつおんなら、めんせつもごうかくするにちがいありません。","vietnamese":"Với phát âm tiếng Nhật của cậu ấy thì chắc chắn sẽ đỗ phỏng vấn."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W05-OSORE-GA-ARU', 'SOUMATOME_N3', 'W05', 'N3', 'Vる / Nの + 恐れがある (E rằng có nguy cơ...)', 'Vる/Nの + 恐れがある', 'Có nguy cơ / E rằng sẽ xảy ra sự việc xấu', 'Thường dùng trong dự báo thiên tai, y tế, tin tức cảnh báo rủi ro có thể xảy ra.', 'LUÔN dùng với kết quả tiêu cực hoặc nguy hiểm.', '[{"japanese":"このまま雨が降り続けば、川があふれる恐れがある。","hiragana":"このままあめがふりつづけば、かわがあふれるおそれがある。","vietnamese":"Nếu trời cứ mưa tiếp thế này thì có nguy cơ sông bị tràn bờ."},{"japanese":"操作を間違えるとデータが消える恐れがあります。","hiragana":"そうさをまちがえるとデータがきえるおそれがあります。","vietnamese":"Nếu thao tác nhầm thì có nguy cơ dữ liệu sẽ bị mất."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W06-KOTO-NI-NATTEIRU', 'SOUMATOME_N3', 'W06', 'N3', 'Vる / Vない + ことになっている', 'Vる/Vない + ことになっている', 'Theo quy định / Theo lịch trình đã định thì...', 'Diễn tả nội quy, quy tắc, truyền thống hoặc lịch trình đã được tập thể/tổ chức ấn định sẵn.', 'Phân biệt với 「ことにしている」 (thói quen tự bản thân đặt ra).', '[{"japanese":"来月から新しいプロジェクトが始まることになっています。","hiragana":"らいげつからあたらしいプロジェクトがはじまることになっています。","vietnamese":"Theo kế hoạch thì tháng sau dự án mới sẽ bắt đầu."},{"japanese":"このアパートではペットを飼ってはいけないことになっている。","hiragana":"このアパートではペットをかってはいけないことになっている。","vietnamese":"Theo quy định chung cư này thì không được nuôi thú cưng."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SMT-W06-ZARU-WO-ENAI', 'SOUMATOME_N3', 'W06', 'N3', 'Vない + ざるを得ない (Đành phải / Không còn cách nào khác)', 'Vない(gốc) + ざるを得ない', 'Đành phải làm (dù không muốn nhưng buộc phải làm)', 'Tình thế bắt buộc khiến bản thân dù không thích vẫn phải chấp nhận làm.', 'Lưu ý bất quy tắc 「する」 biến thành 「せざるを得ない」.', '[{"japanese":"他に人がいないので、私が引き受けざるを得なかった。","hiragana":"ほかにひとがいないので、わたしがひきうけざるをえなかった。","vietnamese":"Vì chẳng còn ai khác nên tôi đành phải nhận lấy việc đó."},{"japanese":"これほど証拠がそろっていては、事実を認めざるを得ない。","hiragana":"これほどしょうこがそろっていては、じじつをみとめざるをえない。","vietnamese":"Bằng chứng đầy đủ thế này rồi thì đành phải thừa nhận sự thật."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-MN3-MN3-01-TE-ITADAKEMASHOU', 'MINNA_N3', 'MN3-01', 'N3', '～ていただけませんか / ～てもらえませんか', 'Vて + いただけないでしょうか', 'Xin vui lòng giúp tôi... được không ạ?', 'Cách nhờ vả lịch sự trong công sở và giao tiếp với người Nhật.', '「～ていただけないでしょうか」 còn lịch sự và mềm hơn nữa.', '[{"japanese":"お忙しいところ恐縮ですが、サインをしていただけませんか。","hiragana":"おいそがしいところきょうしゅくですが、サインをしていただけませんか。","vietnamese":"Biết anh bận nhưng anh ký xác nhận giúp tôi được không ạ?"},{"japanese":"もう一回ゆっくり説明していただけないでしょうか。","hiragana":"もういっかいゆっくりせつめいしていただけないでしょうか。","vietnamese":"Anh giải thích lại chậm hơn một lần nữa được không ạ?"}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-MN3-MN3-01-MONODA', 'MINNA_N3', 'MN3-01', 'N3', 'Vる + ものだ / Vた + ものだ', 'Vる + ものだ / Vた + ものだ', 'Vốn dĩ là đương nhiên / Hồi xưa thường hay...', 'Vる+ものだ diễn tả chân lý hiển nhiên hoặc đạo lý chung; Vた+ものだ gợi nhớ kỷ niệm xa xưa thường hay làm gì.', 'Ngữ khí sâu lắng, chiêm nghiệm.', '[{"japanese":"時間はあっという間に過ぎるものですね。","hiragana":"じかんはあっというまにすぎるものですね。","vietnamese":"Thời gian trôi nhanh như chớp mắt ấy nhỉ."},{"japanese":"若いときはよく友達と夜遅くまで語り合ったものだ。","hiragana":"わかいときはよくともだちとよるおそくまでかたりあったものだ。","vietnamese":"Thời trẻ tôi thường trò chuyện cùng bạn tới tận khuya."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-MN3-MN3-02-TONOKOTO', 'MINNA_N3', 'MN3-02', 'N3', '～とのことだ (Nghe báo lại rằng / Theo tin nhắn thì...)', 'Thể thường + とのことです', 'Nghe nói là / Được thông báo là... (trích dẫn gián tiếp lịch sự)', 'Truyền đạt lại lời nhắn qua điện thoại, email, thông báo từ người khác một cách trang trọng.', 'Dùng rất nhiều trong môi trường công sở Nhật Bản khi nghe điện thoại chuyển lời.', '[{"japanese":"受付の方によると、今日の会議は一時間遅れるとのことです。","hiragana":"うけつけのかたによると、きょうのかいぎはいちじかんおくれるとのことです。","vietnamese":"Theo nhân viên lễ tân báo lại thì cuộc họp hôm nay trễ 1 tiếng."},{"japanese":"メールが届いて、明日の予定が変更になったとのことだ。","hiragana":"メールがとどいて、あしたのよていがへんこうになったとのことだ。","vietnamese":"Email gửi tới báo rằng lịch trình ngày mai đã thay đổi."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-MN3-MN3-02-TO-IWARETEIRU', 'MINNA_N3', 'MN3-02', 'N3', '～と 言われている (Được người ta nói rằng / Tương truyền rằng)', 'Thể thường + と言われている', 'Được cho là / Người ta vẫn nói là...', 'Đưa ra nhận định chung phổ biến trong xã hội hoặc kiến thức khoa học được công nhận rộng rãi.', 'Thường xuất hiện trong các đoạn văn giải thích khoa học và văn hóa.', '[{"japanese":"日本は四季がはっきりしている国だと言われています。","hiragana":"にほんはしきがはっきりしているくにだといわれています。","vietnamese":"Nhật Bản được nói là đất nước có bốn mùa rõ rệt."},{"japanese":"十分な睡眠をとると記憶力が上がると言われている。","hiragana":"じゅうぶんなすいみんをとるときおくりょくがあがるといわれている。","vietnamese":"Người ta nói ngủ đủ giấc sẽ giúp tăng trí nhớ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-MN3-MN3-03-KOTONI-SURU', 'MINNA_N3', 'MN3-03', 'N3', 'Vる / Vない + ことにしている (Đặt làm thói quen cá nhân)', 'Vる/Vない + ことにしている', 'Tôi luôn giữ thói quen làm / không làm...', 'Chỉ quy tắc cá nhân tự đặt ra và duy trì đều đặn trong sinh hoạt.', 'Phân biệt rõ với 「ことになっている」 (quy định chung).', '[{"japanese":"健康のために、エレベーターを使わず階段を使うことにしています。","hiragana":"けんこうのために、エレベーターをつかわずかいだんをつかうことにしています。","vietnamese":"Vì sức khỏe tôi giữ thói quen đi cầu thang bộ thay thang máy."},{"japanese":"太りたくないので、夜九時以降は何も食べないことにしている。","hiragana":"ふとりたくないので、よるくじいこうはなにもたべないことにしている。","vietnamese":"Không muốn tăng cân nên tôi tự đặt ra thói quen không ăn gì sau 9h tối."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-MN3-MN3-03-NAKA-DE-KAKE', 'MINNA_N3', 'MN3-03', 'N3', '～おかげで・～せいで (Mở rộng trung cấp)', 'V/A(thường)/Nの + わりに', 'Tuy... vậy mà lại (so với tiêu chuẩn chung)', '「わりに」 so sánh mức độ thực tế tốt hơn hoặc bất ngờ hơn so với vẻ ngoài/giá cả/tuổi tác.', 'VD: Giá rẻ mà ngon (安いわりにおいしい).', '[{"japanese":"彼はまだ来日して半年なわりに、日本語がとても上手だ。","hiragana":"かれはまだらいにちしてはんとしなわりに、にほんごがとてもじょうずだ。","vietnamese":"Cậu ấy mới tới Nhật nửa năm mà tiếng Nhật đã giỏi đến bất ngờ."},{"japanese":"よく食べたわりに、体重がまったく増えていない。","hiragana":"よくたべたわりに、たいじゅうがまったくふえていない。","vietnamese":"Tuy ăn khá nhiều nhưng cân nặng hoàn toàn không tăng."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
