insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-read-short-2_mnn5-rs2-q1', 'reading-short', 'N5', 'reading', 'さとうさんは どこで リンさんを 待ちますか。', 'Tin nhắn rủ đi ăn tối (Bài 6–13)', '["タイ料理の 店の中","駅の 南口","駅の 北口","リンさんの うち"]'::jsonb, 1, 'Câu cuối ghi rõ: 「６時半に 南口で 待っています。」 (Đợi ở cửa Nam lúc 6:30).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
