insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-s-n4-2_q1', 'reading-short', 'N4', 'reading', '鈴木さんは まず 何を しますか。', 'Tin nhắn nhờ photo tài liệu', '["駅の 近くの 銀行へ 行く。","会議の 資料を 10ぶ コピーする。","1時ごろ 会議室へ 行く。","メールの へんじを 待つ。"]'::jsonb, 1, 'Người nhắn nhờ Suzuki photo sẵn 10 bộ tài liệu họp chiều.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-s-n4-3_q1', 'reading-short', 'N4', 'reading', 'この 薬は いつ 飲みますか。', 'Cách uống thuốc cảm', '["食事の 前に","食事の あと 30分いないに","寝る 前に 1回だけ","おなかが すいている ときに"]'::jsonb, 1, 'Hướng dẫn ghi rõ 毎食後30分いないに (trong vòng 30 phút sau mỗi bữa ăn).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-s-n4-4_q1', 'reading-short', 'N4', 'reading', '電車を おりるとき、何に 気をつけますか。', 'Cảnh báo quên đồ trên tàu', '["いそいで すぐ おりること。","わすれものがないか 確認すること。","傘を 電車に おいて おくこと。","大きい 荷物を 持たないこと。"]'::jsonb, 1, 'Thông báo khuyên kiểm tra lại hành lý (自分の荷物をもう一度確かめる) tránh để quên.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-s-n3-1_q1', 'reading-short', 'N3', 'reading', '筆者が 心配して いる ことは 何ですか。', 'Thói quen đọc sách trên tàu điện', '["通勤時間が 長すぎる こと。","スマホの 値段が 高い こと。","長い 文章を 深く 考える 力が 弱くなる こと。","新聞を 買う 人が 増えた こと。"]'::jsonb, 2, 'Tác giả nhắc tới việc nếu chỉ đọc bài ngắn thì 長い文章をじっくり考える力が落ちていく.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-s-n3-2_q1', 'reading-short', 'N3', 'reading', '明日の 午前2時に 急いで 連絡したい ときは どう しますか。', 'Thông báo bảo trì hệ thống nội bộ', '["社内メールを 送る。","携帯電話で 連絡する。","午前4時まで 待つ。","会社の 受付へ 行く。"]'::jsonb, 1, 'Trong khung giờ bảo trì (1h-4h sáng), trường hợp khẩn cấp dùng điện thoại di động (携帯電話をご利用ください).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-s-n3-3_q1', 'reading-short', 'N3', 'reading', '筆者の 考えに 合って いるのは どれですか。', 'Ý nghĩa thực sự của thất bại', '["失敗しない 人のほうが 成功する。","失敗は いやなものだから、挑戦しない ほうがいい。","失敗から 学んで 次に 生かす ことで 成長できる。","成長には 運だけが 必要だ。"]'::jsonb, 2, 'Ý chính: học nguyên nhân từ thất bại để vận dụng cho lần sau giúp trưởng thành lớn hơn.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n5-s1_real-read-n5-s1-q1', 'reading-short', 'N5', 'reading', '土曜日に図書館は何時に閉まりますか。', 'Thông báo giờ mở cửa Thư viện Trường', '["午後５時です。","夜８時です。","朝９時です。","休みです。"]'::jsonb, 0, 'Trong bài viết rõ: 「土曜日は午後５時に閉まります」(Thứ Bảy đóng cửa lúc 5 giờ chiều).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n5-s2_real-read-n5-s2-q1', 'reading-short', 'N5', 'reading', 'リンさんはあした何を持ってきますか。', 'Tin nhắn rủ đi công viên ngắm hoa', '["飲み物","お弁当","カメラ","お菓子"]'::jsonb, 0, 'Câu cuối ghi: 「リンさんは飲み物を持ってきてください」(Linh hãy mang đồ uống tới).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n4-s1_real-read-n4-s1-q1', 'reading-short', 'N4', 'reading', 'ペットボトルはいつ出さなければなりませんか。', 'Thông báo đổi ngày thu gom rác tái chế', '["１６日（木）の朝８時半まで","１５日（水）の朝８時半まで","１６日（木）の夕方まで","来週の水曜日まで"]'::jsonb, 0, 'Thông báo ghi đổi sang ngày 16 (Thứ 5) và để ra trước 8:30 sáng.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n4-s2_real-read-n4-s2-q1', 'reading-short', 'N4', 'reading', 'この人は店長に何をお願いしていますか。', 'Tin nhắn xin đổi ca làm thêm ở quán cà phê', '["金曜日に休んで、かわりに土曜日の午後に入りたいこと。","土曜日も金曜日も両方休みたいこと。","大学の試験の日にちを変えてほしいこと。","今月でアルバイトを辞めたいこと。"]'::jsonb, 0, 'Người viết xin nghỉ thứ Sáu vì thi đại học và đề xuất làm bù vào chiều thứ Bảy.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n3-s1_real-read-n3-s1-q1', 'reading-short', 'N3', 'reading', 'このメールを送った一番の目的は何ですか。', 'Email công việc đề nghị đổi lịch họp với đối tác', '["来週火曜日の打ち合わせの日時を変更してもらうこと。","来週の出張に佐藤さんも参加してもらうこと。","打ち合わせを完全に中止にすること。","金曜日の午後に会議室を予約してもらうこと。"]'::jsonb, 0, 'Người gửi nêu lý do công tác đột xuất và xin đổi lịch họp thứ Ba sang chiều thứ Năm hoặc sáng thứ Sáu.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n3-s2_real-read-n3-s2-q1', 'reading-short', 'N3', 'reading', 'このお知らせの内容と合っているものはどれですか。', 'Thông báo kiểm tra bảo trì thang máy tòa nhà', '["点検が正午より早く終われば、その時点でエレベーターが使えるようになる。","８月２０日は一日中エレベーターが使えない。","作業中は非常階段も利用できない。","点検は午後の２時間で行われる。"]'::jsonb, 0, 'Câu cuối dùng ngữ pháp N3 「〜次第」: 「点検が早く終わり次第、運転を再開いたします」(Ngay khi kiểm tra xong sớm sẽ vận hành lại ngay).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-read-med-1_mnn5-rm1-q1', 'reading-medium', 'N5', 'reading', 'ランさんは 何で 学校へ 行きますか。', 'Một ngày ở Nhật Bản của du học sinh Lan (Bài 1–20)', '["電車","バス","自転車","歩いて"]'::jsonb, 2, 'Đoạn 2: 「自転車で 学校へ 行きます。」 (Đi học bằng xe đạp).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-read-med-1_mnn5-rm1-q2', 'reading-medium', 'N5', 'reading', 'コンビニの 人は ランさんに 何を して くれますか。', 'Một ngày ở Nhật Bản của du học sinh Lan (Bài 1–20)', '["朝ごはんを 作って くれます","わからない 言葉を 教えて くれます","自転車を 貸して くれます","大学の テストを 手伝って くれます"]'::jsonb, 1, 'Đoạn 3: 「わからない 言葉を いつも 教えて くれます。」 (Luôn chỉ giúp những từ không hiểu).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-read-med-2_mnn5-rm2-q1', 'reading-medium', 'N5', 'reading', 'どうして お父さんは コートを 買って くれましたか。', 'Kế hoạch du lịch mùa xuân & món quà của bố (Bài 21–25)', '["誕生日だった から","北海道が とても 寒い から","友達に あげる から","コートが 安かった から"]'::jsonb, 1, 'Đoạn 2: 「北海道は とても 寒いでしょう。だから 先週、父が 暖かい コートを 買って くれました。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-read-med-2_mnn5-rm2-q2', 'reading-medium', 'N5', 'reading', 'この 人が 北海道で したい ことは 何ですか。', 'Kế hoạch du lịch mùa xuân & món quà của bố (Bài 21–25)', '["日本語を 勉強する こと","コートを 売る こと","ラーメンを 食べたり 温泉に 入ったり する こと","アルバイトを する こと"]'::jsonb, 2, 'Đoạn 3: 「おいしい ラーメンを 食べたり、温泉に 入ったり したいです。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n5-1_jlpt-rm-n5-1-q1', 'reading-medium', 'N5', 'reading', '家族は どうやって デパートへ 行きましたか。', 'Cuối tuần đi mua sắm cùng gia đình', '["バスで 行きました。","電車で 行きました。","歩いて 行きました。","車で 行きました。"]'::jsonb, 2, 'Lúc đi gia đình chọn đi bộ vì thời tiết đẹp (バスではなく、歩いて行きました). Lúc về mới đi tàu điện.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n5-1_jlpt-rm-n5-1-q2', 'reading-medium', 'N5', 'reading', 'どうして 電車で 家へ 帰りましたか。', 'Cuối tuần đi mua sắm cùng gia đình', '["天気が わるくなったからです。","買い物を して 荷物が 重かったからです。","午後 4時に なって 急いでいたからです。","バスが なかったからです。"]'::jsonb, 1, 'Sau khi mua áo, bánh kẹo và hoa quả, hành lý nặng (荷物が重かった) nên cả nhà đi tàu về.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n4-1_jlpt-rm-n4-1-q1', 'reading-medium', 'N4', 'reading', '筆者は どうして 紙の本を 読むようになりましたか。', 'Thói quen đọc sách trên tàu điện', '["スマートフォンの料金が高くなったから。","スマホを見ていると目が疲れやすくなったから。","電車の中でゲームが禁止されたから。","小説のほうがニュースより速く読めるから。"]'::jsonb, 1, 'Tác giả nêu rõ lý do: 「目が疲れやすくなりました。そこで、先月から小さめの小説を持ち歩くようにしました。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n4-1_jlpt-rm-n4-1-q2', 'reading-medium', 'N4', 'reading', '筆者が選んでいる本は どんな本ですか。', 'Thói quen đọc sách trên tàu điện', '["写真がたくさん入った大きい本","片手で持てるサイズの小さい小説","仕事に関係する専門書","毎朝駅で配られるニュースの本"]'::jsonb, 1, '「小さめの小説」 và 「片手で持てるサイズなので、立っているときでも楽に読めます。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n3-1_jlpt-rm-n3-1-q1', 'reading-medium', 'N3', 'reading', 'テレワークの課題として挙げられているのはどれですか。', 'Làm việc từ xa và ranh giới nghỉ ngơi', '["通勤時間が長くなってストレスが増えること。","自分のペースで仕事をすることがまったくできないこと。","仕事と休みの時間の境界が曖昧になりやすいこと。","会社のパソコンが自宅で使えないこと。"]'::jsonb, 2, 'Vấn đề được nêu ở đoạn 2 là khó phân biệt công việc và đời tư (仕事とプライベートの区別がつきにくい).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n3-1_jlpt-rm-n3-1-q2', 'reading-medium', 'N3', 'reading', '筆者はテレワークをうまく続けるために何が必要だと述べていますか。', 'Làm việc từ xa và ranh giới nghỉ ngơi', '["毎日必ず会社に一度顔を出すこと","場所や時間を意識的に分けて気分を切り替えること","夜遅くまで働いて昼間に長く寝ること","パソコンを使わずに紙だけで仕事すること"]'::jsonb, 1, 'Đoạn cuối đề xuất tách nơi làm/nghỉ hoặc đi dạo theo giờ để chủ động phân tách công việc và nghỉ ngơi.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-m-n4-1_q1', 'reading-medium', 'N4', 'reading', '筆者は さとうさんの 家に 何日間 いましたか。', 'Bức thư cảm ơn sau chuyến Homestay', '["2日間","3日間","1週間","1か月"]'::jsonb, 1, 'Câu đầu tiên viết: 先週は 3日間 お世話になり.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-m-n4-1_q2', 'reading-medium', 'N4', 'reading', '筆者が お父さんに して もらった ことは 何ですか。', 'Bức thư cảm ơn sau chuyến Homestay', '["カレーを 作ってもらった。","温泉へ 連れていってもらった。","ベトナムへ 送ってもらった。","日本語を 教えてもらった。"]'::jsonb, 1, 'Câu thứ 2 đoạn 2: お父さんに連れていってもらった温泉もすばらしかったです.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-m-n3-1_q1', 'reading-medium', 'N3', 'reading', '手で 書く ことの よい点は 何だと 書かれていますか。', 'Vì sao việc ghi chép bằng tay lại hiệu quả?', '["スピードが パソコンより 速い 点。","頭で 整理しながら 書くため、記憶に 残りやすい 点。","あとから データを コピーしやすい 点。","手が まったく 疲れない 点。"]'::jsonb, 1, 'Đoạn 2 nói viết tay phải tóm tắt trong đầu nên dễ đọng lại ký ức hơn.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-m-n3-1_q2', 'reading-medium', 'N3', 'reading', '筆者が すすめているのは どんな やり方ですか。', 'Vì sao việc ghi chép bằng tay lại hiệu quả?', '["パソコンを いっさい 使わない こと。","タブレットだけで テスト勉強する こと。","目的に 合わせて 使い分ける こと。","ノートを まったく 取らない こと。"]'::jsonb, 2, 'Câu cuối bài: 目的によって使い分けるのが賢いやり方だろう.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n5-m1_real-read-n5-m1-q1', 'reading-medium', 'N5', 'reading', 'この人はどうしてどこへも行きませんでしたか。', 'Một ngày cuối tuần ở nhà của Minh', '["天気がよくなかったからです。","宿題がたくさんあったからです。","映画を見たかったからです。","体の調子が悪かったからです。"]'::jsonb, 0, 'Câu thứ 2 nêu rõ nguyên nhân: 「天気がよくなかったので、どこへも行きませんでした」.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n5-m1_real-read-n5-m1-q2', 'reading-medium', 'N5', 'reading', '日本の映画はどうでしたか。', 'Một ngày cuối tuần ở nhà của Minh', '["すこし難しかったですが、おもしろかったです。","とても簡単で、おもしろかったです。","難しくて、つまらなかったです。","長すぎて、最後まで見ませんでした。"]'::jsonb, 0, 'Câu cuối ghi rõ: 「すこし難しかったですが、とてもおもしろかったです」.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n5-m2_real-read-n5-m2-q1', 'reading-medium', 'N5', 'reading', '「さくら」はどんな店ですか。', 'Quán cà phê yêu thích gần nhà ga', '["静かで、コーヒーもケーキもおいしい店です。","駅から遠くて、にぎやかな店です。","日曜日だけ開いている店です。","本を売っている大きい店です。"]'::jsonb, 0, 'Đoạn 2 miêu tả: 「店の中はいつも静かで、コーヒーもケーキもとてもおいしいです」.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n5-m2_real-read-n5-m2-q2', 'reading-medium', 'N5', 'reading', 'わたしは毎週土曜日に「さくら」で何をしますか。', 'Quán cà phê yêu thích gần nhà ga', '["本を読みます。","アルバイトをします。","友達と料理を作ります。","日本語を教えます。"]'::jsonb, 0, 'Câu cuối ghi rõ: 「わたしは毎週土曜日にここで本を読みます」.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n4-m1_real-read-n4-m1-q1', 'reading-medium', 'N4', 'reading', 'どうして小さい袋に入っているお菓子が人気なのですか。', 'Văn hóa tặng quà Omiyage ở công ty Nhật', '["分けやすく、いない人の机にも置いておけるから。","値段が一番安くて、甘いから。","日本の空港でしか買えないから。","長い時間食べなくても悪くならないから。"]'::jsonb, 0, 'Câu cuối giải thích rõ: 「みんなで分けやすく、席にいない人の机にも置いておけるからです」.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n4-m2_real-read-n4-m2-q1', 'reading-medium', 'N4', 'reading', '温泉に入るときのルールとして正しいものはどれですか。', 'Vì sao người Nhật thích đi suối nước nóng Onsen mùa đông', '["入る前に体を洗い、タオルはお湯に入れない。","タオルでお湯をかき混ぜてから入る。","水着を着て入らなければならない。","出たあとで体を洗わなければならない。"]'::jsonb, 0, 'Đoạn 2 nêu rõ 2 quy tắc: tắm sạch trước khi xuống nước và không nhúng khăn vào bồn.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n3-m1_real-read-n3-m1-q1', 'reading-medium', 'N3', 'reading', '筆者がテレワークの課題として挙げていることは何か。', 'Làm việc từ xa (Telework) và ranh giới nghỉ ngơi', '["仕事と私生活の区別がつきにくくなり、夜遅くまで働いてしまいやすいこと。","通勤時間が長くなって家族と話す時間が減ったこと。","自宅のパソコンの性能が会社より低いこと。","同僚とメールで連絡が取れなくなること。"]'::jsonb, 0, 'Sau từ chuyển tiếp 「一方で」, tác giả chỉ rõ vấn đề: 「仕事と私生活の区別がつきにくくなり、つい夜遅くまでパソコンを見てしまう」.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n3-m2_real-read-n3-m2-q1', 'reading-medium', 'N3', 'reading', '「金継ぎ」が世界中で注目されている理由として最も適切なものはどれか。', 'Nghệ thuật Kintsugi (金継ぎ) và vẻ đẹp của sự không hoàn hảo', '["傷を隠さず、新しい美しさとして受け入れる考え方に魅力があるから。","壊れた器を新品と全く見分けがつかないほど綺麗に直せるから。","誰でも数分で安く修理できる簡単な方法だから。","古い器を高く売るための技術だから。"]'::jsonb, 0, 'Câu trọng tâm: 「傷を隠すのではなく、その跡を新しい美しさとして受け入れる考え方が…注目を集めている」.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n3-1_jlpt-rl-n3-1-q1', 'reading-long', 'N3', 'reading', '便利で速い社会になって、どんな問題が起きていると筆者は言っていますか。', 'Giá trị của việc "chờ đợi" trong thời đại tốc độ', '["インターネットの注文で荷物が届かないことが増えた。","少し待つだけでイライラしたり怒ったりする人が増えた。","電車の本数が減って乗り換えに時間がかかるようになった。","手紙を書く人が増えたが返事が遅くなっている。"]'::jsonb, 1, 'Đoạn 2 nêu rõ: vì quá quen tốc độ nên người dễ cáu kỉnh khi phải chờ dù chỉ 3 phút.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n3-1_jlpt-rl-n3-1-q2', 'reading-long', 'N3', 'reading', '筆者が手紙や料理の例を出したのはなぜですか。', 'Giá trị của việc "chờ đợi" trong thời đại tốc độ', '["手紙や料理はできるだけ速く仕上げるべきだと伝えるため。","レストランのサービスが悪い理由を説明するため。","待つ時間にも楽しみや価値があることを示すため。","メールより手紙のほうが仕事で役に立つと言うため。"]'::jsonb, 2, 'Đoạn 3 dùng ví dụ thư tay và món ăn để minh họa vai trò & giá trị của thời gian chờ đợi.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n3-1_jlpt-rl-n3-1-q3', 'reading-long', 'N3', 'reading', '筆者の考えに最も合っているものはどれですか。', 'Giá trị của việc "chờ đợi" trong thời đại tốc độ', '["どんな場面でもスピードよりゆっくりすることが大切だ。","日常の待ち時間はすべて無駄なので減らすべきだ。","緊急時以外は、待つ時間も味わいながら過ごすとよい。","レストランでは料理が出てくるまでスマホを見るべきだ。"]'::jsonb, 2, 'Đoạn kết: trong công việc/khẩn cấp cần tốc độ, nhưng với khoảng chờ nhỏ hằng ngày thì nên thư giãn đón nhận thay vì coi là lãng phí.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n4-1_jlpt-rl-n4-1-q1', 'reading-long', 'N4', 'reading', 'わたしは どうして すぐに りょうりを 始められませんでしたか。', 'Kinh nghiệm học nấu ăn ở câu lạc bộ trường', '["包丁を持っていなかったから。","アルバイトが いそがしかったから。","りょうりクラブが 木曜日にしかなかったから。","せんぱいが こわかったから。"]'::jsonb, 1, 'Đoạn 1: 「でも、アルバイトがいそがしくて、なかなか始めることができませんでした。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n4-1_jlpt-rl-n4-1-q2', 'reading-long', 'N4', 'reading', 'このクラブについて正しいものはどれですか。', 'Kinh nghiệm học nấu ăn ở câu lạc bộ trường', '["毎週日本の伝統りょうりだけを作る。","留学生もいっしょに参加している。","毎週日曜日の朝に集まっている。","今でも家ではまったく作れない。"]'::jsonb, 1, 'Đoạn 2: 「日本人の学生だけでなく、留学生もたくさん参加しています。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n5-1_jlpt-rl-n5-1-q1', 'reading-long', 'N5', 'reading', 'わたしは 平日の 午後、よく 何を していますか。', 'Bức thư gửi thầy giáo cũ', '["アルバイトを しています。","図書館で 宿題をしたり 友達と話したり しています。","浅草へ お寺を 見に 行っています。","日本語の クラスで 授業を 受けています。"]'::jsonb, 1, 'Thư viết: 「午後は図書館で宿題をしたり、友達と話したりしています。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n5-1_jlpt-rl-n5-1-q2', 'reading-long', 'N5', 'reading', '先週の 日曜日は だれと どこへ 行きましたか。', 'Bức thư gửi thầy giáo cũ', '["木村先生と 公園へ 行きました。","クラスの 友達と 浅草へ 行きました。","ひとりで 東京駅へ 行きました。","家族と 図書館へ 行きました。"]'::jsonb, 1, '「同じクラスのベトナム人の友達と浅草へ行きました。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-l-n5-1_q1', 'reading-long', 'N5', 'reading', '筆者は 日曜日の 朝、何を しましたか。', 'Ngày Chủ Nhật của tôi ở Tokyo', '["日本語学校へ 行きました。","洗濯して、家族に 電話しました。","友達と 映画館へ 行きました。","駅前の スーパーで アルバイトをしました。"]'::jsonb, 1, 'Đoạn 2 nói rõ sáng Chủ nhật dậy lúc 8h, giặt đồ rồi gọi điện cho gia đình.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-read-l-n5-1_q2', 'reading-long', 'N5', 'reading', '午後は 誰と 何を しましたか。', 'Ngày Chủ Nhật của tôi ở Tokyo', '["一人で 部屋を そうじしました。","家族と レストランで 食べました。","友達の アリさんと ベトナム料理を 作りました。","学校で テストを 受けました。"]'::jsonb, 2, 'Đoạn 3: 2 giờ chiều Ari đến phòng và hai người cùng nấu món Việt.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n5-l1_real-read-n5-l1-q1', 'reading-long', 'N5', 'reading', 'ナムさんは月曜日から金曜日まで夕方６時まで働いています。会話の勉強をしたいです。どのクラスがいいですか。', 'Tìm kiếm thông tin: Lớp học tiếng Nhật cộng đồng', '["Bクラス","Aクラス","Cクラス","どのクラスも行けません"]'::jsonb, 0, 'Nam làm việc đến 18:00 từ T2–T6 và muốn học hội thoại → Lớp B học Thứ 5 lúc 19:00–20:30 (毎日 の 会話) là phù hợp nhất!', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n5-l1_real-read-n5-l1-q2', 'reading-long', 'N5', 'reading', 'お金がかからないクラスはどれですか。', 'Tìm kiếm thông tin: Lớp học tiếng Nhật cộng đồng', '["Aクラス","Bクラス","Cクラス","全部無料です"]'::jsonb, 0, 'Lớp A ghi rõ 「無料（０円）」(miễn phí).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n5-l2_real-read-n5-l2-q1', 'reading-long', 'N5', 'reading', '２日目に何をしましたか。', 'Chuyến du lịch Kyoto đầu tiên bằng Shinkansen', '["抹茶のアイスクリームを食べて、お土産を買いました。","古いお寺を見て、写真を撮りました。","新幹線に乗って東京へ帰りました。","友達と映画を見ました。"]'::jsonb, 0, 'Câu trong đoạn 2 nêu rõ: 「２日目は抹茶のアイスクリームを食べて、お土産を買いました」.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n5-l2_real-read-n5-l2-q2', 'reading-long', 'N5', 'reading', 'この人はいつまた京都へ行きたいですか。', 'Chuyến du lịch Kyoto đầu tiên bằng Shinkansen', '["秋","夏","冬","来週"]'::jsonb, 0, 'Câu cuối bài: 「また秋に行きたいです」(Muốn đi lại vào mùa thu).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n4-l1_real-read-n4-l1-q1', 'reading-long', 'N4', 'reading', '大学生のマイさんは平日の夜７時にプールで泳ぎたいです。どのコースを申し込んで、いくら払いますか。', 'Tìm kiếm thông tin: So sánh 3 gói thẻ Trung tâm Thể thao', '["フルコース・8,000円","ナイトコース・5,500円","デイコース・4,000円","フルコース・9,000円"]'::jsonb, 0, 'Mai muốn bơi lúc 19:00 tối ngày thường → Gói Night chỉ có Gym (không có hồ bơi) nên phải chọn Full Course (9.000 yên), trừ ưu đãi sinh viên 1.000 yên còn 8.000 yên!', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n4-l2_real-read-n4-l2-q1', 'reading-long', 'N4', 'reading', '散歩を続けてから、どんなよいことがありましたか。', 'Thói quen đi bộ 20 phút mỗi sáng', '["頭がすっきりして、昼間の仕事に集中できるようになった。","体重が半年で１０キロも減った。","近所に新しい友達がたくさんできた。","夜遅くまで起きられるようになった。"]'::jsonb, 0, 'Đoạn 2 nêu rõ: 「頭がすっきりして、昼間の仕事にも集中できるようになりました」.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n3-l1_real-read-n3-l1-q1', 'reading-long', 'N3', 'reading', 'フンさんは土曜日が仕事で、自宅からオンラインで受けられる講座を探しています。開始３週間前に申し込む場合、どれを選んでいくら払いますか。', 'Tìm kiếm thông tin: Khóa học cuối tuần Kỹ năng Số', '["C講座・16,000円","C講座・18,000円","A講座・14,000円","B講座・18,000円"]'::jsonb, 0, 'Hùng bận thứ 7 (loại A), cần học online tại nhà (loại B vì B chỉ học tại lớp) → chọn C (18.000 yên), đăng ký trước 3 tuần (đạt điều kiện trước 2 tuần) nên giảm 2.000 yên còn 16.000 yên.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-read-n3-l2_real-read-n3-l2-q1', 'reading-long', 'N3', 'reading', '筆者が最も言いたいことは何か。', 'Sách giấy và sách điện tử trong thói quen đọc hiện đại', '["紙の本と電子書籍を目的に応じて使い分けることが大切だ。","これからは紙の本をすべて電子書籍に変えるべきだ。","電子書籍は学習に全く向いていないので使うべきではない。","持ち歩きやすい紙の本を新しく開発する必要がある。"]'::jsonb, 0, 'Câu kết luận của tác giả (sau 「〜のではなく」): 「目的に応じて使い分けることが大切だろう」.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-list-1', 'listening', 'N5', 'listening', 'この 店は 何時まで 開いて いますか。', null, '["午後 7時30分","午後 8時","午後 8時30分","午後 10時"]'::jsonb, 2, 'Hôm nay là thứ Bảy (土曜日), nên cửa hàng mở tới 8:30 tối (午後８時半). Chỉ Chủ nhật mới đóng lúc 8:00.', 'すみません、このみせはなんじからなんじまでですか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-list-2', 'listening', 'N5', 'listening', '二人は 何で 公園へ 行きますか。', null, '["バス","電車","自転車","タクシー"]'::jsonb, 1, 'Ban đầu nam đề xuất đi xe buýt, nhưng nữ góp ý Chủ nhật đường đông đi tàu điện nhanh hơn và nam đồng ý: 「じゃあ 電車で 行きましょう。」', 'あしたいっしょにこうえんへいきませんか。バスでいきましょう。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-list-3', 'listening', 'N5', 'listening', '男の人は お姉さんから 何を もらいましたか。', null, '["時計","白いシャツ","ネクタイ","かばん"]'::jsonb, 1, 'Đồng hồ là nhận từ bố (父), còn từ chị gái (姉) là nhận áo sơ mi trắng (白いシャツ).', 'そのとけい、すてきですね。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-list-4', 'listening', 'N5', 'listening', '会議室の かぎは どこに ありますか。', null, '["つくえの 上","つくえの 中","いすの 下","かばんの 中"]'::jsonb, 2, 'Trên bàn không có, sau đó người nam tìm thấy ở dưới ghế: 「いすの 下に ありました！」.', 'すみません、かいぎしつのかぎはどこにありますか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-list-5', 'listening', 'N5', 'listening', '二人は ぜんぶで いくら 払いますか。', null, '["900円","1,200円","1,500円","1,800円"]'::jsonb, 2, '2 phần cà ri (600 × 2 = 1.200 yên) + 1 cà phê (300 yên) = 1.500 yên.', 'カレーライスをふたつと、コーヒーをひとつおねがいします。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-list-6', 'listening', 'N5', 'listening', '学生は これから 何を しますか。', null, '["窓を 閉める","窓を 開ける","エアコンを つける","窓を 開けて エアコンも つける"]'::jsonb, 1, 'Cô giáo từ chối bật điều hòa (「エアコンは けっこうです」), học sinh chỉ cần mở cửa sổ (窓を開ける).', 'ちょっとあついですね。たなかさん、すみませんがまどをあけてください。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-list-7', 'listening', 'N5', 'listening', 'レポートは いつまでに 出さなければ なりませんか。', null, '["今日の 夕方まで","明日まで","金曜日の 朝まで","金曜日の 夕方まで"]'::jsonb, 3, 'Trưởng phòng nói ngày mai chưa cần nộp, nộp trước chiều tối thứ Sáu: 「金曜日の 夕方までに」.', 'ぶちょう、レポートはあしたまでにださなければなりませんか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('mnn5-list-8', 'listening', 'N5', 'listening', '明日 雨が 降ったら、二人は どう しますか。', null, '["海へ 行く","うちで 休む","駅の 近くで 映画を 見る","デパートで 買い物する"]'::jsonb, 2, 'Nếu trời mưa (雨だったら) → xem phim ở gần nhà ga (駅の 近くで 映画を 見ましょう).', 'あした、てんきがよかったらうみへいきましょうね。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n5-1', 'listening', 'N5', 'listening', 'がくせいは あした まず なにを 出さなければなりませんか。', null, '["漢字のプリント","作文（さくぶん）","テストの紙","教科書"]'::jsonb, 0, 'Giáo viên nói rõ: bài tập ngày mai là 漢字のプリント, còn 作文 để sang thứ Hai tuần sau.', 'みなさん、あしたの しゅくだいは かんじの プリントです。さくぶんは 来週の 月曜日で いいですよ。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n5-2', 'listening', 'N5', 'listening', '「お先に 失礼します。」と 言われたら、なんと 答えますか。', null, '["お疲れさまでした。","いらっしゃいませ。","いただきます。","こちらこそ、お願いします。"]'::jsonb, 0, 'Khi ai đó chào về trước (お先に失礼します), câu đáp lịch sự chuẩn tiếng Nhật là 「お疲れさまでした。」', 'きょうは これで おわります。お先に 失礼します。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n4-1', 'listening', 'N4', 'listening', '女の人は どうして その新しいカフェに よく 行きますか。', null, '["コーヒーが とても 安いから","駅に いちばん 近くて にぎやかだから","Wi-Fiがあって 静かで 勉強しやすいから","ケーキが 無料（むりょう）だから"]'::jsonb, 2, 'Bạn nữ phủ nhận chuyện giá rẻ (ねだんは ふつう) và nêu lý do có Wi-Fi và yên tĩnh (静かなんだ) để học bài.', '駅前に 新しいカフェが できたね。あそこ、コーヒーが 安いの？
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n4-2', 'listening', 'N4', 'listening', 'パンの 売り場は どこに ありますか。', null, '["入口のすぐ左側","突き当たりの野菜コーナーを右に曲がった所","野菜コーナーを左に曲がった所","2階のエスカレーターの前"]'::jsonb, 1, 'Nhân viên chỉ dẫn đi thẳng tới cuối đường (突き当たりの野菜コーナー) rồi rẽ phải (右に曲がったところ).', 'すみません、パンの 売り場は どちらですか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n3-1', 'listening', 'N3', 'listening', '男の人は プレゼンの 資料について どう したら いいと 言っていますか。', null, '["数字やグラフの ページを もっと 増やす","細かい データを すべて 削除して 作り直す","1ページの情報量を減らして 読みやすく整理する","文字を さらに 小さくして 1枚に まとめる"]'::jsonb, 2, 'Anh đồng nghiệp khuyên dữ liệu đã đủ (十分そろっている), cần giảm lượng thông tin mỗi trang cho thoáng (情報量を減らしてすっきりさせる).', '来週のプレゼン資料、数字やグラフを もっと 増やした ほうが いいでしょうか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n3-2', 'listening', 'N3', 'listening', '部長に 何と 言いますか。', null, '["はい、すぐに取りに戻ってまいります。","いいえ、机の上に置いたままにしてください。","はい、部長が取りに行ってくださいますか。","すみません、そのまま会議を始めますか。"]'::jsonb, 0, '「取りに戻ってまいります」 sử dụng khiêm nhường ngữ (まいります) phù hợp khi báo với cấp trên là mình sẽ lập tức quay lại lấy.', 'すみません、部長。会議で 使う 資料を 机の上に 置いてきて しまいました。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-lis-n5-1', 'listening', 'N5', 'listening', '二人は 何時に 会いますか。', null, '["6時","6時半","7時","5時半"]'::jsonb, 1, 'Cuối hội thoại chốt thời gian gặp là 6時半 (6 giờ rưỡi).', '今晩 いっしょに ご飯を 食べませんか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-lis-n5-2', 'listening', 'N5', 'listening', 'りんご 1つと みかん 2つは 全部で いくらですか。', null, '["250円","300円","350円","400円"]'::jsonb, 2, '150 + 100 × 2 = 350 yên.', 'すみません、この りんごは いくらですか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-lis-n4-1', 'listening', 'N4', 'listening', '学生は 明日 まず 何を 持っていかなければ なりませんか。', null, '["カメラと お弁当","ノートと ペン","カメラと ノート","お弁当と ペン"]'::jsonb, 1, 'Cần mang theo ノートとペン (sổ và bút); không mang camera và không cần mang cơm trưa.', '明日は 9時に 学校の 正門の前に 集まります。カメラは 使えませんが、メモするための ノートと ペンは 必ず 持ってください。お昼ご飯は 工場で 用意してくれます。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-lis-n4-2', 'listening', 'N4', 'listening', '女の人は どうして その コートの 色を 選びましたか。', null, '["赤より 緑のほうが 安かったから","赤は サイズが 小さすぎて 合わなかったから","店員に 緑を おすすめされたから","最初から 緑だけが 欲しかったから"]'::jsonb, 1, 'Lý do chọn màu xanh vì chiếc màu đỏ size nhỏ quá không vừa (サイズが小さすぎて合わなかった).', 'きれいな 緑の コートですね。赤も 似合いそうだと 思いますが。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-lis-n4-3', 'listening', 'N4', 'listening', '相手の 言葉に どう 答えますか。', null, '["いいえ、まだまだです。","はい、わたしが いちばん 上手です。","すみません、書いて ください。","ええ、日本人が きらいです。"]'::jsonb, 0, 'Văn hóa khiêm tốn đáp lại lời khen ở Nhật dùng 「いいえ、まだまだです」.', 'わあ、漢字を 書くのが 本当に 上手ですね。日本人の ようですよ。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-lis-n4-4', 'listening', 'N4', 'listening', 'お客さんは 何日の 何時に 予約しましたか。', null, '["土曜日 夜6時","土曜日 夜7時","土曜日 夜8時","日曜日 夜8時"]'::jsonb, 2, 'Cuối cùng chốt đặt lúc 8 giờ tối thứ Bảy (土曜日 夜8時).', 'すみません、今週の 土曜日の 夜7時に 4人で 予約したいんですが。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-lis-n3-1', 'listening', 'N3', 'listening', '男の学生は これから まず 何を しますか。', null, '["すぐ 申込書に 名前を 書く","教室へ 学生証を 取りに 戻る","新しい 写真を 撮りに行く","本を 先に 借りて 帰る"]'::jsonb, 1, 'Nhân viên bảo đi lấy thẻ sinh viên trước (先に取ってきてもらえますか), đơn đăng ký điền sau cũng được.', 'すみません、図書館の 利用カードを 作りたいのですが。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-lis-n3-2', 'listening', 'N3', 'listening', '女の人は どうして 新しい アパートを Bに 決めましたか。', null, '["Aより 家賃が 半額くらい 安かったから","Bは 駅から 歩いて 1分以内だったから","Bは 静かで 日当たりが とても 良かったから","Aは もう 他の人に 予約されて いたから"]'::jsonb, 2, 'Cô gái chọn phòng B vì yên tĩnh và đón nắng rất tốt (静かで日当たりが最高だったから).', '引っ越しの 部屋、Aと Bの どちらに 決めたんですか。Aのほうが 駅に 近かったよね。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-lis-n3-3', 'listening', 'N3', 'listening', '課長が 一番 伝えたい ことは 何ですか。', null, '["連休中も 毎日 出勤して 仕事を 進める こと","休みに入る 前に 今週中に 大事な 仕事を 済ませて おく こと","旅行の 予定を すぐに キャンセルする こと","連休明けに 取引先へ 初めて 連絡する こと"]'::jsonb, 1, 'Trưởng phòng nhắn nhủ trong tuần này trước khi nghỉ lễ hãy hoàn thành gọn việc liên lạc đối tác và nộp hồ sơ.', '来週から いよいよ ゴールデンウィークですね。みなさんも 旅行などの 予定を 立てて いると 思います。ただ、連休前の 仕事が 残ったまま 休みに 入ると 大変ですので、今週中に 取引先への 連絡と 書類の 提出だけは きっちり 終わらせて おきましょう。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-pack-lis-n3-4', 'listening', 'N3', 'listening', 'なんと 返事しますか。', null, '["あ、すみません。これから すぐ 拝見します。","いいえ、さっき 私が 送りましたよ。","はい、とても おいしく いただきました。","すみませんが、もう 一度 質問して ください。"]'::jsonb, 0, 'Dùng khiêm nhường ngữ 「拝見します」 ("Xin lỗi, tôi sẽ xem ngay bây giờ ạ").', 'さっき メールで 送った 企画書の データ、もう 確認して いただけましたか。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n5-1', 'listening', 'N5', 'listening', '女の人は何を飲みますか。', null, '["冷たいお茶","熱いコーヒー","オレンジジュース","冷たい水"]'::jsonb, 0, 'Chú ý từ khóa đổi ý kinh điển trong đề nghe JLPT 「やっぱり」(thôi thì / suy nghĩ lại thì) → đáp án cuối là trà lạnh (冷たいお茶).', 'お飲み物は何になさいますか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n5-2', 'listening', 'N5', 'listening', '二人は何時に会いますか。', null, '["２時","２時半","３時","１時半"]'::jsonb, 0, 'Nam đề xuất 2:30 nhưng Nữ đề nghị 2:00 để kịp mua vé và Nam chốt 「じゃあ、２時に」.', '映画は３時からですね。２時半に駅で会いましょうか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n5-3', 'listening', 'N5', 'listening', '女の人はどうして昨日学校を休みましたか。', null, '["歯が痛かったから","かぜをひいたから","アルバイトがあったから","寝坊したから"]'::jsonb, 0, 'Bạn nữ phủ định bị cảm (いいえ) và nói rõ 「歯がとても痛くて」(vì rất đau răng).', 'きのう学校に来ませんでしたね。かぜですか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n5-4', 'listening', 'N5', 'listening', '男の人は母の日に何をあげますか。', null, '["ハンカチ","お花","かばん","ケーキ"]'::jsonb, 0, 'Chú ý mốc thời gian: 「去年」(năm ngoái) tặng hoa → 「今年」(năm nay) tặng khăn tay (ハンカチ).', '母の日に何をあげますか。お花ですか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n5-5', 'listening', 'N5', 'listening', '何と言いますか。', null, '["すみません、ペンを貸してください。","すみません、ペンを借りてください。","すみません、ペンをあげてください。","すみません、ペンを教えてください。"]'::jsonb, 0, '「貸してください」= Hãy cho tôi mượn (đúng). Còn 「借りてください」= Bạn hãy đi mượn đi (sai hướng).', 'ペンを忘れました。友達のペンを使いたいです。何と言いますか。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n5-6', 'listening', 'N5', 'listening', '正しい返事を選んでください。', null, '["おじゃまします。","いってきます。","ごちそうさまでした。","おかえりなさい。"]'::jsonb, 0, 'Khi bước vào nhà người khác ở Nhật luôn nói 「おじゃまします」(Xin phép làm phiền).', 'いらっしゃい。どうぞ、お上がりください。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n4-1', 'listening', 'N4', 'listening', '女の人はこれからまず何をしますか。', null, '["会議室のエアコンをつける","資料をコピーする","お茶を入れる","机の上に資料を並べる"]'::jsonb, 0, 'Tài liệu đã xếp xong; trà để sau (あとでいい); việc cần làm NGAY trước tiên là bật điều hòa (エアコンをつけておいてください).', 'あと３０分でお客さんが来ます。資料のコピーは終わりましたか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n4-2', 'listening', 'N4', 'listening', '男の人はどの電車に乗りますか。', null, '["２番線の急行","１番線の普通","３番線の特急","バス"]'::jsonb, 0, 'Nam chốt chọn tàu tốc hành ở sân ga số 2 (２番線の急行).', 'すみません、空港まで行きたいんですが。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n4-3', 'listening', 'N4', 'listening', '男の人はどうして自転車で会社へ来るようになりましたか。', null, '["運動不足を解消し、健康のため","電車賃を節約するため","駅の近くへ引っ越したから","新しい自転車をもらったから"]'::jsonb, 0, 'Nam phủ định tiết kiệm tiền (いや) và nêu lý do thật: 「運動不足…健康のため」.', '最近、自転車で来ていますね。電車賃を節約しているんですか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n4-4', 'listening', 'N4', 'listening', '女の人が北海道で一番よかったと言っていることは何ですか。', null, '["新鮮な海の幸（食べ物）","きれいな雪景色","安いホテル","親切な地元の人々"]'::jsonb, 0, 'Cụm từ khóa 「何より…が最高でした」(hơn hết là ... tuyệt nhất) chỉ hải sản tươi sống (新鮮な海の幸).', '北海道旅行、どうでしたか。景色がきれいだったでしょう？
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n4-5', 'listening', 'N4', 'listening', '何と言いますか。', null, '["すみません、このメールをチェックしていただけませんか。","すみません、このメールをチェックしてあげましょうか。","すみません、このメールをチェックしてもいいですか。","すみません、このメールをチェックしましたか。"]'::jsonb, 0, 'Nhờ cấp trên/tiền bối làm giúp dùng mẫu kính ngữ 「〜ていただけませんか」(Anh/chị có thể ... giúp em không ạ?).', '書いたメールに間違いがないか、先輩に見てほしいです。何と言いますか。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n4-6', 'listening', 'N4', 'listening', '自然な返事を選んでください。', null, '["いいえ、まだまだです。","はい、とても上手です。","こちらこそ、おめでとうございます。","どういたしまして。"]'::jsonb, 0, 'Trong văn hóa khiêm tốn của Nhật, khi được khen luôn đáp 「いいえ、まだまだです」(Dạ không, em vẫn còn kém lắm ạ).', '最近、日本語がずいぶん上手になりましたね。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n3-1', 'listening', 'N3', 'listening', '女の人はこのあとまず何をしますか。', null, '["納品書の数字を確認する","すぐに相手先に電話する","５箱新しく注文する","荷物をすべて送り返す"]'::jsonb, 0, 'Trình tự hành động rõ ràng: 「まずは納品書の数字を確認して」(Trước tiên kiểm tra phiếu giao hàng) → rồi mới gọi điện.', '課長、さきほど届いた荷物なんですが、注文より５箱足りないんです。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n3-2', 'listening', 'N3', 'listening', '二人はどの店に決めましたか。', null, '["個室のある和食の店","駅前の安いイタリアンの店","会社の中の会議室","食べ放題の焼肉の店"]'::jsonb, 0, 'Nam đồng ý với đề xuất của Nữ và chốt đặt quán món Nhật có phòng riêng (個室のある和食の店).', '送別会の店、駅前のイタリアンはどう？個室はないけど安いよ。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n3-3', 'listening', 'N3', 'listening', '男の人が紙の手帳を使う一番の理由は何ですか。', null, '["自分で書くほうが予定をしっかり覚えられるから","スマホの電池がすぐ切れるから","紙の手帳のほうが軽くて安いから","会社でアプリの使用が禁止されているから"]'::jsonb, 0, 'Lý do chính được nhấn mạnh: 「自分の手で書くほうが予定をしっかり覚えられる」.', 'スマホのアプリじゃなくて、紙の手帳を使っているんですね。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n3-4', 'listening', 'N3', 'listening', 'このスーパーで最近変わったことは何ですか。', null, '["８割以上の客がエコバッグを持ってくるようになった","スーパーの売り上げが半分に減った","レジ袋を再び無料に戻した","プラスチック容器をすべて廃止した"]'::jsonb, 0, '「８割以上」= hơn 80% (1割 = 10%); 「持参する」= tự mang theo.', 'レジ袋を有料にしてから、お客さんの反応はいかがですか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n3-5', 'listening', 'N3', 'listening', 'この美術館の一番の特徴は何ですか。', null, '["ガラス張りの壁から作品と四季の景色を同時に楽しめること","入館料が一年中無料であること","１００年以上前に建てられた木造建築であること","館内で写真撮影や飲食が自由にできること"]'::jsonb, 0, 'Cụm khóa 「最大の特徴です」(đặc trưng lớn nhất là) gắn với tường kính ngắm tác phẩm cùng thiên nhiên 4 mùa.', 'この美術館は、建物の壁がすべてガラスでできており、作品だけでなく四季ごとの自然の景色も同時に楽しめるのが最大の特徴です。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('real-lis-n3-6', 'listening', 'N3', 'listening', '最も適切な返答を選んでください。', null, '["申し訳ありません、今仕上げているところで、あと１時間ほどで提出いたします。","いいえ、まだ出していませんから、待ってください。","お疲れ様でした、来週までに出しましょうか。","おかげさまで、もうすぐ忘れそうでした。"]'::jsonb, 0, 'Trong môi trường công sở Nhật, khi trễ hạn cần xin lỗi lịch sự (申し訳ありません) + báo rõ tiến độ hiện tại (今仕上げているところで) + hẹn thời gian nộp cụ thể (あと１時間ほどで提出いたします).', '先週頼んだ報告書、もう出してくれた？') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
